            .sink { [weak self] _ in
                self?.refreshVoiceCallEntryPreflight()
            }
            .store(in: &appModelCancellables)
        appModel.$selectedProjectId
            .sink { [weak self] _ in self?.refreshVoiceReadinessSnapshot() }
            .store(in: &appModelCancellables)
        appModel.$registry
            .sink { [weak self] _ in
                guard let self else { return }
                _ = self.syncSupervisorJurisdictionRegistry(with: self.knownProjects())
                self.rebuildVisibleRecentEvents()
                self.rebuildPendingSupervisorSkillApprovalViewState()
                self.scheduleSupervisorMemorySnapshotRefresh(reason: "registry_changed")
            }
            .store(in: &appModelCancellables)
        appModel.$skillsCompatibilitySnapshot
            .sink { [weak self] snapshot in
                guard let self else { return }
