    private func isProjectCreationDiagnosticQuestion(_ normalized: String) -> Bool {
        let trimmed = normalized.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        let compact = trimmed
            .replacingOccurrences(of: " ", with: "")
            .trimmingCharacters(in: CharacterSet.punctuationCharacters.union(.symbols))
        let mentionsProjectCreation = containsAny(
            compact,
            [
                "创建",
                "新建",
                "建项目",
                "建立",
                "创立",
                "createproject",
                "createaproject",
                "newproject"
            ]
        ) && (compact.contains("项目") || compact.contains("project"))
            || compact.contains("立项")
        let issueSignals = [
            "没反应",
            "无反应",
            "不创建",
            "创建不了",
            "建不了",
            "立不了",
            "不能创建",
            "不能建",
            "不能立",
            "无法创建",
            "无法建",
            "无法立",
            "失败",
            "没用",
            "不生效"
        ]
        let askSignals = [
            "为什么",
            "为啥",
            "怎么",
            "咋",
            "why"
        ]
        return mentionsProjectCreation
            && (issueSignals.contains(where: { compact.contains($0) })
                || askSignals.contains(where: { compact.contains($0) }))
    }

