        guard !commandScope.projects.isEmpty else {
            return "我现在还没有可读的项目 root。先选中项目，或者先把项目注册进来。"
        }

        guard let selection = focusedSupervisorProjectSelectionForRepoInspection(
            projects: commandScope.projects,
            userMessage: userMessage,
            pathCandidates: intent.rawPaths
        ) else {
            return renderSupervisorRepoInspectionProjectSelectionNeeded(projects: projects)
        }

        guard let ctx = projectContext(from: selection.project) else {
            return "我拿到了项目《\(selection.project.displayName)》，但它的 rootPath 当前不可用，所以这次没法直接读文件。"
        }

        switch intent.action {
        case .readFiles(let rawPaths):
            let limitedPaths = Array(rawPaths.prefix(6))
            let omittedCount = max(0, rawPaths.count - limitedPaths.count)
            var sections: [String] = []

            for rawPath in limitedPaths {
                let displayPath = cleanedSupervisorRepoPathCandidate(rawPath)
                let normalizedPath = normalizedSupervisorRepoInspectionPath(
                    rawPath,
                    projectRoot: ctx.root
                )
                let call = ToolCall(
                    tool: .read_file,
                    args: ["path": .string(normalizedPath)]
                )

                do {
                    let result = try await executeSupervisorDirectToolCall(
                        call,
                        projectRoot: ctx.root
                    )
                    sections.append(
                        renderSupervisorDirectReadSection(
                            displayPath: displayPath,
                            result: result
                        )
                    )
                } catch {
                    let failed = ToolResult(
                        id: call.id,
                        tool: call.tool,
                        ok: false,
                        output: error.localizedDescription
                    )
                    sections.append(
                        renderSupervisorDirectReadSection(
                            displayPath: displayPath,
                            result: failed
                        )
                    )
                }
            }

            appendRecentEvent(
                "repo_inspection_read: \(selection.project.displayName) files=\(limitedPaths.count)",
                project: selection.project
            )

            var lines = ["我已经直接读取《\(selection.project.displayName)》里的 \(limitedPaths.count) 个文件。"]
            if omittedCount > 0 {
                lines.append("还有 \(omittedCount) 个文件没展开；你继续说“把剩下的也读掉”就行。")
            }
            if !sections.isEmpty {
                lines.append(sections.joined(separator: "\n\n"))
            }
            return lines.joined(separator: "\n\n")

        case .listDirectory(let rawPath):
            let normalizedPath = normalizedSupervisorRepoInspectionPath(
                rawPath,
                projectRoot: ctx.root
            )
            let call = ToolCall(
                tool: .list_dir,
                args: ["path": .string(normalizedPath.isEmpty ? "." : normalizedPath)]
            )

            let result: ToolResult
            do {
                result = try await executeSupervisorDirectToolCall(
                    call,
                    projectRoot: ctx.root
                )
            } catch {
                result = ToolResult(
                    id: call.id,
                    tool: call.tool,
                    ok: false,
                    output: error.localizedDescription
                )
            }

            appendRecentEvent(
                "repo_inspection_list: \(selection.project.displayName) path=\(normalizedPath)",
                project: selection.project
            )
            return renderSupervisorDirectListDirectoryReply(
                project: selection.project,
                displayPath: cleanedSupervisorRepoPathCandidate(rawPath).isEmpty ? "." : cleanedSupervisorRepoPathCandidate(rawPath),
                result: result
            )
        }
    }

    private func directSupervisorAttachmentInspectionReplyIfApplicable(
        _ userMessage: String,
        currentTurnAttachments: [AXChatAttachment]
    ) -> String? {
        let candidates = supervisorAttachmentInspectionCandidates(
            currentTurnAttachments: currentTurnAttachments
        )
        guard !candidates.isEmpty,
              isSupervisorAttachmentInspectionRequest(
                userMessage,
                currentTurnAttachments: currentTurnAttachments,
                activeAttachments: candidates
              ) else {
            return nil
        }

        let appReports = candidates.compactMap {
            AXChatAttachmentAppInspectionSupport.macOSAppBundleReport(for: $0)
        }
        guard !appReports.isEmpty else { return nil }

        appendRecentEvent("attachment_inspection: app_bundle count=\(appReports.count)")
        if appReports.count == 1 {
            return appReports[0]
        }
        return appReports.enumerated()
            .map { index, report in
                "附件 \(index + 1)：\n\(report)"
            }
            .joined(separator: "\n\n")
    }

    private func supervisorAttachmentInspectionCandidates(
        currentTurnAttachments: [AXChatAttachment]
    ) -> [AXChatAttachment] {
        let current = AXChatAttachmentSupport.merge(
            existing: [],
            resolved: currentTurnAttachments
        )
        if !current.isEmpty {
            return current
        }

        for message in messages.reversed() where !message.attachments.isEmpty {
            return AXChatAttachmentSupport.merge(
                existing: [],
                resolved: message.attachments
            )
        }
        return []
    }

    private func isSupervisorAttachmentInspectionRequest(
        _ userMessage: String,
        currentTurnAttachments: [AXChatAttachment],
        activeAttachments: [AXChatAttachment]
    ) -> Bool {
        let normalized = normalizedSupervisorIntentText(userMessage)
        let normalizedKey = normalizedLookupKey(userMessage)
        guard !normalized.isEmpty || !normalizedKey.isEmpty else { return false }

        let asksForInspection = containsAny(normalized, [
            "逆向",
            "梳理",
            "功能",
            "能力",
            "菜单",
            "按钮",
            "界面",
            "资源文件",
            "配置",
            "字符串",
            "包结构",
            "有哪些",
            "干什么",
            "是什么",
            "info.plist",
            "contents/macos",
            "resources",
            "inspect",
            "reverse",
            "feature",
            "menu",
            "button",
            "ui",
            "string"
        ])
        guard asksForInspection else { return false }

        if !currentTurnAttachments.isEmpty {
            return true
        }

        if containsAny(normalized, [
            "附件",
            "刚发",
            "刚才发",
            "刚传",
            "我发的",
            "只读附件",
            "这个文件",
            "这个 app",
            "这个app",
            "这个应用",
            "app 包",
            "app包",
            "attached",
            "attachment"
        ]) {
            return true
        }

        return activeAttachments.contains { attachment in
            let nameKey = normalizedLookupKey(attachment.displayName)
            guard !nameKey.isEmpty else { return false }
            return normalizedKey.contains(nameKey)
        }
    }

    private func parseSupervisorRepoInspectionIntent(
        _ userMessage: String
    ) -> SupervisorRepoInspectionIntent? {
        let trimmed = userMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }

        let normalized = normalizedSupervisorIntentText(trimmed)
        let pathCandidates = extractSupervisorRepoPathCandidates(from: trimmed)

        if isDirectSupervisorDirectoryListRequest(
            normalized,
            pathCandidates: pathCandidates
        ) {
            let directoryPath = resolvedSupervisorDirectoryInspectionPath(
                userMessage: trimmed,
                pathCandidates: pathCandidates
            )
            return SupervisorRepoInspectionIntent(action: .listDirectory(directoryPath))
        }

        let fileCandidates = pathCandidates.filter(supervisorRepoPathLooksLikeFile)
        if isDirectSupervisorFileReadRequest(
            normalized,
            fileCandidates: fileCandidates
        ) {
            return SupervisorRepoInspectionIntent(action: .readFiles(fileCandidates))
        }

        return nil
    }

    private func isDirectSupervisorFileReadRequest(
        _ normalized: String,
        fileCandidates: [String]
    ) -> Bool {
        guard !fileCandidates.isEmpty else { return false }

        let strongSignals = [
            "读一下",
            "读取",
            "读这些文件",
            "读这几个文件",
            "打开文件",
            "查看文件",
            "看下文件",
            "看看文件",
            "文件内容",
            "read file",
            "read these files",
            "open file",
            "open these files",
            "file content",
            "cat "
        ]
        if containsAny(normalized, strongSignals) {
            return true
        }

        return containsAny(normalized, ["打开", "open ", "read "])
    }

    private func isDirectSupervisorDirectoryListRequest(
        _ normalized: String,
        pathCandidates: [String]
    ) -> Bool {
        guard hasSupervisorDirectoryInspectionTarget(
            normalized,
            pathCandidates: pathCandidates
        ) else {
            return false
        }

        let strongSignals = [
            "列一下",
            "列出",
            "看看目录",
            "查看目录",
            "目录内容",
            "list dir",
            "list directory",
            "show directory",
            "ls "
        ]
        if containsAny(normalized, strongSignals) {
            return true
        }

        return normalized.contains("目录") && containsAny(normalized, ["看", "列", "list", "open"])
    }

    private func hasSupervisorDirectoryInspectionTarget(
        _ normalized: String,
        pathCandidates: [String]
    ) -> Bool {
        if !pathCandidates.isEmpty {
            return true
        }
        if containsAny(normalized, [
            "项目根目录",
            "项目目录",
            "根目录",
            "当前目录",
            "工作区",
            "项目文件",
            "工程文件",
            "文件列表",
            "目录内容",
            "目录结构",
            "project root",
            "root dir",
            "workspace",
            "working tree",
            "repo root",
            "ls "
        ]) {
            return true
        }
        if normalized.contains("目录"),
           !containsAny(normalized, ["菜单", "按钮", "功能", "能力", "界面"]) {
            return true
        }
        return false
    }

    private func extractSupervisorRepoPathCandidates(from text: String) -> [String] {
        let patterns = [
            #"`[^`\n]+`"#,
            #"(?<![A-Za-z0-9_])(?:~?/)?[A-Za-z0-9._-]+(?:/[A-Za-z0-9._-]+)+/?(?=$|[\s,，。；;:：\)\]\}])"#,
            #"(?<![A-Za-z0-9_])(?:~?/)?[A-Za-z0-9._-]+\.[A-Za-z0-9._-]{1,12}(?=$|[\s,，。；;:：\)\]\}])"#
        ]

        var ordered: [String] = []
        var seen: Set<String> = []

        for pattern in patterns {
            for raw in regexMatches(in: text, pattern: pattern) {
                let cleaned = cleanedSupervisorRepoPathCandidate(raw)
                let key = cleaned.lowercased()
                guard shouldKeepSupervisorRepoPathCandidate(cleaned),
                      !seen.contains(key) else {
                    continue
                }
                ordered.append(cleaned)
                seen.insert(key)
            }
        }

        return filteredSupervisorRepoPathCandidates(ordered)
    }

    private func filteredSupervisorRepoPathCandidates(_ candidates: [String]) -> [String] {
        candidates.filter { candidate in
            let lowered = candidate.lowercased()
            return !candidates.contains { other in
                let otherLowered = other.lowercased()
                guard otherLowered != lowered else { return false }
                return otherLowered.hasSuffix("/" + lowered)
            }
        }
    }

    private func cleanedSupervisorRepoPathCandidate(_ raw: String) -> String {
        var cleaned = raw.trimmingCharacters(in: .whitespacesAndNewlines)

        let leadingTrim = CharacterSet(charactersIn: "`'\"“”‘’([{<")
        let trailingTrim = CharacterSet(charactersIn: "`'\"“”‘’)]}>.,，。；;:：!?！？")

        while let scalar = cleaned.unicodeScalars.first, leadingTrim.contains(scalar) {
            cleaned.removeFirst()
        }
        while let scalar = cleaned.unicodeScalars.last, trailingTrim.contains(scalar) {
            cleaned.removeLast()
        }

        if cleaned.hasPrefix("./"), cleaned.count > 2 {
            cleaned.removeFirst(2)
        }
        return cleaned.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func shouldKeepSupervisorRepoPathCandidate(_ candidate: String) -> Bool {
        guard !candidate.isEmpty else { return false }
        let lowered = candidate.lowercased()
        if lowered.contains("://") || lowered.hasPrefix("www.") {
            return false
        }
        if supervisorRepoPathLooksLikeDomain(candidate) {
            return false
        }
        if candidate.contains("/") {
            return true
        }
        return supervisorRepoPathLooksLikeFile(candidate)
    }

    private func supervisorRepoPathLooksLikeFile(_ candidate: String) -> Bool {
        let extensionToken = URL(fileURLWithPath: candidate).pathExtension
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        return !extensionToken.isEmpty && !supervisorRepoPathLooksLikeDomain(candidate)
    }

    private func supervisorRepoPathLooksLikeDomain(_ candidate: String) -> Bool {
        guard !candidate.contains("/") else { return false }
        let extensionToken = URL(fileURLWithPath: candidate).pathExtension
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard !extensionToken.isEmpty else { return false }
        let commonTLDs: Set<String> = [
            "ai", "app", "cn", "co", "com", "dev", "fm", "gg", "io", "me", "net", "org", "xyz"
        ]
        return commonTLDs.contains(extensionToken)
    }

    private func resolvedSupervisorDirectoryInspectionPath(
        userMessage: String,
        pathCandidates: [String]
    ) -> String {
        if let candidate = pathCandidates.first(where: { !supervisorRepoPathLooksLikeFile($0) }) {
            return candidate
        }

        let normalized = normalizedSupervisorIntentText(userMessage)
        if containsAny(normalized, ["项目根目录", "根目录", "当前目录", "project root", "root dir"]) {
            return "."
        }
        return pathCandidates.first ?? "."
    }

    private func focusedSupervisorProjectSelectionForRepoInspection(
        projects: [AXProjectEntry],
        userMessage: String,
        pathCandidates: [String]
    ) -> SupervisorFocusedProjectSelection? {
        if let selection = focusedSupervisorProjectSelection(
            projects: projects,
            userMessage: userMessage
        ) {
            return selection
        }

        let matches = projects.filter { project in
            let rootName = URL(fileURLWithPath: project.rootPath, isDirectory: true)
                .lastPathComponent
                .lowercased()
            guard !rootName.isEmpty else { return false }
            return pathCandidates.contains { candidate in
                let lowered = candidate.lowercased()
                return lowered == rootName || lowered.hasPrefix(rootName + "/")
            }
        }

        guard matches.count == 1, let matched = matches.first else { return nil }
        return SupervisorFocusedProjectSelection(
            project: matched,
            source: "path_root_basename"
        )
    }

    private func renderSupervisorRepoInspectionProjectSelectionNeeded(
        projects: [AXProjectEntry]
    ) -> String {
        let visibleProjects = projects.prefix(4).map(\.displayName).joined(separator: "、")
        if visibleProjects.isEmpty {
            return "这条像是在让我直接读项目文件，但当前没有可用项目。"
        }
        return """
这条像是在让我直接读项目文件，但当前项目不唯一，我不想替你猜。

你补项目名，或者先在侧栏选中项目后再说。当前可见项目：\(visibleProjects)。
"""
    }

    private func normalizedSupervisorRepoInspectionPath(
        _ rawPath: String,
        projectRoot: URL
    ) -> String {
        var cleaned = cleanedSupervisorRepoPathCandidate(rawPath)
        guard !cleaned.isEmpty else { return "." }

        let rootName = projectRoot.lastPathComponent.lowercased()
        let lowered = cleaned.lowercased()
        if lowered == rootName {
            return "."
        }
        if lowered.hasPrefix(rootName + "/") {
            cleaned = String(cleaned.dropFirst(rootName.count + 1))
        }

        let expanded = NSString(string: cleaned).expandingTildeInPath
        if expanded.hasPrefix("/") {
            let rootPath = projectRoot.standardizedFileURL.path
            let absolutePath = URL(fileURLWithPath: expanded).standardizedFileURL.path
            if absolutePath == rootPath {
                return "."
            }
            if absolutePath.hasPrefix(rootPath + "/") {
                let start = absolutePath.index(absolutePath.startIndex, offsetBy: rootPath.count + 1)
                return String(absolutePath[start...])
            }
            return expanded
        }

        return cleaned.isEmpty ? "." : cleaned
    }

    private func executeSupervisorDirectToolCall(
        _ call: ToolCall,
        projectRoot: URL,
        extraReadableRoots: [URL] = []
    ) async throws -> ToolResult {
        if let override = supervisorToolExecutorOverride {
            return try await override(call, projectRoot)
        }
        let readableRoots = extraReadableRoots.isEmpty
            ? supervisorAttachmentReadableRoots()
            : extraReadableRoots
        return try await ToolExecutor.execute(
            call: call,
            projectRoot: projectRoot,
            extraReadableRoots: readableRoots
        )
    }

    private func renderSupervisorDirectReadSection(
        displayPath: String,
        result: ToolResult
    ) -> String {
        let header = "[\(displayPath.isEmpty ? "(unknown path)" : displayPath)]"
        guard result.ok else {
            return header + "\n" + ToolResultHumanSummary.body(for: result)
        }
        let preview = supervisorDirectReadPreview(from: result.output)
        return header + "\n" + (preview.isEmpty ? "(empty file)" : preview)
    }

    private func renderSupervisorDirectListDirectoryReply(
        project: AXProjectEntry,
        displayPath: String,
        result: ToolResult
    ) -> String {
        let normalizedDisplayPath = displayPath == "." ? "project root" : displayPath
        guard result.ok else {
            return """
我试着列出《\(project.displayName)》里的 \(normalizedDisplayPath)，但这次没成功。

\(ToolResultHumanSummary.body(for: result))
"""
        }

        let cleaned = strippedSupervisorDirectToolOutput(result.output)
        let preview = cappedSupervisorMultilinePreview(cleaned, maxLines: 40, maxChars: 1_200)
        return """
我已经列出《\(project.displayName)》里的 \(normalizedDisplayPath)。

[\(displayPath == "." ? "." : displayPath)]
\(preview.isEmpty ? "(empty)" : preview)
"""
    }

    private func supervisorDirectReadPreview(from output: String) -> String {
        let cleaned = strippedSupervisorDirectToolOutput(output)
        guard !cleaned.isEmpty else { return "" }
        if cleaned.count <= 1_200 {
            return cleaned
        }

        let markdownPreview = supervisorMarkdownDocumentPreview(cleaned)
        if !markdownPreview.isEmpty {
            return markdownPreview
        }
        return cappedSupervisorMultilinePreview(cleaned, maxLines: 28, maxChars: 1_400)
    }

    private func strippedSupervisorDirectToolOutput(_ output: String) -> String {
        let prefix = "sandbox: true\n"
        let trimmed = output.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.hasPrefix(prefix) else { return trimmed }
        return String(trimmed.dropFirst(prefix.count)).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func supervisorMarkdownDocumentPreview(_ text: String) -> String {
        let lines = text.components(separatedBy: .newlines)
        var headings: [String] = []
        var paragraphChunks: [String] = []
        var inCodeFence = false

        for line in lines {
            let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed.hasPrefix("```") {
                inCodeFence.toggle()
                continue
            }
            if inCodeFence {
                continue
            }
            if trimmed.hasPrefix("#") {
                if headings.count < 6 {
                    headings.append(trimmed)
                }
                continue
            }
            if trimmed.isEmpty {
                if !paragraphChunks.isEmpty {
                    break
                }
                continue
            }
            if headings.isEmpty {
                continue
            }
            if trimmed.hasPrefix("- ")
                || trimmed.hasPrefix("* ")
                || trimmed.hasPrefix("> ")
                || trimmed.hasPrefix("1.") {
                if !paragraphChunks.isEmpty {
                    break
                }
                continue
            }
            paragraphChunks.append(trimmed)
            if paragraphChunks.joined(separator: " ").count >= 420 {
                break
            }
        }

        var sections: [String] = []
        if !headings.isEmpty {
            sections.append(headings.joined(separator: "\n"))
        }

        let paragraph = capped(
            paragraphChunks.joined(separator: " "),
            maxChars: 420
        )
        if !paragraph.isEmpty {
            sections.append(paragraph)
        }

        return sections.joined(separator: "\n\n")
    }

    private func cappedSupervisorMultilinePreview(
        _ text: String,
        maxLines: Int,
        maxChars: Int
    ) -> String {
        let normalized = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return "" }

        let lines = normalized.components(separatedBy: .newlines)
        let clippedLines = Array(lines.prefix(maxLines))
        var preview = clippedLines.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
        if preview.count > maxChars {
            preview = capped(preview, maxChars: maxChars)
        }
        if preview != normalized {
            preview += "\n..."
        }
        return preview
    }

    private func looksLikeSupervisorNaturalMemoryPatchFacts(_ userMessage: String) -> Bool {
        guard !isSupervisorStructuredWorkflowPayload(userMessage) else {
            return false
        }
        return parseSupervisorNaturalMemoryPatchIntent(
            userMessage,
            explicitRequest: false
        ).hasFacts
    }

    private func isSupervisorStructuredWorkflowPayload(_ text: String) -> Bool {
        let lowered = text.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !lowered.isEmpty else { return false }

        if lowered.contains("workflow_focus:") ||
            lowered.contains("active_plan_steps:") ||
            lowered.contains("next_pending_steps:") ||
            lowered.contains("attention_steps:") {
            return true
        }

        let keyedMarkers = [
            "trigger=",
            "project_ref=",
            "project_id=",
            "job_id=",
            "plan_id=",
            "step_id=",
            "request_id=",
            "skill_id=",
            "tool_name=",
            "review_trigger=",
            "review_level_hint=",
            "review_run_kind=",
            "active_job_goal=",
            "active_job_status=",
            "active_plan_id=",
            "active_plan_status="
        ]
        let hitCount = keyedMarkers.reduce(into: 0) { count, marker in
            if lowered.contains(marker) {
                count += 1
            }
        }
        return hitCount >= 3
    }

    private func renderFocusedSupervisorNaturalBrief(_ project: AXProjectEntry) -> String {
        let runtime = runtimeStatus(for: project)
        let blocker = (project.blockerSummary ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let next = (project.nextStepSummary ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let pendingGrantCount = pendingHubGrants.filter { $0.projectId == project.projectId }.count

        var lines = [
            "我来简短说一下《\(project.displayName)》。",
            "现在状态：\(runtime.text)。"
        ]

        if !blocker.isEmpty {
            lines.append("当前卡点：\(capped(blocker, maxChars: 72))。")
        }
        if pendingGrantCount > 0 {
            lines.append("还有 \(pendingGrantCount) 个待授权项卡在路上。")
        }
        if !next.isEmpty && !isDigestPlaceholder(next, treatContinueCurrentTaskAsPlaceholder: true) {
            lines.append("我建议下一步先\(capped(next, maxChars: 72))。")
        } else {
            lines.append("下一步还不够具体，我建议先补一条更明确的执行动作。")
        }

        return appendingSupervisorCalendarReminderAsideIfNeeded(
            lines.joined(separator: "\n")
        )
    }

    private func directSupervisorPendingGuidanceAckIfApplicable(
        _ userMessage: String,
        projects: [AXProjectEntry]
    ) -> String? {
        guard let status = naturalSupervisorGuidanceAckStatus(in: userMessage) else { return nil }
        let commandScope = supervisorCommandProjectScope(
            projects: projects,
            userMessage: userMessage
        )

        let candidates = pendingSupervisorGuidanceCandidates(projects: commandScope.projects)
        guard !candidates.isEmpty else { return nil }

        var filtered = candidates
        if let requestedInjectionID = supervisorTriggerContextValue(
            "injection_id",
            userMessage: userMessage
        )?.trimmingCharacters(in: .whitespacesAndNewlines),
           !requestedInjectionID.isEmpty {
            let lowered = requestedInjectionID.lowercased()
            filtered = filtered.filter { candidate in
                let injectionId = candidate.guidance.injectionId.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                return injectionId == lowered ||
                    injectionId.contains(lowered) ||
                    lowered.contains(injectionId)
            }
            guard !filtered.isEmpty else {
                return "我没找到 injection_id=\(requestedInjectionID) 对应的待确认 guidance。"
            }
        }

        if let focus = commandScope.selection {
            let projectMatches = filtered.filter { $0.project.projectId == focus.project.projectId }
            guard !projectMatches.isEmpty else {
                return "项目 \(focus.project.displayName) 当前没有待确认 guidance。"
            }
            filtered = projectMatches
        }

        guard filtered.count == 1, let resolved = filtered.first else {
            return renderPendingSupervisorGuidanceAckAmbiguityReply(filtered)
        }

        return acknowledgePendingSupervisorGuidanceDirectly(
            guidance: resolved.guidance,
            status: status,
            project: resolved.project,
            ctx: resolved.ctx,
            sourceText: userMessage
        )
    }

    private func naturalSupervisorGuidanceAckStatus(
        in userMessage: String
    ) -> SupervisorGuidanceAckStatus? {
        let normalized = normalizedLookupKey(userMessage)
        guard !normalized.isEmpty else { return nil }

        let hasGuidanceSubject = normalizedContainsAny(
            normalized,
            ["建议", "方案", "方向", "guidance", "review"]
        )
        let hasGuidanceContext = hasRecentSupervisorGuidanceContext(
            currentUserMessage: userMessage
        )
        let hasGuidanceReference = hasGuidanceSubject ||
            normalizedContainsAny(normalized, ["这个", "这条"]) ||
            hasGuidanceContext

        if normalizedContainsAny(
            normalized,
            [
                "按这个做",
                "照这个做",
                "按这个推进",
                "照这个推进",
                "就这么做",
                "就这么办",
                "那就按这个来",
                "就按这个来",
                "按你说的来",
                "照这个方案走",
                "按这个方案走"
            ]
        ) || (hasGuidanceReference && normalizedContainsAny(normalized, ["接受", "采用", "可以", "同意", "行", "好"])) {
            return .accepted
        }

        if normalizedContainsAny(
            normalized,
            [
                "先放一下",
                "先搁置",
                "稍后",
                "晚点",
                "回头",
                "之后再",
                "defer",
                "延后",
                "先缓一缓",
                "先缓缓",
                "先挂着",
                "先挂起",
                "先别动这个",
                "等我再看",
                "先等等"
            ]
        ) && hasGuidanceReference {
            return .deferred
        }

        if normalizedContainsAny(
            normalized,
            [
                "别按这个做",
                "换个方向",
                "重新想方案",
                "不要这个方案",
                "别走这条",
                "这个路子不对",
                "这条先别走",
                "换条路",
                "推翻这个方案"
            ]
        ) || (hasGuidanceReference && normalizedContainsAny(normalized, ["不行", "不对", "驳回", "否掉", "reject", "不要"])) {
            return .rejected
        }

        return nil
    }

    private func pendingSupervisorGuidanceCandidates(
        projects: [AXProjectEntry]
    ) -> [(project: AXProjectEntry, ctx: AXProjectContext, guidance: SupervisorGuidanceInjectionRecord)] {
        projects.compactMap { project in
            let ctx = supervisorMemoryContext(for: project)
            guard let guidance = SupervisorGuidanceInjectionStore.latestPendingAck(for: ctx) else {
                return nil
            }
            return (project, ctx, guidance)
        }
    }

    private func renderPendingSupervisorGuidanceAckAmbiguityReply(
        _ candidates: [(project: AXProjectEntry, ctx: AXProjectContext, guidance: SupervisorGuidanceInjectionRecord)]
    ) -> String {
        let lines = candidates.prefix(3).enumerated().map { offset, candidate in
            "\(offset + 1). \(candidate.project.displayName) / \(SupervisorGuidanceTextPresentation.summary(candidate.guidance.guidanceText, maxChars: 56)) / injection=\(candidate.guidance.injectionId)"
        }
        return ([
            "当前有多条待确认 guidance，我不想替你盲选。",
        ] + lines + [
            "补一句项目名，或者直接给 `injection_id=...`。"
        ]).joined(separator: "\n")
    }

    private func acknowledgePendingSupervisorGuidanceDirectly(
        guidance: SupervisorGuidanceInjectionRecord,
        status: SupervisorGuidanceAckStatus,
        project: AXProjectEntry,
        ctx: AXProjectContext,
        sourceText: String
    ) -> String {
        let normalizedNote = naturalSupervisorGuidanceAckNote(
            sourceText: sourceText,
            status: status
        )
        let nowMs = Int64((Date().timeIntervalSince1970 * 1000.0).rounded())

        do {
            try SupervisorGuidanceInjectionStore.acknowledge(
                injectionId: guidance.injectionId,
                status: status,
                note: normalizedNote,
                atMs: nowMs,
                for: ctx
            )
            AXProjectStore.appendRawLog(
                [
                    "type": "supervisor_guidance_ack",
                    "action": "manual_ack",
                    "source": "supervisor_direct_natural_language",
                    "project_id": guidance.projectId,
                    "review_id": guidance.reviewId,
                    "injection_id": guidance.injectionId,
                    "ack_status": status.rawValue,
                    "ack_note": normalizedNote,
                    "ack_required": guidance.ackRequired,
                    "timestamp_ms": nowMs
                ],
                for: ctx
            )

            if let updated = SupervisorGuidanceInjectionStore.load(for: ctx).items.first(where: {
                $0.injectionId == guidance.injectionId
            }) {
                handleEvent(.supervisorGuidanceAck(updated))
            }

            let guidanceSummary = SupervisorGuidanceTextPresentation.summary(
                guidance.guidanceText,
                maxChars: 60
            )
            return frontstageSupervisorGuidanceAckReply(
                projectName: project.displayName,
                status: status,
                guidanceSummary: guidanceSummary
            )
        } catch {
            return "更新《\(project.displayName)》的指导确认失败：\(String(describing: error))"
        }
    }

    private func frontstageSupervisorGuidanceAckReply(
        projectName: String,
        status: SupervisorGuidanceAckStatus,
        guidanceSummary: String
    ) -> String {
        let normalizedProjectName = projectName.trimmingCharacters(in: .whitespacesAndNewlines)
        let target = normalizedProjectName.isEmpty ? "当前项目" : "《\(normalizedProjectName)》"
        let summary = userFacingSupervisorGuidanceAckSummary(guidanceSummary)

        switch status {
        case .accepted:
            if summary.isEmpty {
                return "收到，\(target)这条指导我先按这个方向处理。"
            }
            return "收到，\(target)这条指导我先按这个方向处理：\(summary)"
        case .deferred:
            if summary.isEmpty {
                return "收到，\(target)这条指导我先放一放，稍后再接着处理。"
            }
            return "收到，\(target)这条指导我先放一放，稍后再接着处理：\(summary)"
        case .rejected:
            if summary.isEmpty {
                return "收到，\(target)这条指导先不按这个方向走，我重新评估。"
            }
            return "收到，\(target)这条指导先不按这个方向走，我重新评估：\(summary)"
        case .pending:
            return "\(target)这条指导目前还是待确认状态。"
        }
    }

    private func userFacingSupervisorGuidanceAckSummary(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }
        let lowered = trimmed.lowercased()
        if lowered.contains("serving contract") ||
            trimmed.contains("Supervisor 实际注入") ||
            trimmed.contains("记忆装配未通过运行时校验") ||
            (lowered.contains("strategic memory") && trimmed.contains("供给不足")) {
            return ""
        }
        return trimmed
    }

    private func naturalSupervisorGuidanceAckNote(
        sourceText: String,
        status: SupervisorGuidanceAckStatus
    ) -> String {
        let trimmed = capped(
            sourceText.trimmingCharacters(in: .whitespacesAndNewlines),
            maxChars: 180
        )
        guard !trimmed.isEmpty else {
            switch status {
            case .accepted:
                return "natural_accept_from_supervisor"
            case .deferred:
                return "natural_defer_from_supervisor"
            case .rejected:
                return "natural_reject_from_supervisor"
            case .pending:
                return "natural_pending_from_supervisor"
            }
        }
        return trimmed
    }

    private func directSupervisorPendingGrantActionIfApplicable(
        _ userMessage: String,
        projects: [AXProjectEntry]
    ) -> String? {
        guard !looksLikeSupervisorNaturalMemoryPatchFacts(userMessage) else { return nil }
        guard let approve = pendingGrantTextDecision(in: userMessage) else { return nil }
        guard !pendingHubGrants.isEmpty else {
            return XTHubGrantPresentation.emptyPendingReply(projectName: nil)
        }

        let selection = resolvePendingHubGrantForVoiceAction(userMessage, projects: projects)
        if let reply = selection.reply {
            return reply
        }
        guard let grant = selection.grant else { return nil }

        let grantId = grant.grantRequestId.trimmingCharacters(in: .whitespacesAndNewlines)
        if !grantId.isEmpty, pendingHubGrantActionsInFlight.contains(grantId) {
            let summary = pendingGrantSummaryLine(
                grant,
                includeGrantToken: true,
                includeScope: false,
                includeReason: false
            )
            return "这笔 Hub 授权正在处理中：\(summary)。"
        }

        performPendingHubGrantAction(grant, approve: approve)
        let capabilityText = grantCapabilityText(
            capability: grant.capability,
            modelId: grant.modelId
        )
        let scopeSentence = pendingGrantScopeText(grant).map { "\($0)。" } ?? ""
        if approve {
            return "收到，我开始处理《\(grant.projectName)》的\(capabilityText) Hub 授权了。\(scopeSentence)结果回来后我继续汇报。"
        }
        return "收到，我先拦下《\(grant.projectName)》的\(capabilityText) Hub 授权。\(scopeSentence)结果会回写到系统。"
    }

    private func directSupervisorPendingSkillApprovalActionIfApplicable(
        _ userMessage: String,
        projects: [AXProjectEntry]
    ) -> String? {
        guard !looksLikeSupervisorNaturalMemoryPatchFacts(userMessage) else { return nil }
        guard let approve = pendingSupervisorSkillApprovalDecision(in: userMessage) else {
            return nil
        }

        let selection = resolvePendingSupervisorSkillApprovalForDirectAction(
            userMessage,
            projects: projects
        )
        if let reply = selection.reply {
            return reply
        }
        guard let approval = selection.approval else { return nil }
        let replyContext = directSupervisorPendingSkillApprovalReplyContext(approval)

        if approve {
            approvePendingSupervisorSkillApproval(approval)
            return directSupervisorPendingSkillApprovalApproveReply(
                approval,
                context: replyContext
            )
        }

        denyPendingSupervisorSkillApproval(approval)
        return directSupervisorPendingSkillApprovalDenyReply(
            approval,
            context: replyContext
        )
    }

    private func directSupervisorPendingSkillApprovalReplyContext(
        _ approval: SupervisorPendingSkillApproval
    ) -> DirectSupervisorPendingSkillApprovalReplyContext {
        let activityItem = SupervisorSkillActivityPresentation.governedSkillPresentationItem(
            for: approval
        )
        let message = XTPendingApprovalPresentation.approvalMessage(
            toolName: approval.toolName,
            tool: approval.tool,
            toolSummary: approval.toolSummary,
            activity: activityItem
        )
        let deltaLines = XTPendingApprovalPresentation.approvalProfileDeltaLines(
            for: activityItem
        )
        return DirectSupervisorPendingSkillApprovalReplyContext(
            mode: pendingSupervisorSkillAuthorizationMode(for: approval),
            displaySummary: supervisorPendingApprovalDisplaySummary(approval),
            deltaHeadline: directSupervisorPendingSkillApprovalDeltaHeadline(
                from: deltaLines
            ),
            gateLine: deltaLines.first(where: { $0.hasPrefix("授权门槛：") }),
            digestContext: supervisorPendingApprovalDigestContext(approval),
            nextStep: message.nextStep
        )
    }

    private func directSupervisorPendingSkillApprovalApproveReply(
        _ approval: SupervisorPendingSkillApproval,
        context: DirectSupervisorPendingSkillApprovalReplyContext
    ) -> String {
        var lines: [String] = []
        switch context.mode {
        case .localApproval:
            lines.append("收到，我开始批准《\(approval.projectName)》的技能调用了：\(context.displaySummary)")
            if let deltaHeadline = directSupervisorPendingSkillApprovalNonEmpty(
                context.deltaHeadline
            ) {
                lines.append("能力增量：\(deltaHeadline)")
            }
            lines.append("通过后我继续往下执行")
        case .hubGrant:
            lines.append("收到，《\(approval.projectName)》这条技能授权待处理项当前还不能直接放行：\(context.displaySummary)")
            if let deltaHeadline = directSupervisorPendingSkillApprovalNonEmpty(
                context.deltaHeadline
            ) {
                lines.append("能力增量：\(deltaHeadline)")
            }
            if let gateLine = directSupervisorPendingSkillApprovalNonEmpty(
                context.gateLine
            ) {
                lines.append(gateLine)
            }
            if let nextStep = directSupervisorPendingSkillApprovalNonEmpty(
                context.nextStep
            ) {
                lines.append(nextStep)
            } else {
                lines.append("先完成 Hub grant，再恢复这次受治理技能调用")
            }
        case .blocked:
            lines.append("收到，《\(approval.projectName)》这条技能治理待处理项当前还不能直接放行：\(context.displaySummary)")
            if let digestContext = directSupervisorPendingSkillApprovalNonEmpty(
                context.digestContext
            ) {
                lines.append(digestContext)
            }
            if let gateLine = directSupervisorPendingSkillApprovalNonEmpty(
                context.gateLine
            ) {
                lines.append(gateLine)
            }
            lines.append("请先按阻塞提示处理，我再继续往下推进")
        }
        return directSupervisorPendingSkillApprovalReplyText(lines)
    }

    private func directSupervisorPendingSkillApprovalDenyReply(
        _ approval: SupervisorPendingSkillApproval,
        context: DirectSupervisorPendingSkillApprovalReplyContext
    ) -> String {
        var lines: [String] = [
            "收到，我先拦下《\(approval.projectName)》的技能调用：\(context.displaySummary)"
        ]
        if let deltaHeadline = directSupervisorPendingSkillApprovalNonEmpty(
            context.deltaHeadline
        ) {
            lines.append("能力增量：\(deltaHeadline)")
        } else if let digestContext = directSupervisorPendingSkillApprovalNonEmpty(
            context.digestContext
        ) {
            lines.append(digestContext)
        }
        lines.append("系统会把这次拒绝写回 workflow")
        return directSupervisorPendingSkillApprovalReplyText(lines)
    }

    private func directSupervisorPendingSkillApprovalDeltaHeadline(
        from lines: [String]
    ) -> String? {
        lines.first(where: { $0.hasPrefix("新增放开：") })
            ?? lines.first(where: { $0.hasPrefix("本次请求：") })
            ?? lines.first(where: { $0.hasPrefix("当前可直接运行：") })
    }

    private func directSupervisorPendingSkillApprovalReplyText(
        _ lines: [String]
    ) -> String {
        lines.compactMap {
            directSupervisorPendingSkillApprovalSentence($0)
        }
        .joined()
    }

    private func directSupervisorPendingSkillApprovalSentence(
        _ raw: String?
    ) -> String? {
        guard let value = directSupervisorPendingSkillApprovalNonEmpty(raw) else {
            return nil
        }
        guard let last = value.last else { return value }
        switch last {
        case "。", "！", "？":
            return value
        default:
            return value + "。"
        }
    }

    private func directSupervisorPendingSkillApprovalNonEmpty(
        _ raw: String?
    ) -> String? {
        let trimmed = (raw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private func pendingSupervisorSkillApprovalDecision(
        in text: String
    ) -> Bool? {
        let normalized = normalizedLookupKey(text)
        guard !normalized.isEmpty else { return nil }

        let hasContext = hasRecentSupervisorPendingSkillApprovalContext(
            currentUserMessage: text
        )
        let explicitRequestId = explicitPendingSupervisorSkillRequestId(in: text) != nil
        let hasStrongSubject = normalizedContainsAny(
            normalized,
            pendingSupervisorSkillApprovalSubjectTokens()
        )
        let hasApprove = normalizedContainsAny(
            normalized,
            pendingSupervisorSkillApprovalApproveTokens()
        )
        let hasDeny = normalizedContainsAny(
            normalized,
            pendingSupervisorSkillApprovalDenyTokens()
        )

        if hasApprove != hasDeny {
            guard explicitRequestId || hasStrongSubject || hasContext else {
                return nil
            }
            return hasApprove
        }

        let hasImplicitSinglePendingContext = pendingSupervisorSkillApprovals.count == 1
        guard hasContext || hasImplicitSinglePendingContext else { return nil }
        let contextualApprove = normalizedContainsAny(
            normalized,
            pendingSupervisorSkillApprovalContextualApproveTokens()
        )
        let contextualDeny = normalizedContainsAny(
            normalized,
            pendingSupervisorSkillApprovalContextualDenyTokens()
        )
        guard contextualApprove != contextualDeny else { return nil }
        return contextualApprove
    }

