    func pendingSupervisorSkillAuthorizationMode(
        readiness: XTSkillExecutionReadiness?,
        requiredCapability: String? = nil
    ) -> SupervisorPendingSkillAuthorizationMode {
        let readinessState = readiness?.executionReadiness
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased() ?? ""
        let capability = requiredCapability?.trimmingCharacters(
            in: .whitespacesAndNewlines
        ) ?? ""
        switch readinessState {
        case XTSkillExecutionReadinessState.grantRequired.rawValue:
            return .hubGrant
        case XTSkillExecutionReadinessState.localApprovalRequired.rawValue:
            return .localApproval
        case "",
             XTSkillExecutionReadinessState.ready.rawValue,
             XTSkillExecutionReadinessState.degraded.rawValue:
            return capability.isEmpty ? .localApproval : .hubGrant
        default:
            return .blocked
        }
    }

    func pendingSupervisorSkillAuthorizationMode(
        for approval: SupervisorPendingSkillApproval
    ) -> SupervisorPendingSkillAuthorizationMode {
        SupervisorPendingSkillApprovalPresentation.authorizationMode(for: approval)
