    private func shouldRepromptPendingSupervisorMemoryFactFollowUp(
        _ userMessage: String,
        normalized: String,
        explicitRequest: Bool,
        followUp: SupervisorPendingMemoryFactFollowUp
    ) -> Bool {
        if explicitRequest {
            return true
        }
        if looksLikeSupervisorNaturalMemoryPatchFacts(userMessage) {
            return true
        }
        if shouldCollectNaturalFactsBeforeStrategicReview(normalized) {
            return true
        }
        if normalizedContainsAny(
            normalized,
            [
                "继续",
                "继续补",
                "继续问",
                "接着",
                "下一项",
                "下一条",
                "下一个",
                "然后呢",
                "你继续",
                "继续这个",
                "继续这个补充",
                "继续这个背景",
                "继续补这个",
                "再问一项",
                "再补一项",
                "下一个问题",
                "继续收集",
                "继续补背景",
                "继续补记忆",
                "继续补上下文",
                "好你问",
                "你问吧",
                "问吧",
                "继续吧",
                "go on",
                "continue",
                "continue this",
                "next one",
                "next question"
            ]
        ) {
            return true
        }

        let projectAliases = normalizedSupervisorProjectAliasTerms(
            displayNameForPendingSupervisorMemoryFactFollowUp(followUp) ?? ""
        )
        let referencesPendingProject = !projectAliases.isEmpty && projectAliases.contains { alias in
            normalized.contains(alias)
        }
        if referencesPendingProject && normalizedContainsAny(
            normalized,
            [
                "背景",
                "项目背景",
                "上下文",
                "记忆",
                "补充",
                "补档",
                "review",
                "审查",
                "审阅",
                "纠偏"
            ]
        ) {
            return true
        }

        return false
    }

    private func pendingSupervisorMemoryFactFollowUpCategories(
        for readiness: SupervisorMemoryAssemblyReadiness
    ) -> [SupervisorMemoryFactFollowUpCategory] {
        let issueCodes = Set(readiness.issueCodes)
        var categories: [SupervisorMemoryFactFollowUpCategory] = []

        if issueCodes.isEmpty {
            categories.append(contentsOf: SupervisorMemoryFactFollowUpCategory.allCases)
        }
        if issueCodes.contains("memory_review_floor_not_met") ||
            issueCodes.contains("memory_strategic_anchor_underfed") ||
            issueCodes.contains("memory_core_layers_truncated") ||
            issueCodes.contains("memory_continuity_floor_not_met") {
            categories.append(contentsOf: [.goalAndDone, .decision, .blocker])
        }
        if issueCodes.contains("memory_review_floor_not_met") ||
            issueCodes.contains("memory_strategic_anchor_underfed") ||
            issueCodes.contains("memory_focus_evidence_missing") {
            categories.append(.evidence)
        }

        var ordered: [SupervisorMemoryFactFollowUpCategory] = []
        for category in categories where !ordered.contains(category) {
            ordered.append(category)
        }
        return ordered
    }

    private func installPendingSupervisorMemoryFactFollowUp(
        projectId: String?,
        projectName: String?,
        issueSummary: String?,
        categories: [SupervisorMemoryFactFollowUpCategory]
    ) -> SupervisorPendingMemoryFactFollowUp {
        let now = Date().timeIntervalSince1970
        rememberPendingSupervisorMemoryFactFollowUpProjectName(
            projectId: projectId,
            projectName: projectName
        )
        let followUp = SupervisorPendingMemoryFactFollowUp(
            projectId: projectId,
            projectName: projectName,
            issueSummary: issueSummary,
            remainingCategories: categories,
            createdAt: now,
            updatedAt: now
        )
        pendingSupervisorMemoryFactFollowUp = followUp
        publishPendingSupervisorMemoryFactFollowUpState(followUp)
        return followUp
    }

    private func activeSupervisorMemoryFactFollowUp() -> SupervisorPendingMemoryFactFollowUp? {
        guard let followUp = pendingSupervisorMemoryFactFollowUp else { return nil }
        let now = Date().timeIntervalSince1970
        if now - followUp.updatedAt > supervisorEllipsisContextCarryWindowSec {
            clearPendingSupervisorMemoryFactFollowUp()
            return nil
        }
        publishPendingSupervisorMemoryFactFollowUpState(followUp)
        return followUp
    }

    private func clearPendingSupervisorMemoryFactFollowUp() {
        pendingSupervisorMemoryFactFollowUp = nil
        publishPendingSupervisorMemoryFactFollowUpState(nil)
    }

    private func rememberPendingSupervisorMemoryFactFollowUpProjectName(
        projectId: String?,
        projectName: String?
    ) {
        let normalizedProjectID = projectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let normalizedProjectName = projectName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !normalizedProjectID.isEmpty,
              !normalizedProjectName.isEmpty,
              normalizedProjectName != normalizedProjectID else {
            return
        }
        pendingSupervisorMemoryFactFollowUpProjectNameCache[normalizedProjectID] = normalizedProjectName
    }

    private func resolvedPendingSupervisorMemoryFactFollowUpProjectName(
        existing: String?,
        project: AXProjectEntry
    ) -> String {
        let existingName = existing?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let displayName = project.displayName.trimmingCharacters(in: .whitespacesAndNewlines)
        let projectID = project.projectId.trimmingCharacters(in: .whitespacesAndNewlines)

        if !displayName.isEmpty, displayName != projectID {
            return displayName
        }
        if !existingName.isEmpty {
            return existingName
        }
        if !displayName.isEmpty {
            return displayName
        }
        return projectID
    }

    private func displayNameForPendingSupervisorMemoryFactFollowUp(
        _ followUp: SupervisorPendingMemoryFactFollowUp
    ) -> String? {
        let projectID = followUp.projectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let projectName = followUp.projectName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let registryProjects = AXProjectRegistryStore
            .sanitizeLoadedRegistry(appModel?.registry ?? AXProjectRegistryStore.load())
            .registry
            .projects

        if !projectName.isEmpty, projectName != projectID {
            return projectName
        }

        if !projectID.isEmpty,
           let cached = pendingSupervisorMemoryFactFollowUpProjectNameCache[projectID],
           !cached.isEmpty {
            return cached
        }

        if !projectID.isEmpty,
           let resolved = registryProjects.first(where: { $0.projectId == projectID })?.displayName
            .trimmingCharacters(in: .whitespacesAndNewlines),
           !resolved.isEmpty,
           resolved != projectID {
            return resolved
        }

        let selectedProjectID = appModel?.selectedProjectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !selectedProjectID.isEmpty,
           let selectedDisplayName = registryProjects.first(where: { $0.projectId == selectedProjectID })?.displayName
            .trimmingCharacters(in: .whitespacesAndNewlines),
           !selectedDisplayName.isEmpty,
           selectedDisplayName != selectedProjectID {
            return selectedDisplayName
        }

        if !projectName.isEmpty {
            return projectName
        }
        if !projectID.isEmpty {
            return projectID
        }
        return nil
    }

    private func supervisorProjectSelectionForPendingMemoryFactFollowUp(
        _ followUp: SupervisorPendingMemoryFactFollowUp,
        projects: [AXProjectEntry]
    ) -> SupervisorFocusedProjectSelection? {
        guard let projectId = followUp.projectId,
              let project = projects.first(where: { $0.projectId == projectId }) else {
            return nil
        }
        return SupervisorFocusedProjectSelection(
            project: project,
            source: "pending_memory_fact_follow_up"
        )
    }

    private func bindPendingSupervisorMemoryFactFollowUp(
        to project: AXProjectEntry
    ) -> SupervisorPendingMemoryFactFollowUp? {
        guard var followUp = activeSupervisorMemoryFactFollowUp() else { return nil }
        followUp.projectId = project.projectId
        followUp.projectName = resolvedPendingSupervisorMemoryFactFollowUpProjectName(
            existing: followUp.projectName,
            project: project
        )
        rememberPendingSupervisorMemoryFactFollowUpProjectName(
            projectId: followUp.projectId,
            projectName: followUp.projectName
        )
        followUp.updatedAt = Date().timeIntervalSince1970
        pendingSupervisorMemoryFactFollowUp = followUp
        publishPendingSupervisorMemoryFactFollowUpState(followUp)
        return followUp
    }

    private func publishPendingSupervisorMemoryFactFollowUpState(
        _ followUp: SupervisorPendingMemoryFactFollowUp?
    ) {
        let previousReminderFingerprint = supervisorPendingMemoryFactFollowUpReminderFingerprint
        guard let followUp,
              let nextCategory = followUp.remainingCategories.first else {
            clearSupervisorMemoryFactFollowUpReminder(
                fingerprint: previousReminderFingerprint,
                removeLocalNotification: true
            )
            supervisorPendingMemoryFactFollowUpStatusLine = "memory follow-up: idle"
            supervisorPendingMemoryFactFollowUpQuestion = ""
            supervisorPendingMemoryFactFollowUpReminderFingerprint = ""
            return
        }

        let projectLabel = displayNameForPendingSupervisorMemoryFactFollowUp(followUp)
        let remainingCount = followUp.remainingCategories.count
        if let projectLabel, !projectLabel.isEmpty {
            supervisorPendingMemoryFactFollowUpStatusLine = "memory follow-up: \(projectLabel) / remaining=\(remainingCount)"
        } else {
            supervisorPendingMemoryFactFollowUpStatusLine = "memory follow-up: project_unresolved / remaining=\(remainingCount)"
        }
        supervisorPendingMemoryFactFollowUpQuestion = nextCategory.question
        syncPendingSupervisorMemoryFactFollowUpReminderIfNeeded(
            followUp,
            nextCategory: nextCategory,
            previousFingerprint: previousReminderFingerprint
        )
    }

    private func syncPendingSupervisorMemoryFactFollowUpReminderIfNeeded(
        _ followUp: SupervisorPendingMemoryFactFollowUp,
        nextCategory: SupervisorMemoryFactFollowUpCategory,
        previousFingerprint: String
    ) {
        let reminder = pendingSupervisorMemoryFactFollowUpReminder(
            for: followUp,
            nextCategory: nextCategory
        )
        supervisorPendingMemoryFactFollowUpReminderFingerprint = reminder.fingerprint
        HubIPCClient.removeNotification(dedupeKey: reminder.notificationIdentifier)
        guard reminder.fingerprint != previousFingerprint else { return }
        clearSupervisorMemoryFactFollowUpReminder(
            fingerprint: previousFingerprint,
            removeLocalNotification: true
        )
        if let override = supervisorMemoryFollowUpReminderOverrideForTesting {
            override(reminder.title, reminder.body, reminder.actionURL)
            return
        }
        guard backgroundSupervisorServicesEnabled else { return }
        postLocalSupervisorMemoryFollowUpNotification(reminder)
    }

    private func clearSupervisorMemoryFactFollowUpReminder(
        fingerprint: String,
        removeLocalNotification: Bool
    ) {
        let trimmed = fingerprint.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        let identifier = "x_terminal_supervisor_memory_follow_up_\(trimmed)"
        HubIPCClient.removeNotification(dedupeKey: identifier)
        guard removeLocalNotification, canPostLocalSupervisorNotifications() else { return }
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: [identifier])
        UNUserNotificationCenter.current().removeDeliveredNotifications(withIdentifiers: [identifier])
    }

    private func pendingSupervisorMemoryFactFollowUpReminder(
        for followUp: SupervisorPendingMemoryFactFollowUp,
        nextCategory: SupervisorMemoryFactFollowUpCategory
    ) -> SupervisorMemoryFactFollowUpReminder {
        let projectID = followUp.projectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let projectName = displayNameForPendingSupervisorMemoryFactFollowUp(followUp) ?? ""
        let stableScope: String = {
            if !projectID.isEmpty {
                return projectID
            }
            if !projectName.isEmpty {
                return projectName
            }
            return "project_unresolved"
        }()
        let fingerprint = supervisorDeterministicDigest(
            stable: [
                "pending_memory_fact_follow_up",
                stableScope,
                nextCategory.rawValue,
                nextCategory.question,
            ].joined(separator: "|")
        )

        let title: String
        let lead: String
        if !projectName.isEmpty {
            title = "待补背景：\(projectName)"
            lead = "《\(projectName)》还缺这项项目背景：\(nextCategory.question)"
        } else {
            title = "Supervisor 等你补项目背景"
            lead = "还没锁定项目，先说项目名，再补这项背景：\(nextCategory.question)"
        }

        let remainingCount = followUp.remainingCategories.count
        let remainingLine = remainingCount > 1
            ? "还剩 \(remainingCount) 项。"
            : "这是最后 1 项。"
        let issueLine: String
        if let issueSummary = followUp.issueSummary?.trimmingCharacters(in: .whitespacesAndNewlines),
           !issueSummary.isEmpty {
            issueLine = " 当前缺口：\(capped(issueSummary, maxChars: 48))。"
        } else {
            issueLine = ""
        }
        let body = "\(lead)\(issueLine) \(remainingLine) 直接说“\(nextCategory.example)”即可。"

        return SupervisorMemoryFactFollowUpReminder(
            fingerprint: fingerprint,
            notificationIdentifier: "x_terminal_supervisor_memory_follow_up_\(fingerprint)",
            title: title,
            body: body,
            actionURL: supervisorActionURL(projectId: followUp.projectId)
        )
    }

    private func postLocalSupervisorMemoryFollowUpNotification(
        _ reminder: SupervisorMemoryFactFollowUpReminder
    ) {
        guard canPostLocalSupervisorNotifications() else { return }
        let content = UNMutableNotificationContent()
        content.title = reminder.title
        content.body = reminder.body
        content.sound = .default
        content.threadIdentifier = supervisorMemoryFollowUpNotificationThreadID

        let request = UNNotificationRequest(
            identifier: reminder.notificationIdentifier,
            content: content,
            trigger: nil
        )
        UNUserNotificationCenter.current().add(request) { error in
            if let error {
                print("Supervisor memory follow-up notification error: \(error)")
            }
        }
    }

    private func canPostLocalSupervisorNotifications() -> Bool {
        if ProcessInfo.processInfo.isRunningUnderAutomatedTests {
            return false
        }
        return true
    }

    private func promptForPendingSupervisorMemoryFactFollowUp(
        _ followUp: SupervisorPendingMemoryFactFollowUp,
        style: SupervisorMemoryFactFollowUpPromptStyle = .initial
    ) -> String {
        let nextCategory = followUp.remainingCategories.first ?? .goalAndDone
        let hasProject = {
            if let projectName = displayNameForPendingSupervisorMemoryFactFollowUp(followUp),
               !projectName.isEmpty {
                return true
            }
            return false
        }()

        switch (style, hasProject) {
        case (.initial, true):
            return """
先补：\(nextCategory.tailLabel)。
\(nextCategory.question)
直接说：\(nextCategory.example)
"""
        case (.initial, false):
            return """
先告诉我项目名，并补：\(nextCategory.tailLabel)。
直接说：某某项目，\(nextCategory.example)
"""
        case (.reminder, true):
            return """
还在等这项背景：\(nextCategory.tailLabel)。
直接说：\(nextCategory.example)
"""
        case (.reminder, false):
            return """
还没锁定项目。直接说：某某项目，\(nextCategory.example)
"""
        case (.next, true):
            return """
下一项：\(nextCategory.tailLabel)。
\(nextCategory.question)
直接说：\(nextCategory.example)
"""
        case (.next, false):
            return """
下一项先锁定项目：\(nextCategory.tailLabel)。
直接说：某某项目，\(nextCategory.example)
"""
        }
    }

    private func supervisorMemoryFactCategoriesCovered(
        by intent: SupervisorNaturalMemoryPatchIntent
    ) -> Set<SupervisorMemoryFactFollowUpCategory> {
        var covered = Set<SupervisorMemoryFactFollowUpCategory>()
        if intent.goal?.isEmpty == false ||
            intent.doneDefinition?.isEmpty == false ||
            !intent.nonGoals.isEmpty ||
            !intent.approvedTechStack.isEmpty {
            covered.insert(.goalAndDone)
        }
        if intent.decisionStatement?.isEmpty == false || intent.decisionReason?.isEmpty == false {
            covered.insert(.decision)
        }
        if intent.blockerSummary?.isEmpty == false ||
            !intent.attemptedActions.isEmpty ||
            intent.currentStateSummary?.isEmpty == false ||
            intent.nextStepSummary?.isEmpty == false {
            covered.insert(.blocker)
        }
        if !intent.selectedEvidence.isEmpty {
            covered.insert(.evidence)
        }
        return covered
    }

    private func replyTextByAdvancingPendingSupervisorMemoryFactFollowUpIfNeeded(
        baseReply: String,
        intent: SupervisorNaturalMemoryPatchIntent,
        project: AXProjectEntry
    ) -> String {
        guard var followUp = activeSupervisorMemoryFactFollowUp() else {
            return baseReply
        }
        if let followUpProjectId = followUp.projectId,
           followUpProjectId != project.projectId {
            clearPendingSupervisorMemoryFactFollowUp()
            return baseReply
        }

        followUp.projectId = project.projectId
        followUp.projectName = resolvedPendingSupervisorMemoryFactFollowUpProjectName(
            existing: followUp.projectName,
            project: project
        )
        rememberPendingSupervisorMemoryFactFollowUpProjectName(
            projectId: followUp.projectId,
            projectName: followUp.projectName
        )
        let covered = supervisorMemoryFactCategoriesCovered(by: intent)
        guard !covered.isEmpty else {
            followUp.updatedAt = Date().timeIntervalSince1970
            pendingSupervisorMemoryFactFollowUp = followUp
            return baseReply
        }

        followUp.remainingCategories.removeAll { covered.contains($0) }
        followUp.updatedAt = Date().timeIntervalSince1970
        if followUp.remainingCategories.isEmpty {
            clearPendingSupervisorMemoryFactFollowUp()
            return """
\(baseReply)

这轮关键背景我已经先补进《\(project.displayName)》了。你现在可以直接再让我审查一次方向；如果还有新的日志或结果，也可以继续补。
"""
        }

        pendingSupervisorMemoryFactFollowUp = followUp
        publishPendingSupervisorMemoryFactFollowUpState(followUp)
        return """
\(baseReply)

下一项我还要补：
\(promptForPendingSupervisorMemoryFactFollowUp(followUp, style: .next))
"""
    }

    private func parseSupervisorNaturalMemoryPatchIntent(
        _ userMessage: String,
        explicitRequest: Bool
    ) -> SupervisorNaturalMemoryPatchIntent {
        let segments = extractSupervisorNaturalMemoryPatchSegments(from: userMessage)

        func firstValue(_ kind: SupervisorNaturalMemoryPatchFieldKind) -> String? {
            segments.first(where: { $0.kind == kind })?.value
        }

        func allValues(_ kind: SupervisorNaturalMemoryPatchFieldKind) -> [String] {
            segments.filter { $0.kind == kind }.map(\.value)
        }

        let rawDecision = firstValue(.decision)
        let rawReason = firstValue(.decisionReason)
        let rawBlocker = firstValue(.blocker)
        let rawState = firstValue(.currentState)
        let rawNextStep = firstValue(.nextStep)

        var decisionStatement = sanitizeSupervisorNaturalMemoryPatchValue(rawDecision ?? "")
        let lowered = normalizedSupervisorIntentText(userMessage)
        let looksLikeQuestion = userMessage.contains("?") ||
            userMessage.contains("？") ||
            lowered.hasSuffix("吗")
        if decisionStatement.isEmpty,
           !looksLikeQuestion,
           containsAny(
                lowered,
                [
                    "我们决定",
                    "决定先",
                    "决定不",
                    "改走",
                    "不走",
                    "改成",
                    "换成",
                    "锁定",
                    "就按这个",
                    "定成"
                ]
           ) {
            decisionStatement = sanitizeSupervisorNaturalMemoryPatchValue(userMessage)
        }

        let selectedEvidence = orderedUniqueReviewScalars(
            allValues(.evidence)
                .flatMap(splitSupervisorNaturalMemoryPatchList)
                .map(sanitizeSupervisorNaturalMemoryPatchValue)
        )

        return SupervisorNaturalMemoryPatchIntent(
            goal: firstValue(.goal),
            doneDefinition: firstValue(.doneDefinition),
            nonGoals: orderedUniqueReviewScalars(
                allValues(.nonGoal).flatMap(splitSupervisorNaturalMemoryPatchList)
            ),
            approvedTechStack: orderedUniqueReviewScalars(
                allValues(.approvedTechStack).flatMap(splitSupervisorNaturalMemoryPatchList)
            ),
            decisionStatement: decisionStatement.isEmpty ? nil : decisionStatement,
            decisionReason: rawReason,
            blockerSummary: rawBlocker,
            attemptedActions: orderedUniqueReviewScalars(
                allValues(.attemptedAction).flatMap(splitSupervisorNaturalMemoryPatchList)
            ),
            currentStateSummary: rawState,
            nextStepSummary: rawNextStep,
            selectedEvidence: selectedEvidence,
            explicitRequest: explicitRequest
        )
    }

    private func extractSupervisorNaturalMemoryPatchSegments(
        from text: String
    ) -> [(kind: SupervisorNaturalMemoryPatchFieldKind, value: String)] {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return [] }

        let markerMap: [(kind: SupervisorNaturalMemoryPatchFieldKind, tokens: [String])] = [
            (.goal, ["长期目标是", "目标是", "目标锁成", "目标先锁成", "目标定成", "目标先定成", "目标改成", "goal is", "goal:", "目标:", "要做的是", "最终要"]),
            (.doneDefinition, ["完成标准是", "完成标准锁成", "完成标准定成", "验收标准是", "验收标准锁成", "验收标准定成", "done definition is", "done definition:", "mvp是", "mvp:", "最小可交付是"]),
            (.nonGoal, ["先不做", "不要做", "不做", "非目标是", "non goal is", "non goals are"]),
            (.approvedTechStack, ["只用", "必须用", "只能用", "技术栈定为", "技术栈锁成", "技术栈是", "tech stack is", "approved tech stack"]),
            (.decision, ["我们决定", "决定先", "决定不", "改走", "不走", "改成", "换成", "锁定", "就按这个", "定成"]),
            (.decisionReason, ["原因是", "因为", "理由是", "主要考虑是", "why:", "because"]),
            (.blocker, ["现在卡在", "卡点是", "阻塞是", "卡住了", "blocker is", "blocker 是", "blocker是", "blocker:"]),
            (.attemptedAction, ["已经试过", "试过", "尝试了", "做过", "已试过"]),
            (.currentState, ["现在状态是", "当前状态是", "目前状态是", "目前在", "current state is"]),
            (.nextStep, ["下一步是", "接下来是", "接下来先", "后面先", "next step is"]),
            (.evidence, ["把这个作为依据", "把这个当依据", "作为依据", "证据是", "依据是", "参考是", "把这个作为证据"])
        ]

        struct Match {
            var kind: SupervisorNaturalMemoryPatchFieldKind
            var location: Int
            var length: Int
        }

        let lowered = trimmed.lowercased() as NSString
        let original = trimmed as NSString
        var matches: [Match] = []

        for (kind, tokens) in markerMap {
            for token in tokens {
                let needle = token.lowercased()
                var searchRange = NSRange(location: 0, length: lowered.length)
                while true {
                    let found = lowered.range(
                        of: needle,
                        options: [],
                        range: searchRange
                    )
                    if found.location == NSNotFound { break }
                    matches.append(Match(kind: kind, location: found.location, length: found.length))
                    let nextLocation = found.location + max(found.length, 1)
                    if nextLocation >= lowered.length { break }
                    searchRange = NSRange(location: nextLocation, length: lowered.length - nextLocation)
                }
            }
        }

        let sorted = matches.sorted { lhs, rhs in
            if lhs.location != rhs.location { return lhs.location < rhs.location }
            return lhs.length > rhs.length
        }

        var selected: [Match] = []
        var occupiedEnd = -1
        for match in sorted {
            if match.location < occupiedEnd { continue }
            selected.append(match)
            occupiedEnd = match.location + match.length
        }

        return selected.enumerated().compactMap { index, match in
            let valueStart = match.location + match.length
            let valueEnd = index + 1 < selected.count ? selected[index + 1].location : original.length
            guard valueEnd > valueStart else { return nil }
            let rawValue = original.substring(with: NSRange(location: valueStart, length: valueEnd - valueStart))
            let cleaned = sanitizeSupervisorNaturalMemoryPatchValue(rawValue)
            guard !cleaned.isEmpty else { return nil }
            return (match.kind, cleaned)
        }
    }

    func sanitizeSupervisorNaturalMemoryPatchValue(_ raw: String) -> String {
        var cleaned = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        cleaned = cleaned.replacingOccurrences(
            of: #"^[\s:：,，;；\.\-、]+"#,
            with: "",
            options: .regularExpression
        )
        cleaned = cleaned.replacingOccurrences(
            of: #"[\s,，;；。!！]+$"#,
            with: "",
            options: .regularExpression
        )
        cleaned = cleaned.trimmingCharacters(in: CharacterSet(charactersIn: "\"'“”‘’"))
        return cleaned.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func splitSupervisorNaturalMemoryPatchList(_ raw: String) -> [String] {
        let normalized = raw
            .replacingOccurrences(of: "以及", with: "、")
            .replacingOccurrences(of: "及", with: "、")
            .replacingOccurrences(of: " and ", with: ",")
        let parts = normalized.components(
            separatedBy: CharacterSet(charactersIn: "、,，/|；;\n")
        )
        return parts
            .map(sanitizeSupervisorNaturalMemoryPatchValue)
            .filter { !$0.isEmpty }
    }

    private func directSupervisorProjectCoderDispatchIfApplicable(
        _ userMessage: String,
        normalized: String,
        projects: [AXProjectEntry]
    ) -> String? {
        guard isExplicitSupervisorProjectCodingExecutionIntent(
            userMessage,
            normalized: normalized
        ) else { return nil }
        guard let appModel else {
            return "我识别到这是项目 coding 执行指令，但当前 Supervisor 还没有绑定 XT AppModel，不能安全派发给 Coder。"
        }
        guard appModel.hubConnected || appModel.hubRemoteConnected else {
            return "我识别到这是项目 coding 执行指令，但当前 Hub 路由未连接，先不把它伪装成已派发。请先恢复 Hub 连接后再继续。"
        }
        guard let selection = focusedSupervisorCommandProjectSelection(
            projects: projects,
            userMessage: userMessage
        ) else {
            return "我识别到这是项目 coding 执行指令，但当前项目不唯一。请点选项目或在这句话里带上项目名，我再直接派给对应 Coder。"
        }

        let ctx = supervisorMemoryContext(for: selection.project)
        let session = appModel.session(for: ctx)
        session.ensureLoaded(ctx: ctx, limit: 200)
        guard !session.isSending else {
            return "我识别到这是《\(selection.project.displayName)》的 coding 执行指令，但这个项目的 Coder 正在处理上一轮。我不会插队覆盖当前执行；等它结束后再发“继续执行这条 coding 指令”。"
        }
        guard session.pendingToolCalls.isEmpty else {
            return "我识别到这是《\(selection.project.displayName)》的 coding 执行指令，但这个项目的 Coder 还有待审批工具请求。我不会绕过审批直接开新轮；先审批当前 Coder 工具请求后再继续。"
        }

        let config: AXProjectConfig?
        do {
            config = try AXProjectStore.loadOrCreateConfig(for: ctx)
        } catch {
            return "我识别到这是《\(selection.project.displayName)》的 coding 执行指令，但项目配置加载失败：\(error.localizedDescription)"
        }
        let dispatchDedupeKey = supervisorProjectCoderDispatchDedupeKey(
            project: selection.project,
            userMessage: userMessage
        )
        if supervisorProjectCoderDispatchWasRecentlyHandled(dispatchDedupeKey) {
            return "这条我刚才已经派发给《\(selection.project.displayName)》的 Coder；我不会重复派发。当前进度看心跳和项目聊天。"
        }
        rememberSupervisorProjectCoderDispatch(dispatchDedupeKey)
        let memory = try? AXProjectStore.loadOrCreateMemory(for: ctx)
        let workflowContext = markSupervisorWorkflowCoderDispatchIfApplicable(
            project: selection.project,
            ctx: ctx,
            userMessage: userMessage
        )
        let dispatchCreatedAtMs = Int64((Date().timeIntervalSince1970 * 1000.0).rounded())
        let workflowValues = supervisorWorkflowContextValues(workflowContext)
        let dispatchId = AXChatMessageLineageMetadata.makeDispatchId(
            projectId: selection.project.projectId,
            runId: workflowValues["job_id"],
            launchRunId: workflowValues["step_id"],
            createdAtMs: dispatchCreatedAtMs
        )
        let dispatchLineage = AXChatMessageLineageMetadata(
            dispatchId: dispatchId,
            sourceRole: "supervisor",
            targetRole: "coder",
            dispatchKind: "supervisor_to_coder",
            projectId: selection.project.projectId,
            runId: workflowValues["job_id"],
            launchRunId: workflowValues["step_id"],
            status: "dispatched",
            createdAtMs: dispatchCreatedAtMs
        )
        let dispatchText = supervisorProjectCoderDispatchUserText(
            userMessage: userMessage,
            project: selection.project,
            selectionSource: selection.source,
            workflowContext: workflowContext
        )
        let baselineMessageCount = session.messages.count

        let preservedDraft = session.draft
        let preservedAttachments = session.draftAttachments
        session.draft = dispatchText
        session.draftAttachments = []
        session.send(
            ctx: ctx,
            memory: memory,
            config: config,
            router: appModel.llmRouter,
            sender: .supervisor,
            lineage: dispatchLineage
        )
        if !preservedDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            || !preservedAttachments.isEmpty {
            session.draft = preservedDraft
            session.draftAttachments = preservedAttachments
        }

        _ = appendActionLedger(
            action: "dispatch_project_coder",
            targetRef: selection.project.displayName,
            projectId: selection.project.projectId,
            projectName: selection.project.displayName,
            role: AXRole.coder.rawValue,
            modelId: appModel.settingsStore.settings.modelRoute(for: .coder).primaryModelId,
            status: "ok",
            reasonCode: "explicit_supervisor_coding_instruction",
            detail: capped(userMessage, maxChars: 240),
            verifiedAt: Date().timeIntervalSince1970,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )

        recordSupervisorProjectCoderDispatchHeartbeat(
            project: selection.project,
            projects: projects,
            userMessage: userMessage,
            workflowContext: workflowContext,
            dispatchId: dispatchId
        )
        startSupervisorProjectCoderDispatchWatch(
            session: session,
            context: SupervisorProjectCoderDispatchWatchContext(
                project: selection.project,
                ctx: ctx,
                userMessage: userMessage,
                workflowContext: workflowContext,
                dispatchId: dispatchId,
                baselineMessageCount: baselineMessageCount,
                dispatchDedupeKey: dispatchDedupeKey,
                projectCount: projects.count
            )
        )

        return "已派发给《\(selection.project.displayName)》的 Coder。执行进度会在心跳和项目聊天里更新。"
    }

    private func recordSupervisorProjectCoderDispatchHeartbeat(
        project: AXProjectEntry,
        projects: [AXProjectEntry],
        userMessage: String,
        workflowContext: String?,
        dispatchId: String
    ) {
        let workflowLine = workflowContext == nil
            ? "未检测到可同步的 launch_run；本次只派发到项目 Coder 执行轮。"
            : "当前 workflow 的下一条 `launch_run` 已同步为 Coder 执行中。"
        let content = """
主动推进：
已派发《\(project.displayName)》给 Coder；项目聊天正在处理。
dispatch_id：\(dispatchId)
指令摘要：\(capped(userMessage, maxChars: 160))
\(workflowLine)

重点看板：
《\(project.displayName)》：owner=coder，状态=执行中；后续写文件或跑命令仍按 Coder 工具审批和 A-Tier 策略走。

Coder 下一步建议：
等待项目 Coder 完成执行或发起工具审批；Supervisor 聊天框不再重复写入推进日志。
"""
        recordHeartbeatEntry(
            reason: "project_coder_dispatch",
            projectCount: projects.count,
            changed: true,
            content: content,
            focusActionURL: resumeProjectActionURL(projectId: project.projectId)
        )
    }

    private func startSupervisorProjectCoderDispatchWatch(
        session: ChatSessionModel,
        context: SupervisorProjectCoderDispatchWatchContext
    ) {
        supervisorProjectCoderDispatchWatchTasks[context.dispatchDedupeKey]?.cancel()
        let startedAt = Date().timeIntervalSince1970
        supervisorProjectCoderDispatchWatchTasks[context.dispatchDedupeKey] = Task { @MainActor [weak self, weak session] in
            guard let self, let session else { return }
            await self.observeSupervisorProjectCoderDispatch(
                session: session,
                context: context,
                startedAt: startedAt
            )
        }
    }

    private func observeSupervisorProjectCoderDispatch(
        session: ChatSessionModel,
        context: SupervisorProjectCoderDispatchWatchContext,
        startedAt: TimeInterval
    ) async {
        var timedOut = false
        while !Task.isCancelled {
            if !session.pendingToolCalls.isEmpty {
                break
            }
            if !session.isSending {
                break
            }
            let elapsed = Date().timeIntervalSince1970 - startedAt
            if elapsed >= supervisorProjectCoderDispatchWatchTimeoutSec {
                timedOut = true
                break
            }
            try? await Task.sleep(nanoseconds: supervisorProjectCoderDispatchWatchPollNanoseconds)
        }
        guard !Task.isCancelled else { return }
        supervisorProjectCoderDispatchWatchTasks[context.dispatchDedupeKey] = nil
        recordSupervisorProjectCoderDispatchObservation(
            context: context,
            observation: supervisorProjectCoderDispatchObservation(
                session: session,
                context: context,
                timedOut: timedOut
            )
        )
    }

    private func supervisorProjectCoderDispatchObservation(
        session: ChatSessionModel,
        context: SupervisorProjectCoderDispatchWatchContext,
        timedOut: Bool
    ) -> SupervisorProjectCoderDispatchObservation {
        let pendingToolCallCount = session.pendingToolCalls.count
        if pendingToolCallCount > 0 {
            return SupervisorProjectCoderDispatchObservation(
                stepStatus: .awaitingAuthorization,
                heartbeatReason: "project_coder_dispatch_awaiting_authorization",
                headline: "《\(context.project.displayName)》Coder 正在等待工具审批。",
                boardStatus: "等待审批",
                summary: "pending_tool_calls=\(pendingToolCallCount)",
                updateWorkflow: true
            )
        }

        let lastError = (session.lastError ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if !lastError.isEmpty {
            return SupervisorProjectCoderDispatchObservation(
                stepStatus: .failed,
                heartbeatReason: "project_coder_dispatch_failed",
                headline: "《\(context.project.displayName)》Coder 执行失败。",
                boardStatus: "失败",
                summary: capped(lastError, maxChars: 220),
                updateWorkflow: true
            )
        }

        if timedOut {
            return SupervisorProjectCoderDispatchObservation(
                stepStatus: nil,
                heartbeatReason: "project_coder_dispatch_still_running",
                headline: "《\(context.project.displayName)》Coder 仍在执行。",
                boardStatus: "执行中",
                summary: "已等待 \(Int(supervisorProjectCoderDispatchWatchTimeoutSec)) 秒，仍未观察到最终回复或工具审批。",
                updateWorkflow: false
            )
        }

        let assistantText = latestSupervisorProjectCoderAssistantText(
            session: session,
            baselineMessageCount: context.baselineMessageCount
        )
        let summary = capped(
            assistantText.isEmpty ? "未观察到 Coder 的最终回复。" : assistantText,
            maxChars: 220
        )
        if assistantText.isEmpty {
            return SupervisorProjectCoderDispatchObservation(
                stepStatus: .blocked,
                heartbeatReason: "project_coder_dispatch_blocked",
                headline: "《\(context.project.displayName)》Coder 没有形成可观察的最终回复。",
                boardStatus: "阻塞",
                summary: summary,
                updateWorkflow: true
            )
        }

        if supervisorProjectCoderReplyLooksBlocked(assistantText) {
            return SupervisorProjectCoderDispatchObservation(
                stepStatus: .blocked,
                heartbeatReason: "project_coder_dispatch_blocked",
                headline: "《\(context.project.displayName)》Coder 回复显示当前被阻塞。",
                boardStatus: "阻塞",
                summary: summary,
                updateWorkflow: true
            )
        }

        return SupervisorProjectCoderDispatchObservation(
            stepStatus: .completed,
            heartbeatReason: "project_coder_dispatch_completed",
            headline: "《\(context.project.displayName)》Coder 已完成本轮执行。",
            boardStatus: "完成",
            summary: summary,
            updateWorkflow: true
        )
    }

    private func latestSupervisorProjectCoderAssistantText(
        session: ChatSessionModel,
        baselineMessageCount: Int
    ) -> String {
        let safeBaseline = max(0, min(baselineMessageCount, session.messages.count))
        return session.messages
            .dropFirst(safeBaseline)
            .last {
                $0.role == .assistant
                    && !$0.content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            }?
            .content
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    }

    private func supervisorProjectCoderReplyLooksBlocked(_ text: String) -> Bool {
        let normalized = text
            .folding(options: [.caseInsensitive, .diacriticInsensitive, .widthInsensitive], locale: .current)
            .lowercased()
        return containsAny(
            normalized,
            [
                "blocked",
                "阻塞",
                "无法",
                "失败",
                "待审批",
                "需要审批",
                "permission",
                "grant",
                "denied",
                "error"
            ]
        )
    }

    private func recordSupervisorProjectCoderDispatchObservation(
        context: SupervisorProjectCoderDispatchWatchContext,
        observation: SupervisorProjectCoderDispatchObservation
    ) {
        if observation.updateWorkflow,
           let stepStatus = observation.stepStatus {
            updateSupervisorWorkflowForProjectCoderObservation(
                context: context,
                stepStatus: stepStatus,
                summary: observation.summary
            )
        }

        let content = """
主动推进：
\(observation.headline)
dispatch_id：\(context.dispatchId)
Coder 摘要：\(observation.summary)

重点看板：
《\(context.project.displayName)》：owner=coder，状态=\(observation.boardStatus)；完整执行细节留在项目 Coder 聊天，Supervisor 聊天框只保留派发确认。

Coder 下一步建议：
\(supervisorProjectCoderDispatchNextStepText(observation))
"""
        recordHeartbeatEntry(
            reason: observation.heartbeatReason,
            projectCount: context.projectCount,
            changed: true,
            content: content,
            focusActionURL: resumeProjectActionURL(projectId: context.project.projectId)
        )
        recordRuntimeActivity(
            "project_coder_dispatch \(observation.boardStatus): \(context.project.displayName) · \(capped(observation.summary, maxChars: 120))",
            project: context.project
        )
    }

    private func supervisorProjectCoderDispatchNextStepText(
        _ observation: SupervisorProjectCoderDispatchObservation
    ) -> String {
        switch observation.stepStatus {
        case .completed:
            return "由 Supervisor 或 Reviewer 接着做验收/审查，必要时再派发下一轮。"
        case .awaitingAuthorization:
            return "进入项目聊天审批 Coder 的工具请求；XT 不绕过 Hub/本地审批策略。"
        case .blocked, .failed:
            return "打开项目 Coder 聊天查看阻塞原因，补授权、补上下文或重新派发更窄的任务。"
        default:
            return "继续观察项目 Coder 聊天；状态变化会进入心跳和运行活动。"
        }
    }

    private func updateSupervisorWorkflowForProjectCoderObservation(
        context: SupervisorProjectCoderDispatchWatchContext,
        stepStatus: SupervisorPlanStepStatus,
        summary: String
    ) {
        let values = supervisorWorkflowContextValues(context.workflowContext)
        guard let jobId = values["job_id"],
              let planId = values["plan_id"],
              let stepId = values["step_id"] else {
            return
        }
        let updatedAtMs = Int64((Date().timeIntervalSince1970 * 1000.0).rounded())
        let detail = [
            "Coder final observed from project chat",
            "dispatch_source=supervisor_chat",
            "dispatch_id=\(context.dispatchId)",
            "coder_status=\(stepStatus.rawValue)",
            "summary=\(capped(summary, maxChars: 220))"
        ].joined(separator: "\n")
        _ = updateSupervisorWorkflowStepState(
            ctx: context.ctx,
            project: context.project,
            jobId: jobId,
            planId: planId,
            stepId: stepId,
            status: stepStatus,
            detail: detail,
            owner: "coder",
            updatedAtMs: updatedAtMs
        )
    }

    private func supervisorWorkflowContextValues(_ workflowContext: String?) -> [String: String] {
        guard let workflowContext else { return [:] }
        var values: [String: String] = [:]
        for rawLine in workflowContext.split(separator: "\n", omittingEmptySubsequences: true) {
            let line = String(rawLine)
            guard let separator = line.firstIndex(of: "=") else { continue }
            let key = String(line[..<separator]).trimmingCharacters(in: .whitespacesAndNewlines)
            let value = String(line[line.index(after: separator)...]).trimmingCharacters(in: .whitespacesAndNewlines)
            guard !key.isEmpty, !value.isEmpty else { continue }
            values[key] = value
        }
        return values
    }

    private func supervisorProjectCoderDispatchDedupeKey(
        project: AXProjectEntry,
        userMessage: String
    ) -> String {
        let normalizedInstruction = normalizedLookupKey(userMessage)
        return supervisorDeterministicDigest(
            stable: [
                "supervisor_project_coder_dispatch",
                project.projectId,
                project.displayName,
                normalizedInstruction
            ].joined(separator: "|")
        )
    }

    private func supervisorProjectCoderDispatchWasRecentlyHandled(_ key: String) -> Bool {
        let normalizedKey = key.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalizedKey.isEmpty else { return false }
        let now = Date().timeIntervalSince1970
        recentSupervisorProjectCoderDispatchesByKey = recentSupervisorProjectCoderDispatchesByKey.filter {
            now - $0.value <= supervisorProjectCoderDispatchDedupeWindowSec
        }
        guard let previous = recentSupervisorProjectCoderDispatchesByKey[normalizedKey] else {
            return false
        }
        return now - previous <= supervisorProjectCoderDispatchDedupeWindowSec
    }

    private func rememberSupervisorProjectCoderDispatch(_ key: String) {
        let normalizedKey = key.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalizedKey.isEmpty else { return }
        recentSupervisorProjectCoderDispatchesByKey[normalizedKey] = Date().timeIntervalSince1970
    }

    private func isExplicitSupervisorProjectCodingExecutionIntent(
        _ userMessage: String,
        normalized: String
    ) -> Bool {
        let trimmed = userMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        let lowered = trimmed
            .folding(options: [.caseInsensitive, .diacriticInsensitive, .widthInsensitive], locale: .current)
            .lowercased()
        let compact = normalized
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: " ", with: "")
        guard !compact.isEmpty else { return false }

        let asksForExplanation = containsAny(compact, ["怎么", "如何", "为什么", "详细说说", "设计一下"])
            || lowered.contains("?")
            || lowered.contains("？")
        let hasImperativeCue = containsAny(
            compact,
            ["先", "现在", "马上", "直接", "请", "帮我", "把", "给", "开始", "执行", "运行", "派发", "交给"]
        )
        if asksForExplanation && !hasImperativeCue {
            return false
        }

        let executionVerbs = [
            "创建",
            "新建",
            "建",
            "写",
            "改",
            "修改",
            "实现",
            "开发",
            "搭建",
            "补齐",
            "补",
            "落盘",
            "生成",
            "跑",
            "运行",
            "执行",
            "开始",
            "做",
            "派发",
            "交给coder",
            "交给 coder",
            "让coder",
            "让 coder",
            "implement",
            "build",
            "code"
        ]
        let codingObjects = [
            "代码",
            "文件",
            "页面",
            "骨架",
            "最小可运行",
            "mvp",
            "功能",
            "项目根目录",
            "仓库",
            "repo",
            "coder",
            "coding",
            "html",
            "css",
            "javascript",
            "js",
            "swift",
            "index.html",
            "style.css",
            "main.js"
        ]
        let hasExecutionVerb = executionVerbs.contains { compact.contains($0.replacingOccurrences(of: " ", with: "")) }
            || executionVerbs.contains { lowered.contains($0) }
        let hasCodingObject = codingObjects.contains { compact.contains($0.replacingOccurrences(of: " ", with: "")) }
            || codingObjects.contains { lowered.contains($0) }
            || supervisorMessageContainsFileReference(lowered)

        return hasExecutionVerb && hasCodingObject
    }

    private func supervisorMessageContainsFileReference(_ lowered: String) -> Bool {
        lowered.range(
            of: #"(?i)\b[\p{L}\p{N}_./-]+\.(html|css|js|jsx|ts|tsx|swift|py|rs|json|md|yml|yaml|toml|sh|txt)\b"#,
            options: .regularExpression
        ) != nil
    }

    private func markSupervisorWorkflowCoderDispatchIfApplicable(
        project: AXProjectEntry,
        ctx: AXProjectContext,
        userMessage: String
    ) -> String? {
        guard let state = supervisorWorkflowState(
            project: project,
            ctx: ctx,
            preferredJobId: nil,
            preferredPlanId: nil,
            preferredRequestId: nil
        ), let plan = state.plan else {
            return nil
        }
        guard !isTerminalSupervisorJobStatus(state.job.status),
              !isTerminalSupervisorPlanStatus(plan.status),
              let step = supervisorContinuableLaunchRunStep(in: plan) else {
            return nil
        }

        let updatedAtMs = Int64((Date().timeIntervalSince1970 * 1000.0).rounded())
        let detail = [
            "launch_run dispatched to project Coder chat",
            "dispatch_source=supervisor_chat",
            "user_request=\(capped(userMessage, maxChars: 240))"
        ].joined(separator: "\n")
        _ = updateSupervisorWorkflowStepState(
            ctx: ctx,
            project: project,
            jobId: state.job.jobId,
            planId: plan.planId,
            stepId: step.stepId,
            status: .running,
            detail: detail,
            owner: "coder",
            updatedAtMs: updatedAtMs
        )
        return [
            "job_id=\(state.job.jobId)",
            "plan_id=\(plan.planId)",
            "step_id=\(step.stepId)",
            "step_title=\(step.title)",
            "step_kind=\(step.kind.rawValue)"
        ].joined(separator: "\n")
    }

    private func supervisorProjectCoderDispatchUserText(
        userMessage: String,
        project: AXProjectEntry,
        selectionSource: String,
        workflowContext: String?
    ) -> String {
        var lines = [
            "来自 Supervisor 的项目执行派发。",
            "项目：\(project.displayName)",
            "project_id：\(project.projectId)",
            "selection_source：\(selectionSource)",
            "",
            "原始用户指令：",
            userMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        ]
        if let workflowContext, !workflowContext.isEmpty {
            lines.append("")
            lines.append("当前 workflow：")
            lines.append(workflowContext)
        }
        lines.append("")
        lines.append("执行要求：")
        lines.append("- 这是 Coder 执行轮，不是 Supervisor 讨论轮。")
        lines.append("- 优先在当前项目根目录内直接落盘完成请求。")
        lines.append("- 如果需要新建文件，使用当前可用的 write_file/tool_calls；不要要求用户手动复制文件内容，除非当前 Tool policy 明确阻止写入。")
        lines.append("- 范围收敛到这次指令；完成后说明改了什么、怎么运行、还有什么未做。")
        return lines.joined(separator: "\n")
    }

    private func directSupervisorWorkflowLaunchRunContinuationIfApplicable(
        _ userMessage: String,
        normalized: String,
        projects: [AXProjectEntry]
    ) -> String? {
        guard !isSupervisorStructuredWorkflowPayload(userMessage) else { return nil }
        guard isExplicitSupervisorContinuationIntent(normalized) else { return nil }
        guard let selection = focusedSupervisorCommandProjectSelection(
            projects: projects,
            userMessage: userMessage
        ) else {
            return nil
        }

        let ctx = supervisorMemoryContext(for: selection.project)
        guard let state = supervisorWorkflowState(
            project: selection.project,
            ctx: ctx,
            preferredJobId: nil,
            preferredPlanId: nil,
            preferredRequestId: nil
        ), let plan = state.plan else {
            return nil
        }
        guard !isTerminalSupervisorJobStatus(state.job.status),
              !isTerminalSupervisorPlanStatus(plan.status),
              let step = supervisorContinuableLaunchRunStep(in: plan) else {
            return nil
        }

        do {
            return try continueSupervisorWorkflowLaunchRun(
                project: selection.project,
                ctx: ctx,
                job: state.job,
                plan: plan,
                step: step
            )
        } catch {
            let detail = "launch_run continuation failed: \(error.localizedDescription)"
            let updatedAtMs = Int64((Date().timeIntervalSince1970 * 1000.0).rounded())
            _ = updateSupervisorWorkflowStepState(
                ctx: ctx,
                project: selection.project,
                jobId: state.job.jobId,
                planId: plan.planId,
                stepId: step.stepId,
                status: .blocked,
                detail: detail,
                owner: "coder",
                updatedAtMs: updatedAtMs
            )
            return renderAutomationRuntimeError(error)
        }
    }

    private func supervisorContinuableLaunchRunStep(
        in plan: SupervisorPlanRecord
    ) -> SupervisorPlanStepRecord? {
        let orderedSteps = supervisorOrderedWorkflowSteps(plan)
        let completedStepIDs = Set(
            orderedSteps
                .filter { $0.status == .completed }
                .map(\.stepId)
        )

        func dependenciesSatisfied(for step: SupervisorPlanStepRecord) -> Bool {
            let dependencies = (step.dependsOn ?? [])
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
            return dependencies.allSatisfy { completedStepIDs.contains($0) }
        }

        if let attentionStep = orderedSteps.first(where: { step in
            guard step.kind == .launchRun else { return false }
            switch step.status {
            case .running, .blocked, .awaitingAuthorization:
                return true
            case .pending, .completed, .failed, .canceled:
                return false
            }
        }) {
            return attentionStep
        }

        return orderedSteps.first(where: { step in
            step.kind == .launchRun
                && step.status == .pending
                && dependenciesSatisfied(for: step)
        })
    }

    private func continueSupervisorWorkflowLaunchRun(
        project: AXProjectEntry,
        ctx: AXProjectContext,
        job: SupervisorJobRecord,
        plan: SupervisorPlanRecord,
        step: SupervisorPlanStepRecord
    ) throws -> String {
        let updatedAtMs = Int64((Date().timeIntervalSince1970 * 1000.0).rounded())
        let now = Date()

        if let activeRunID = effectiveAutomationRunRef(
            for: ctx,
            allowedStates: automationMutableRunStates
        ), let checkpoint = try? automationRunCoordinator.latestCheckpoint(for: activeRunID, in: ctx) {
            switch checkpoint.state {
            case .queued, .running:
                _ = updateSupervisorWorkflowStepState(
                    ctx: ctx,
                    project: project,
                    jobId: job.jobId,
                    planId: plan.planId,
                    stepId: step.stepId,
                    status: .running,
                    detail: "launch_run already routed to governed automation runtime (run_id=\(activeRunID), state=\(checkpoint.state.rawValue))",
                    owner: "coder",
                    updatedAtMs: updatedAtMs
                )
                return try renderAutomationRuntimeStatus(for: project, ctx: ctx)
            case .blocked, .takeover, .downgraded:
                let recoveryCandidate = try automationRunCoordinator.latestRecoveryCandidate(
                    for: ctx,
                    now: now.timeIntervalSince1970
                )
                let decision = try recoverLatestAutomationRun(
                    for: project,
                    ctx: ctx,
                    now: now.timeIntervalSince1970,
                    recoveryMode: .operatorOverride,
                    auditRef: automationRuntimeAuditRef(action: "workflow_launch_run_continue", project: project),
                    emitSystemMessage: false
                )
                let recovered = decision?.decision == .resume
                _ = updateSupervisorWorkflowStepState(
                    ctx: ctx,
                    project: project,
                    jobId: job.jobId,
                    planId: plan.planId,
                    stepId: step.stepId,
                    status: recovered ? .running : .blocked,
                    detail: decision.map {
                        "launch_run recovery \($0.decision.rawValue) (run_id=\($0.runID), state=\($0.recoveredState.rawValue), hold=\($0.holdReason.isEmpty ? "none" : $0.holdReason))"
                    } ?? "launch_run recovery requested but no recoverable run candidate was accepted",
                    owner: "coder",
                    updatedAtMs: updatedAtMs
                )
                return renderAutomationRecoverySummary(
                    project: project,
                    ctx: ctx,
                    decision: decision,
                    retryPackage: automationLatestRetryPackage,
                    recoveryCandidate: recoveryCandidate
                )
            case .delivered, .failed:
                break
            }
        }

        do {
            let request = try makeManualAutomationRunRequest(for: project, ctx: ctx)
            let prepared = try startAutomationRun(for: ctx, request: request, emitSystemMessage: false)
            _ = updateSupervisorWorkflowStepState(
                ctx: ctx,
                project: project,
                jobId: job.jobId,
                planId: plan.planId,
                stepId: step.stepId,
                status: .running,
                detail: "launch_run delegated to governed automation runtime (run_id=\(prepared.launchRef), recipe=\(prepared.recipeRef))",
                owner: "coder",
                updatedAtMs: updatedAtMs
            )
            return renderAutomationStartSummary(project: project, prepared: prepared)
        } catch XTAutomationRunCoordinatorError.activeRecipeMissing {
            _ = updateSupervisorWorkflowStepState(
                ctx: ctx,
                project: project,
                jobId: job.jobId,
                planId: plan.planId,
                stepId: step.stepId,
                status: .blocked,
                detail: "launch_run blocked: active automation recipe missing",
                owner: "coder",
                updatedAtMs: updatedAtMs
            )
            return """
⚠️ 已识别到当前 workflow 的下一 runnable step 是 \(step.stepId)（launch_run），但项目还没有 ready + active 的 automation recipe。

\(renderAutomationRuntimeError(XTAutomationRunCoordinatorError.activeRecipeMissing))
我不会把这一步降级成裸 `CALL_SKILL(coder...)`；需要先把这条工单接到 XTAutomation runtime。
"""
        } catch {
            throw error
        }
    }

    private func localSupervisorWorkflowBootstrapIfApplicable(
        _ userMessage: String,
        normalized: String,
        projects: [AXProjectEntry]
    ) -> String? {
        guard isExplicitSupervisorContinuationIntent(normalized) else { return nil }
        guard let selection = focusedSupervisorCommandProjectSelection(
            projects: projects,
            userMessage: userMessage
        ) else {
            return nil
        }

        let ctx = supervisorMemoryContext(for: selection.project)
        guard !hasActiveSupervisorWorkflow(project: selection.project, ctx: ctx) else {
            return nil
        }

        let digest = supervisorMemoryDigest(selection.project)
        guard let spec = buildLocalSupervisorWorkflowBootstrapSpec(
            selection: selection,
            digest: digest
        ) else {
            return nil
        }

        let createPayload = SupervisorCreateJobPayload(
            projectRef: spec.project.projectId,
            goal: spec.jobGoal,
            priority: SupervisorJobPriority.high.rawValue,
            source: SupervisorJobSource.supervisor.rawValue,
            currentOwner: "supervisor"
        )
        let createResult = createSupervisorJob(
            from: createPayload,
            userMessage: userMessage,
            triggerSource: .userTurn,
            emitSystemMessage: false
        )
        _ = appendActionLedger(
            action: "create_job",
            targetRef: spec.project.displayName,
            projectId: createResult.projectId,
            projectName: createResult.projectName,
            role: nil,
            modelId: nil,
            status: createResult.ok ? "ok" : "failed",
            reasonCode: createResult.reasonCode,
            detail: createResult.message,
            verifiedAt: createResult.ok ? Date().timeIntervalSince1970 : nil,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )
        guard createResult.ok, let jobId = createResult.jobId else {
            return createResult.message
        }

        let planPayload = SupervisorUpsertPlanPayload(
            projectRef: spec.project.projectId,
            jobId: jobId,
            planId: spec.planId,
            currentOwner: "supervisor",
            steps: spec.steps
        )
        let planResult = upsertSupervisorPlan(
            from: planPayload,
            userMessage: userMessage,
            triggerSource: .userTurn,
            emitSystemMessage: false
        )
        _ = appendActionLedger(
            action: "upsert_plan",
            targetRef: spec.project.displayName,
            projectId: planResult.projectId,
            projectName: planResult.projectName,
            role: nil,
            modelId: nil,
            status: planResult.ok ? "ok" : "failed",
            reasonCode: planResult.reasonCode,
            detail: planResult.message,
            verifiedAt: planResult.ok ? Date().timeIntervalSince1970 : nil,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )
        guard planResult.ok else {
            return """
我已经按《\(spec.project.displayName)》的当前记忆创建了受治理任务，但写入执行计划失败。

\(createResult.message)
\(planResult.message)
"""
        }

        return renderLocalSupervisorWorkflowBootstrapResponse(
            project: spec.project,
            digest: spec.digest,
            jobId: jobId,
            planId: spec.planId,
            steps: spec.steps
        )
    }

    private func buildLocalSupervisorWorkflowBootstrapSpec(
        selection: SupervisorFocusedProjectSelection,
        digest: SupervisorMemoryProjectDigest
    ) -> SupervisorLocalWorkflowBootstrapSpec? {
        let goal = digest.goal.trimmingCharacters(in: .whitespacesAndNewlines)
        let currentState = digest.currentState.trimmingCharacters(in: .whitespacesAndNewlines)
        let nextStep = digest.nextStep.trimmingCharacters(in: .whitespacesAndNewlines)
        let blocker = digest.blocker.trimmingCharacters(in: .whitespacesAndNewlines)

        let hasConcreteGoal = !isDigestPlaceholder(goal)
        let hasConcreteCurrentState = !isDigestPlaceholder(currentState)
        let hasConcreteNextStep = !isDigestPlaceholder(
            nextStep,
            treatContinueCurrentTaskAsPlaceholder: true
        )
        let hasConcreteBlocker = !isDigestPlaceholder(blocker, treatNoValueAsPlaceholder: true)
        guard hasConcreteNextStep || hasConcreteGoal else {
            return nil
        }

        let jobGoal = hasConcreteNextStep ? nextStep : goal
        let primaryAction = hasConcreteNextStep ? nextStep : jobGoal
        let projectToken = normalizedLookupKey(selection.project.displayName).isEmpty
            ? String(selection.project.projectId.prefix(8)).lowercased()
            : String(normalizedLookupKey(selection.project.displayName).prefix(24))
        let nowMs = Int64((Date().timeIntervalSince1970 * 1000.0).rounded())
        let planId = "plan-\(projectToken)-continue-\(nowMs)"
        let primaryStepTitle = normalizedSupervisorBootstrapPrimaryStepTitle(primaryAction)
        let followUpTitle: String = {
            if hasConcreteBlocker {
                return "处理阻塞并回写下一轮动作：\(capped(blocker, maxChars: 48))"
            }
            return "回写推进结果并确认下一轮动作"
        }()

        let reviewDetail = [
            "bootstrap_source=local_direct_continue",
            "focus_source=\(selection.source)",
            "memory_source=\(digest.source)",
            "goal=\(hasConcreteGoal ? goal : "(none)")",
            "current_state=\(hasConcreteCurrentState ? currentState : "(none)")",
            "next_step=\(hasConcreteNextStep ? nextStep : "(none)")",
            "blocker=\(hasConcreteBlocker ? blocker : "(none)")"
        ].joined(separator: "\n")
        let executionDetail = [
            "derived_from=\(hasConcreteNextStep ? "next_step" : "goal")",
            "runtime_state=\(digest.runtimeState)",
            "current_state=\(hasConcreteCurrentState ? currentState : "(none)")",
            "blocker=\(hasConcreteBlocker ? blocker : "(none)")"
        ].joined(separator: "\n")
        let wrapUpDetail = [
            "close_loop=write_back_execution_delta",
            "next_goal=\(jobGoal)",
            "blocker=\(hasConcreteBlocker ? blocker : "(none)")"
        ].joined(separator: "\n")

        let steps = [
            SupervisorUpsertPlanStepPayload(
                stepId: "step-001",
                title: "审查项目上下文记忆并确认当前事实",
                kind: SupervisorPlanStepKind.writeMemory.rawValue,
                status: SupervisorPlanStepStatus.completed.rawValue,
                skillId: nil,
                currentOwner: "supervisor",
                detail: reviewDetail
            ),
            SupervisorUpsertPlanStepPayload(
                stepId: "step-002",
                title: primaryStepTitle,
                kind: suggestedSupervisorBootstrapPlanStepKind(primaryAction).rawValue,
                status: SupervisorPlanStepStatus.pending.rawValue,
                skillId: nil,
                currentOwner: "supervisor",
                detail: executionDetail
            ),
            SupervisorUpsertPlanStepPayload(
                stepId: "step-003",
                title: followUpTitle,
                kind: SupervisorPlanStepKind.writeMemory.rawValue,
                status: SupervisorPlanStepStatus.pending.rawValue,
                skillId: nil,
                currentOwner: "supervisor",
                detail: wrapUpDetail
            )
        ]

        return SupervisorLocalWorkflowBootstrapSpec(
            project: selection.project,
            digest: digest,
            jobGoal: jobGoal,
            planId: planId,
            steps: steps
        )
    }

    private func renderLocalSupervisorWorkflowBootstrapResponse(
        project: AXProjectEntry,
        digest: SupervisorMemoryProjectDigest,
        jobId: String,
        planId: String,
        steps: [SupervisorUpsertPlanStepPayload]
    ) -> String {
        var lines = [
            "我已经按《\(project.displayName)》的当前记忆，把下一步起成一个受治理 workflow。",
            "",
            "job_id: \(jobId)",
            "plan_id: \(planId)",
            "任务目标：\(digest.nextStep.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || isDigestPlaceholder(digest.nextStep, treatContinueCurrentTaskAsPlaceholder: true) ? digest.goal : digest.nextStep)"
        ]

        let currentState = digest.currentState.trimmingCharacters(in: .whitespacesAndNewlines)
        if !isDigestPlaceholder(currentState) {
            lines.append("当前状态：\(currentState)")
        }
        let blocker = digest.blocker.trimmingCharacters(in: .whitespacesAndNewlines)
        if !isDigestPlaceholder(blocker, treatNoValueAsPlaceholder: true) {
            lines.append("当前阻塞：\(SupervisorBlockerPresentation.label(blocker))")
        }

        lines.append("计划步骤：")
        lines.append(
            steps.enumerated().map { index, step in
                let status = SupervisorPlanStepStatus.parse(step.status).rawValue
                return "\(index + 1). \(step.title)（\(status)）"
            }.joined(separator: "\n")
        )
        lines.append("")
        lines.append("这样 Supervisor 再收到“继续 / 自动继续”时，就会沿着这个 job / plan 往下执行，而不是只汇报 idle。")
        return lines.joined(separator: "\n")
    }

    private func normalizedSupervisorBootstrapPrimaryStepTitle(_ text: String) -> String {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "推进当前最具体的执行动作" }
        let lowered = trimmed.lowercased()
        if containsAny(lowered, ["继续", "推进", "修复", "梳理", "实现", "重跑", "检查", "运行", "输出", "整理"]) {
            return capped(trimmed, maxChars: 72)
        }
        return "推进：\(capped(trimmed, maxChars: 64))"
    }

    private func suggestedSupervisorBootstrapPlanStepKind(_ action: String) -> SupervisorPlanStepKind {
        let lowered = action.lowercased()
        if containsAny(lowered, ["调用技能", "调用skill", "call skill", "技能"]) {
            return .callSkill
        }
        if containsAny(lowered, ["运行", "重跑", "测试", "构建", "build", "test", "run", "smoke", "验证"]) {
            return .launchRun
        }
        if containsAny(lowered, ["确认", "澄清", "问用户", "ask user", "授权", "approve"]) {
            return .askUser
        }
        return .writeMemory
    }

    private func hasActiveSupervisorWorkflow(
        project: AXProjectEntry,
        ctx: AXProjectContext
    ) -> Bool {
        let jobActive = SupervisorProjectJobStore.load(for: ctx).jobs.contains { record in
            record.projectId == project.projectId && !isTerminalSupervisorJobStatus(record.status)
        }
        if jobActive {
            return true
        }

        let planActive = SupervisorProjectPlanStore.load(for: ctx).plans.contains { record in
            record.projectId == project.projectId && !isTerminalSupervisorPlanStatus(record.status)
        }
        if planActive {
            return true
        }

        return SupervisorProjectSkillCallStore.load(for: ctx).calls.contains { record in
            record.projectId == project.projectId && !isTerminalSupervisorSkillCallStatus(record.status)
        }
    }

    private func isTerminalSupervisorJobStatus(_ status: SupervisorJobStatus) -> Bool {
        switch status {
        case .completed, .failed, .canceled:
            return true
        default:
            return false
        }
    }

    private func isTerminalSupervisorPlanStatus(_ status: SupervisorPlanStatus) -> Bool {
        switch status {
        case .completed, .failed, .canceled:
            return true
        default:
            return false
        }
    }

    private func isTerminalSupervisorSkillCallStatus(_ status: SupervisorSkillCallStatus) -> Bool {
        switch status {
        case .completed, .failed, .canceled:
            return true
        default:
            return false
        }
    }

    func normalizedSupervisorIntentText(_ text: String) -> String {
        text
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }

