    private func isExplicitSupervisorSkillDispatchFollowupRequest(_ normalized: String) -> Bool {
        let trimmed = normalized.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        let compact = trimmed
            .replacingOccurrences(of: " ", with: "")
            .trimmingCharacters(in: CharacterSet.punctuationCharacters.union(.symbols))
        guard !compact.isEmpty else { return false }

        return compact.range(
            of: #"^(请|那就|就|直接|先|现在)?(用|跑|执行|运行|调用)(这个|该|此)?(skill|技能)$"#,
            options: .regularExpression
        ) != nil
    }

    private func isExplicitSupervisorSkillEnableFollowupRequest(_ normalized: String) -> Bool {
        let trimmed = normalized.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        let intentTokens = [
            "申请启用",
            "申请开通",
            "申请可用性",
            "发起申请",
            "提交申请",
            "提交hub申请",
            "提交 hub 申请",
            "启用它",
            "启用这个",
            "enable it",
            "request enable"
        ]
        if intentTokens.contains(where: { trimmed.contains($0) }) {
            return true
        }

        let hasEnableVerb = [
            "申请",
            "启用",
            "开通",
            "enable",
            "request",
            "submit"
        ].contains(where: { trimmed.contains($0) })
        guard hasEnableVerb else { return false }

        if trimmed.contains("package_sha256") || trimmed.contains("sha256") {
            return true
        }

        return trimmed.range(
            of: #"\b[a-z0-9]+(?:[._-][a-z0-9]+)+\b"#,
            options: .regularExpression
        ) != nil
    }

    private func isExplicitSupervisorContinuationIntent(_ normalized: String) -> Bool {
        let trimmed = normalized.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        let compact = trimmed.replacingOccurrences(of: " ", with: "")
        let exact = compact.trimmingCharacters(
            in: CharacterSet.punctuationCharacters.union(.symbols)
        )
        if ["继续", "推进", "下一步"].contains(exact) {
            return true
        }

        let directTokens = [
            "继续推进",
            "继续执行",
            "自动继续",
            "自动推进",
            "按当前记忆继续推进",
            "按当前记忆继续",
            "继续这个项目",
            "继续当前项目",
            "继续该项目",
            "继续这个任务",
            "继续当前任务",
            "推进这个项目",
            "推进当前项目",
            "推进该项目",
            "继续下一步",
            "开始下一步"
        ]
        if directTokens.contains(where: { compact.contains($0) }) {
            return true
        }

        let continuationVerbs = ["继续", "推进", "接着", "下一步", "followup", "continue"]
        let scopeTokens = [
            "项目",
            "当前项目",
            "这个项目",
            "该项目",
            "任务",
            "当前任务",
            "这个任务",
            "workflow",
            "plan",
            "记忆",
            "上下文"
        ]
        let hasVerb = continuationVerbs.contains(where: { compact.contains($0) })
        let hasScope = scopeTokens.contains(where: { compact.contains($0) })
        return hasVerb && hasScope
    }

    private func processCreateJobCommand(
        in text: String,
        userMessage: String,
        triggerSource: SupervisorCommandTriggerSource
    ) -> String {
        guard let payload = firstTagContent(in: text, tag: "CREATE_JOB"), !payload.isEmpty else {
            return text
        }

        switch decodeSupervisorJSONPayload(payload, as: SupervisorCreateJobPayload.self) {
        case .success(let command):
            let result = createSupervisorJob(
                from: command,
                userMessage: userMessage,
                triggerSource: triggerSource
            )
            _ = appendActionLedger(
                action: "create_job",
                targetRef: (command.projectRef ?? "").trimmingCharacters(in: .whitespacesAndNewlines),
                projectId: result.projectId,
                projectName: result.projectName,
                role: nil,
                modelId: nil,
                status: result.ok ? "ok" : "failed",
                reasonCode: result.reasonCode,
                detail: result.message,
                verifiedAt: result.ok ? Date().timeIntervalSince1970 : nil,
                triggerSource: triggerSource.rawValue
            )
            return replacingTaggedSection(
                in: text,
                tag: "CREATE_JOB",
                with: result.message
            )
        case .failure(let error):
            let reason = error.message
            _ = appendActionLedger(
                action: "create_job",
                targetRef: "(invalid_json)",
                projectId: nil,
                projectName: nil,
                role: nil,
                modelId: nil,
                status: "failed",
                reasonCode: "invalid_create_job_format",
                detail: reason,
                verifiedAt: nil,
                triggerSource: triggerSource.rawValue
            )
            return replacingTaggedSection(
                in: text,
                tag: "CREATE_JOB",
                with: "❌ CREATE_JOB 标签解析失败：\(reason)"
            )
        }
    }

    private func processUpsertPlanCommand(
        in text: String,
        userMessage: String,
        triggerSource: SupervisorCommandTriggerSource
    ) -> String {
        guard let payload = firstTagContent(in: text, tag: "UPSERT_PLAN"), !payload.isEmpty else {
            return text
        }

        switch decodeSupervisorJSONPayload(payload, as: SupervisorUpsertPlanPayload.self) {
        case .success(let command):
            let result = upsertSupervisorPlan(
                from: command,
                userMessage: userMessage,
                triggerSource: triggerSource
            )
            _ = appendActionLedger(
                action: "upsert_plan",
                targetRef: (command.projectRef ?? "").trimmingCharacters(in: .whitespacesAndNewlines),
                projectId: result.projectId,
                projectName: result.projectName,
                role: nil,
                modelId: nil,
                status: result.ok ? "ok" : "failed",
                reasonCode: result.reasonCode,
                detail: result.message,
                verifiedAt: result.ok ? Date().timeIntervalSince1970 : nil,
                triggerSource: triggerSource.rawValue
            )
            return replacingTaggedSection(
                in: text,
                tag: "UPSERT_PLAN",
                with: result.message
            )
        case .failure(let error):
            let reason = error.message
            _ = appendActionLedger(
                action: "upsert_plan",
                targetRef: "(invalid_json)",
                projectId: nil,
                projectName: nil,
                role: nil,
                modelId: nil,
                status: "failed",
                reasonCode: "invalid_upsert_plan_format",
                detail: reason,
                verifiedAt: nil,
                triggerSource: triggerSource.rawValue
            )
            return replacingTaggedSection(
                in: text,
                tag: "UPSERT_PLAN",
                with: "❌ UPSERT_PLAN 标签解析失败：\(reason)"
            )
        }
    }

