    func supervisorBaseSkillReadiness(
        record: SupervisorSkillCallRecord,
        project: AXProjectEntry,
        ctx: AXProjectContext,
        config: AXProjectConfig,
        registryItem: SupervisorSkillRegistryItem?
    ) -> XTSkillExecutionReadiness? {
        let skillId = record.skillId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !skillId.isEmpty else { return nil }
        return AXSkillsLibrary.skillExecutionReadiness(
            skillId: skillId,
            projectId: project.projectId,
            projectName: project.displayName,
            projectRoot: ctx.root,
            config: config,
            registryItem: registryItem,
            hubBaseDir: HubPaths.baseDir()
        )
    }

    private func supervisorSkillRequiresLocalApproval(
        approvalFloor: String,
        ctx: AXProjectContext,
        config: AXProjectConfig
    ) -> Bool {
        switch approvalFloor.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() {
        case XTSkillApprovalFloor.none.rawValue,
             XTSkillApprovalFloor.hubGrant.rawValue:
            return false
        case XTSkillApprovalFloor.localApproval.rawValue:
            return !xtProjectGovernedAutoApprovalConfigured(
                projectRoot: ctx.root,
                config: config
            )
        case XTSkillApprovalFloor.hubGrantPlusLocalApproval.rawValue,
             XTSkillApprovalFloor.ownerConfirmation.rawValue:
            return true
        default:
            return false
        }
    }

    private func supervisorSkillGrantSatisfied(
        record: SupervisorSkillCallRecord,
        readiness: XTSkillExecutionReadiness,
        toolCall: ToolCall?
    ) -> Bool {
        let normalizedGrantFloor = readiness.grantFloor
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        if normalizedGrantFloor.isEmpty || normalizedGrantFloor == XTSkillGrantFloor.none.rawValue {
            return true
        }
        if let granted = firstNonEmpty(
            record.grantId,
            toolCall?.args["grant_id"]?.stringValue
        ), !granted.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return true
        }
        switch record.status {
        case .queued, .running, .completed, .failed, .canceled:
            return true
        default:
            return false
        }
    }

    private func supervisorSkillLocalApprovalSatisfied(
        record: SupervisorSkillCallRecord,
        readiness: XTSkillExecutionReadiness,
        ctx: AXProjectContext,
        config: AXProjectConfig
    ) -> Bool {
        guard supervisorSkillRequiresLocalApproval(
            approvalFloor: readiness.approvalFloor,
            ctx: ctx,
            config: config
        ) else {
            return true
        }
        switch record.status {
        case .queued, .running, .completed, .failed, .canceled:
            return true
        default:
            return false
        }
    }

    private func supervisorOverriddenSkillReadiness(
        _ readiness: XTSkillExecutionReadiness,
        state: XTSkillExecutionReadinessState
    ) -> XTSkillExecutionReadiness {
        var updated = readiness
        updated.executionReadiness = state.rawValue
        updated.runnableNow = state == .ready
        updated.stateLabel = XTSkillCapabilityProfileSupport.readinessLabel(state.rawValue)

        switch state {
        case .ready:
            updated.denyCode = ""
            updated.reasonCode = "request-scoped authorization satisfied"
            updated.unblockActions = []
        case .grantRequired:
            updated.denyCode = "grant_required"
            let grantFloor = updated.grantFloor.trimmingCharacters(in: .whitespacesAndNewlines)
            if grantFloor.isEmpty || grantFloor.lowercased() == XTSkillGrantFloor.none.rawValue {
                updated.reasonCode = "hub grant still pending"
            } else {
                updated.reasonCode = "grant floor \(updated.grantFloor) still pending"
            }
            updated.unblockActions = XTSkillCapabilityProfileSupport.unblockActions(
                for: .grantRequired,
                approvalFloor: updated.approvalFloor,
                requiredRuntimeSurfaces: updated.requiredRuntimeSurfaces
            )
        case .localApprovalRequired:
            updated.denyCode = "local_approval_required"
            let approvalFloor = updated.approvalFloor.trimmingCharacters(in: .whitespacesAndNewlines)
            if approvalFloor.isEmpty || approvalFloor.lowercased() == XTSkillApprovalFloor.none.rawValue {
                updated.reasonCode = "local approval still pending"
            } else {
                updated.reasonCode = "approval floor \(updated.approvalFloor) requires local confirmation"
            }
            updated.unblockActions = XTSkillCapabilityProfileSupport.unblockActions(
                for: .localApprovalRequired,
                approvalFloor: updated.approvalFloor,
                requiredRuntimeSurfaces: updated.requiredRuntimeSurfaces
            )
        default:
            break
        }

        return updated
    }

    func supervisorEffectiveSkillReadiness(
        from baseReadiness: XTSkillExecutionReadiness,
        record: SupervisorSkillCallRecord,
        ctx: AXProjectContext,
        config: AXProjectConfig,
        toolCall: ToolCall?
    ) -> XTSkillExecutionReadiness {
        let requestRequiresGrant = !(record.requiredCapability?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "").isEmpty
        let explicitGrantPresent = firstNonEmpty(
            record.grantId,
            toolCall?.args["grant_id"]?.stringValue
        )?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
        if record.status == .awaitingAuthorization {
            if requestRequiresGrant && !explicitGrantPresent {
                return supervisorOverriddenSkillReadiness(baseReadiness, state: .grantRequired)
            }
            return supervisorOverriddenSkillReadiness(
                baseReadiness,
                state: .localApprovalRequired
            )
        }
        let grantSatisfied = supervisorSkillGrantSatisfied(
            record: record,
            readiness: baseReadiness,
            toolCall: toolCall
        )
        if requestRequiresGrant && !grantSatisfied {
            return supervisorOverriddenSkillReadiness(baseReadiness, state: .grantRequired)
        }

        guard let baseState = XTSkillCapabilityProfileSupport.readinessState(
            from: baseReadiness.executionReadiness
        ) else {
            return baseReadiness
        }

        switch baseState {
        case .grantRequired:
            guard grantSatisfied else {
                return baseReadiness
            }
            if supervisorSkillRequiresLocalApproval(
                approvalFloor: baseReadiness.approvalFloor,
                ctx: ctx,
                config: config
            ),
            !supervisorSkillLocalApprovalSatisfied(
                record: record,
                readiness: baseReadiness,
                ctx: ctx,
                config: config
            ) {
                return supervisorOverriddenSkillReadiness(
                    baseReadiness,
                    state: .localApprovalRequired
                )
            }
            return supervisorOverriddenSkillReadiness(baseReadiness, state: .ready)
        case .localApprovalRequired:
            if supervisorSkillLocalApprovalSatisfied(
                record: record,
                readiness: baseReadiness,
                ctx: ctx,
                config: config
            ) {
                return supervisorOverriddenSkillReadiness(baseReadiness, state: .ready)
            }
            return baseReadiness
        case .policyClamped:
            guard supervisorGovernedNetworkToolEligibleForRequestScopedOverride(toolCall) else {
                return baseReadiness
            }
            if requestRequiresGrant && !grantSatisfied {
                return supervisorOverriddenSkillReadiness(baseReadiness, state: .grantRequired)
            }
            if supervisorSkillRequiresLocalApproval(
                approvalFloor: baseReadiness.approvalFloor,
                ctx: ctx,
                config: config
            ),
            !supervisorSkillLocalApprovalSatisfied(
                record: record,
                readiness: baseReadiness,
                ctx: ctx,
                config: config
            ) {
                return supervisorOverriddenSkillReadiness(
                    baseReadiness,
                    state: .localApprovalRequired
                )
            }
            return supervisorOverriddenSkillReadiness(baseReadiness, state: .ready)
        default:
            return baseReadiness
        }
    }

    private func supervisorRequestedCapabilityFamilies(
        toolCall: ToolCall?,
        baseReadiness: XTSkillExecutionReadiness?,
        effectiveReadiness: XTSkillExecutionReadiness?
    ) -> [String] {
        if let baseReadiness, !baseReadiness.capabilityFamilies.isEmpty {
            return XTSkillCapabilityProfileSupport.normalizedStrings(
                baseReadiness.capabilityFamilies
            )
        }
        if let effectiveReadiness, !effectiveReadiness.capabilityFamilies.isEmpty {
            return XTSkillCapabilityProfileSupport.normalizedStrings(
                effectiveReadiness.capabilityFamilies
            )
        }
        guard let toolCall else { return [] }
        return XTSkillCapabilityProfileSupport.capabilityFamilies(
            for: toolCall.tool,
            args: toolCall.args
        )
    }

    func hydrateSupervisorSkillGovernanceSnapshot(
        _ record: inout SupervisorSkillCallRecord,
        project: AXProjectEntry,
        ctx: AXProjectContext,
        toolCall: ToolCall?,
        config: AXProjectConfig? = nil,
        registryItem: SupervisorSkillRegistryItem? = nil
    ) {
        let normalizedRequestId = record.requestId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalizedRequestId.isEmpty else { return }

        let resolvedConfig = config ?? supervisorProjectConfig(ctx: ctx)
        let resolvedRegistryItem = registryItem ?? resolvedSupervisorRegistryItem(
            skillId: record.skillId,
            projectId: project.projectId,
            projectName: project.displayName,
            projectRoot: ctx.root
        )
        let currentProfileSnapshot = supervisorProjectEffectiveSkillProfileSnapshot(
            project: project,
            ctx: ctx,
            config: resolvedConfig
        )
        let baseReadiness = supervisorBaseSkillReadiness(
            record: record,
            project: project,
            ctx: ctx,
            config: resolvedConfig,
            registryItem: resolvedRegistryItem
        )
        let effectiveReadiness = baseReadiness.map {
            supervisorEffectiveSkillReadiness(
                from: $0,
                record: record,
                ctx: ctx,
                config: resolvedConfig,
                toolCall: toolCall
            )
        } ?? record.readiness
        let requestedFamilies = supervisorRequestedCapabilityFamilies(
            toolCall: toolCall,
            baseReadiness: baseReadiness,
            effectiveReadiness: effectiveReadiness
        )
        let persistedDeltaApproval = record.deltaApproval.flatMap { delta in
            delta.requestId.trimmingCharacters(in: .whitespacesAndNewlines) == normalizedRequestId
                ? delta
                : nil
        }
        let deltaReason = firstNonEmpty(
            persistedDeltaApproval?.reason,
            baseReadiness?.reasonCode,
            record.resultSummary,
            record.policyReason
        ) ?? "waiting for local governed approval"
        let resolvedDeltaApproval = persistedDeltaApproval ?? XTSkillCapabilityProfileSupport.deltaApproval(
            requestId: normalizedRequestId,
            projectId: project.projectId,
            projectName: project.displayName,
            requestedSkillId: firstNonEmpty(record.requestedSkillId, record.skillId) ?? record.skillId,
            effectiveSkillId: record.skillId,
            toolName: record.toolName,
            requestedCapabilityFamilies: requestedFamilies,
            currentSnapshot: currentProfileSnapshot,
            reason: deltaReason
        )

        if record.resultEvidenceRef?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty != false {
            record.resultEvidenceRef = SupervisorSkillResultEvidenceStore.resultEvidenceRef(
                requestId: normalizedRequestId
            )
        }
        record.deltaApproval = resolvedDeltaApproval
        record.profileDeltaRef = resolvedDeltaApproval == nil
            ? nil
            : SupervisorSkillResultEvidenceStore.profileDeltaRef(for: record.resultEvidenceRef)
        record.readiness = effectiveReadiness
        record.readinessRef = effectiveReadiness == nil
            ? nil
            : SupervisorSkillResultEvidenceStore.readinessRef(for: record.resultEvidenceRef)
    }

    @discardableResult
    func applySupervisorSkillCallStatus(
        requestId: String,
        ctx: AXProjectContext,
        project: AXProjectEntry,
        status: SupervisorSkillCallStatus,
        stepStatus: SupervisorPlanStepStatus,
        resultSummary: String,
        denyCode: String,
        policySource: String? = nil,
        policyReason: String? = nil,
        rawOutput: String? = nil,
        requiredCapability: String? = nil,
        grantRequestId: String? = nil,
        grantId: String? = nil,
        updatedAtMs: Int64,
        triggerSource: SupervisorCommandTriggerSource,
        toolCall: ToolCall?
    ) -> SupervisorSkillCallRecord? {
        let snapshot = SupervisorProjectSkillCallStore.load(for: ctx)
        guard var record = snapshot.calls.first(where: { $0.requestId == requestId }) else { return nil }
        record.status = status
        record.resultSummary = capped(resultSummary, maxChars: 320)
        record.denyCode = denyCode.trimmingCharacters(in: .whitespacesAndNewlines)
        record.policySource = normalizedSupervisorSkillPolicyScalar(policySource)
        record.policyReason = normalizedSupervisorSkillPolicyScalar(policyReason)
        if let requiredCapability, !requiredCapability.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            record.requiredCapability = requiredCapability.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        if let grantRequestId, !grantRequestId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            record.grantRequestId = grantRequestId.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        if let grantId, !grantId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            record.grantId = grantId.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        record.updatedAtMs = updatedAtMs
        hydrateSupervisorSkillGovernanceSnapshot(
            &record,
            project: project,
            ctx: ctx,
            toolCall: toolCall
        )
        record.resultEvidenceRef = SupervisorSkillResultEvidenceStore.write(
            record: record,
            toolCall: toolCall,
            rawOutput: rawOutput,
            triggerSource: triggerSource.rawValue,
            ctx: ctx
        ) ?? record.resultEvidenceRef
        try? SupervisorProjectSkillCallStore.upsert(record, for: ctx)
        _ = updateSupervisorWorkflowStepState(
            ctx: ctx,
            project: project,
            jobId: record.jobId,
            planId: record.planId,
            stepId: record.stepId,
            status: stepStatus,
            detail: record.resultSummary,
            owner: record.currentOwner,
            updatedAtMs: updatedAtMs
        )
        appendSupervisorSkillCallRawLog(
            action: status.rawValue,
            record: record,
            toolCall: toolCall,
            triggerSource: triggerSource,
            ctx: ctx
        )
        appendSupervisorSkillResultRawLog(
            record: record,
            toolCall: toolCall,
            rawOutput: rawOutput,
            triggerSource: triggerSource,
            ctx: ctx
        )
        if status != .running && status != .queued {
            appendRecentEvent(
                "skill_result: \(project.displayName) -> \(record.skillId) \(status.rawValue)",
                project: project
            )
        }
        return record
    }

    func normalizedSupervisorSkillPolicyScalar(_ raw: String?) -> String? {
        let trimmed = (raw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    @discardableResult
    func updateSupervisorWorkflowStepState(
        ctx: AXProjectContext,
        project: AXProjectEntry,
        jobId: String,
        planId: String,
        stepId: String,
        status: SupervisorPlanStepStatus,
        detail: String,
        owner: String?,
        updatedAtMs: Int64
    ) -> Bool {
        let planSnapshot = SupervisorProjectPlanStore.load(for: ctx)
        guard var plan = planSnapshot.plans.first(where: { $0.planId == planId })
            ?? planSnapshot.plans.first(where: { $0.jobId == jobId && $0.steps.contains(where: { $0.stepId == stepId }) }) else {
            return false
        }
        guard let stepIndex = plan.steps.firstIndex(where: { $0.stepId == stepId }) else { return false }
        let jobSnapshot = SupervisorProjectJobStore.load(for: ctx)
        guard var job = jobSnapshot.jobs.first(where: { $0.jobId == jobId }) else { return false }

        plan.steps[stepIndex].status = status
        plan.steps[stepIndex].detail = capped(detail, maxChars: 320)
        if let owner, !owner.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            plan.steps[stepIndex].currentOwner = owner
            job.currentOwner = owner
        }
        plan.steps[stepIndex].updatedAtMs = updatedAtMs
        plan.updatedAtMs = updatedAtMs
        plan.status = derivedPlanStatus(from: plan.steps)
        job.activePlanId = plan.planId
        job.status = derivedJobStatus(from: plan)
        job.updatedAtMs = updatedAtMs

        do {
            try SupervisorProjectPlanStore.upsert(plan, for: ctx)
            try SupervisorProjectJobStore.upsert(job, for: ctx)
        } catch {
            return false
        }

        currentTask = SupervisorTask(
            id: job.jobId,
            projectId: job.projectId,
            title: job.goal,
            status: job.status.rawValue,
            createdAt: Double(job.createdAtMs) / 1000.0
        )
        syncSupervisorProjectWorkflowCanonical(ctx: ctx, project: project)
        return true
    }

    func supervisorSkillPreflightFailureMessage(
        displaySkill: String,
        verdict: SupervisorSkillPreflightVerdict
    ) -> String {
        switch verdict.denyCode {
        case "preflight_quarantined":
            return "❌ CALL_SKILL 失败：技能 \(displaySkill) 当前处于 quarantine，不能执行（preflight_quarantined）"
        default:
            return "❌ CALL_SKILL 失败：技能 \(displaySkill) 的 preflight 未通过（preflight_failed）"
        }
    }

    func supervisorSkillRegistryIncludesHubTruth(
        _ snapshot: SupervisorSkillRegistrySnapshot
    ) -> Bool {
        snapshot.memorySource
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .contains("hub_skill_registry")
    }

    private func supervisorMissingMultimodalWrapperHint(
        requestedSkillId: String,
        effectiveSkillId: String
    ) -> SupervisorMissingMultimodalWrapperHint? {
        let canonicalEffective = AXSkillsLibrary.canonicalSupervisorSkillID(effectiveSkillId)
        let canonicalRequested = AXSkillsLibrary.canonicalSupervisorSkillID(requestedSkillId)
        let canonicalSkillId = firstNonEmptyString(canonicalEffective, canonicalRequested) ?? ""
        guard !canonicalSkillId.isEmpty else { return nil }

        let globalSnapshot = AXSkillsLibrary.supervisorGlobalSkillRegistrySnapshot(
            hubBaseDir: HubPaths.baseDir()
        )
        let globalSkillIDs = Set(globalSnapshot.items.map {
            AXSkillsLibrary.canonicalSupervisorSkillID($0.skillId)
        })
        guard globalSkillIDs.contains("find-skills"),
              globalSkillIDs.contains("request-skill-enable") else {
            return nil
        }

        switch canonicalSkillId {
        case "local-ocr":
            return SupervisorMissingMultimodalWrapperHint(
                wrapperSkillId: "local-ocr",
                suggestedQuery: "local-ocr",
                capabilityLabel: "OCR / 图片文字提取"
            )
        case "local-vision":
            return SupervisorMissingMultimodalWrapperHint(
                wrapperSkillId: "local-vision",
                suggestedQuery: "local-vision",
                capabilityLabel: "图片理解 / multimodal"
            )
        case "local-transcribe":
            return SupervisorMissingMultimodalWrapperHint(
                wrapperSkillId: "local-transcribe",
                suggestedQuery: "local-transcribe",
                capabilityLabel: "音频转写 / speech-to-text"
            )
        case "local-tts":
            return SupervisorMissingMultimodalWrapperHint(
                wrapperSkillId: "local-tts",
                suggestedQuery: "local-tts",
                capabilityLabel: "语音合成 / text-to-speech"
            )
        case "local-embeddings":
            return SupervisorMissingMultimodalWrapperHint(
                wrapperSkillId: "local-embeddings",
                suggestedQuery: "local-embeddings",
                capabilityLabel: "向量嵌入 / embedding"
            )
        default:
            return nil
        }
    }

    func supervisorMissingMultimodalWrapperRecoveryMessage(
        requestedSkillId: String,
        effectiveSkillId: String
    ) -> String? {
        guard let hint = supervisorMissingMultimodalWrapperHint(
            requestedSkillId: requestedSkillId,
            effectiveSkillId: effectiveSkillId
        ) else {
            return nil
        }

        return """
当前项目还没有 `\(hint.wrapperSkillId)` 这类本地多模态 wrapper。若要继续 \(hint.capabilityLabel) 链路，请先用 `CALL_GLOBAL_SKILL` 调 `find-skills` 搜索 `\(hint.suggestedQuery)`，再把返回结果里的精确 `skill_id` 和 `package_sha256` 原样传给 `request-skill-enable`；不要编造 `package_sha256`，也不要把这类请求降级成无根据的纯文本猜测。
"""
    }

    @discardableResult
    func persistBlockedSupervisorSkillCall(
        requestId: String,
        project: AXProjectEntry,
        ctx: AXProjectContext,
        jobId: String,
        planId: String,
        stepId: String,
        skillId: String,
        requestedSkillId: String? = nil,
        routingReasonCode: String? = nil,
        routingExplanation: String? = nil,
        toolName: String = "",
        payload: [String: JSONValue],
        currentOwner: String,
        resultSummary: String,
        denyCode: String,
        policySource: String? = nil,
        policyReason: String? = nil,
        toolCall: ToolCall? = nil,
        triggerSource: SupervisorCommandTriggerSource,
        updatedAtMs: Int64
    ) -> SupervisorSkillCallRecord {
        var blocked = SupervisorSkillCallRecord(
            schemaVersion: SupervisorSkillCallRecord.currentSchemaVersion,
            requestId: requestId,
            projectId: project.projectId,
            jobId: jobId,
            planId: planId,
            stepId: stepId,
            skillId: skillId,
            requestedSkillId: requestedSkillId,
            routingReasonCode: routingReasonCode,
            routingExplanation: routingExplanation,
            toolName: toolName,
            status: .blocked,
            payload: payload,
            currentOwner: currentOwner,
            resultSummary: resultSummary,
            denyCode: denyCode,
            policySource: policySource,
            policyReason: policyReason,
            resultEvidenceRef: nil,
            requiredCapability: nil,
            grantRequestId: nil,
            grantId: nil,
            createdAtMs: updatedAtMs,
            updatedAtMs: updatedAtMs,
            auditRef: "audit-xt-supervisor-skill-\(String(requestId.suffix(12)))"
        )
        hydrateSupervisorSkillGovernanceSnapshot(
            &blocked,
            project: project,
            ctx: ctx,
            toolCall: toolCall
        )
        blocked.resultEvidenceRef = SupervisorSkillResultEvidenceStore.write(
            record: blocked,
            toolCall: toolCall,
            rawOutput: nil,
            triggerSource: triggerSource.rawValue,
            ctx: ctx
        )
        try? SupervisorProjectSkillCallStore.upsert(blocked, for: ctx)
        _ = updateSupervisorWorkflowStepState(
            ctx: ctx,
            project: project,
            jobId: jobId,
            planId: planId,
            stepId: stepId,
            status: .blocked,
            detail: blocked.resultSummary,
            owner: blocked.currentOwner,
            updatedAtMs: updatedAtMs
        )
        appendSupervisorSkillCallRawLog(
            action: "blocked",
            record: blocked,
            toolCall: toolCall,
            triggerSource: triggerSource,
            ctx: ctx
        )
        appendSupervisorSkillResultRawLog(
            record: blocked,
            toolCall: toolCall,
            rawOutput: nil,
            triggerSource: triggerSource,
            ctx: ctx
        )
        appendRecentEvent(
            "skill_result: \(project.displayName) -> \(blocked.skillId) \(blocked.status.rawValue)",
            project: project
        )
        return blocked
    }

    func appendSupervisorSkillCallRawLog(
        action: String,
        record: SupervisorSkillCallRecord,
        toolCall: ToolCall?,
        triggerSource: SupervisorCommandTriggerSource,
        ctx: AXProjectContext
    ) {
        var row: [String: Any] = [
            "type": "supervisor_skill_call",
            "action": action,
            "schema_version": SupervisorSkillCallRecord.currentSchemaVersion,
            "request_id": record.requestId,
            "project_id": record.projectId,
            "job_id": record.jobId,
            "plan_id": record.planId,
            "step_id": record.stepId,
            "skill_id": record.skillId,
            "tool_name": record.toolName,
            "status": record.status.rawValue,
            "current_owner": record.currentOwner,
            "trigger_source": triggerSource.rawValue,
            "audit_ref": record.auditRef,
            "timestamp_ms": record.updatedAtMs
        ]
        if !record.resultSummary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            row["result_summary"] = record.resultSummary
        }
        if let requestedSkillId = record.requestedSkillId?.trimmingCharacters(in: .whitespacesAndNewlines),
           !requestedSkillId.isEmpty {
            row["requested_skill_id"] = requestedSkillId
        }
        if let routingReasonCode = record.routingReasonCode?.trimmingCharacters(in: .whitespacesAndNewlines),
           !routingReasonCode.isEmpty {
            row["routing_reason_code"] = routingReasonCode
        }
        if let routingExplanation = record.routingExplanation?.trimmingCharacters(in: .whitespacesAndNewlines),
           !routingExplanation.isEmpty {
            row["routing_explanation"] = routingExplanation
        }
        if !record.denyCode.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            row["deny_code"] = record.denyCode
        }
        if let policySource = record.policySource?.trimmingCharacters(in: .whitespacesAndNewlines),
           !policySource.isEmpty {
            row["policy_source"] = policySource
        }
        if let policyReason = record.policyReason?.trimmingCharacters(in: .whitespacesAndNewlines),
           !policyReason.isEmpty {
            row["policy_reason"] = policyReason
        }
        if let resultEvidenceRef = record.resultEvidenceRef?.trimmingCharacters(in: .whitespacesAndNewlines),
           !resultEvidenceRef.isEmpty {
            row["result_evidence_ref"] = resultEvidenceRef
        }
        if let profileDeltaRef = record.profileDeltaRef?.trimmingCharacters(in: .whitespacesAndNewlines),
           !profileDeltaRef.isEmpty {
            row["profile_delta_ref"] = profileDeltaRef
        }
        if let readinessRef = record.readinessRef?.trimmingCharacters(in: .whitespacesAndNewlines),
           !readinessRef.isEmpty {
            row["readiness_ref"] = readinessRef
        }
        if let capability = record.requiredCapability?.trimmingCharacters(in: .whitespacesAndNewlines),
           !capability.isEmpty {
            row["required_capability"] = capability
        }
        if let grantRequestId = record.grantRequestId?.trimmingCharacters(in: .whitespacesAndNewlines),
           !grantRequestId.isEmpty {
            row["grant_request_id"] = grantRequestId
        }
        if let grantId = record.grantId?.trimmingCharacters(in: .whitespacesAndNewlines),
           !grantId.isEmpty {
            row["grant_id"] = grantId
        }
        if let toolCall {
            row["tool"] = toolCall.tool.rawValue
            row["tool_args"] = foundationJSONObject(from: toolCall.args)
        }
        appendSupervisorSkillDeltaApproval(to: &row, deltaApproval: record.deltaApproval)
        appendSupervisorSkillReadiness(to: &row, readiness: record.readiness)
        AXProjectStore.appendRawLog(row, for: ctx)
    }

    func appendSupervisorSkillResultRawLog(
        record: SupervisorSkillCallRecord,
        toolCall: ToolCall?,
        rawOutput: String?,
        triggerSource: SupervisorCommandTriggerSource,
        ctx: AXProjectContext
    ) {
        var row: [String: Any] = [
            "type": "supervisor_skill_result",
            "schema_version": SupervisorSkillResultEvidence.currentSchemaVersion,
            "request_id": record.requestId,
            "project_id": record.projectId,
            "job_id": record.jobId,
            "plan_id": record.planId,
            "step_id": record.stepId,
            "skill_id": record.skillId,
            "tool_name": record.toolName,
            "status": record.status.rawValue,
            "result_summary": record.resultSummary,
            "deny_code": record.denyCode,
            "trigger_source": triggerSource.rawValue,
            "audit_ref": record.auditRef,
            "updated_at_ms": record.updatedAtMs
        ]
        if let resultEvidenceRef = record.resultEvidenceRef?.trimmingCharacters(in: .whitespacesAndNewlines),
           !resultEvidenceRef.isEmpty {
            row["result_evidence_ref"] = resultEvidenceRef
            let normalizedOutput = (rawOutput ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            if !normalizedOutput.isEmpty {
                row["raw_output_ref"] = "\(resultEvidenceRef)#raw_output"
                row["raw_output_chars"] = normalizedOutput.count
            }
        }
        if let profileDeltaRef = record.profileDeltaRef?.trimmingCharacters(in: .whitespacesAndNewlines),
           !profileDeltaRef.isEmpty {
            row["profile_delta_ref"] = profileDeltaRef
        }
        if let readinessRef = record.readinessRef?.trimmingCharacters(in: .whitespacesAndNewlines),
           !readinessRef.isEmpty {
            row["readiness_ref"] = readinessRef
        }
        if let uiReviewAgentEvidenceRef = supervisorUIReviewAgentEvidenceRef(from: rawOutput) {
            row["ui_review_agent_evidence_ref"] = uiReviewAgentEvidenceRef
        }
        if let requestedSkillId = record.requestedSkillId?.trimmingCharacters(in: .whitespacesAndNewlines),
           !requestedSkillId.isEmpty {
            row["requested_skill_id"] = requestedSkillId
        }
        if let routingReasonCode = record.routingReasonCode?.trimmingCharacters(in: .whitespacesAndNewlines),
           !routingReasonCode.isEmpty {
            row["routing_reason_code"] = routingReasonCode
        }
        if let routingExplanation = record.routingExplanation?.trimmingCharacters(in: .whitespacesAndNewlines),
           !routingExplanation.isEmpty {
            row["routing_explanation"] = routingExplanation
        }
        if let policySource = record.policySource?.trimmingCharacters(in: .whitespacesAndNewlines),
           !policySource.isEmpty {
            row["policy_source"] = policySource
        }
        if let policyReason = record.policyReason?.trimmingCharacters(in: .whitespacesAndNewlines),
           !policyReason.isEmpty {
            row["policy_reason"] = policyReason
        }
        if let capability = record.requiredCapability?.trimmingCharacters(in: .whitespacesAndNewlines),
           !capability.isEmpty {
            row["required_capability"] = capability
        }
        if let toolCall {
            row["tool"] = toolCall.tool.rawValue
            row["tool_args"] = foundationJSONObject(from: toolCall.args)
        }
        appendSupervisorSkillDeltaApproval(to: &row, deltaApproval: record.deltaApproval)
        appendSupervisorSkillReadiness(to: &row, readiness: record.readiness)
        appendGovernanceTruthSnapshot(to: &row, rawOutput: rawOutput)
        AXProjectStore.appendRawLog(row, for: ctx)
    }

    private func appendSupervisorSkillReadiness(
        to row: inout [String: Any],
        readiness: XTSkillExecutionReadiness?
    ) {
        guard let readiness else { return }
        if !readiness.intentFamilies.isEmpty {
            row["intent_families"] = readiness.intentFamilies
        }
        if !readiness.capabilityFamilies.isEmpty {
            row["capability_families"] = readiness.capabilityFamilies
        }
        if !readiness.capabilityProfiles.isEmpty {
            row["capability_profiles"] = readiness.capabilityProfiles
        }
        row["execution_readiness"] = readiness.executionReadiness
        row["state_label"] = readiness.stateLabel
        row["grant_floor"] = readiness.grantFloor
        row["approval_floor"] = readiness.approvalFloor
        row["required_runtime_surfaces"] = readiness.requiredRuntimeSurfaces
        row["unblock_actions"] = readiness.unblockActions
        if !readiness.reasonCode.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            row["readiness_reason_code"] = readiness.reasonCode
        }
    }

    private func appendSupervisorSkillDeltaApproval(
        to row: inout [String: Any],
        deltaApproval: XTSkillProfileDeltaApproval?
    ) {
        guard let deltaApproval else { return }
        row["approval_summary"] = deltaApproval.summary
        row["current_runnable_profiles"] = deltaApproval.currentRunnableProfiles
        row["requested_profiles"] = deltaApproval.requestedProfiles
        row["delta_profiles"] = deltaApproval.deltaProfiles
        row["current_runnable_capability_families"] = deltaApproval.currentRunnableCapabilityFamilies
        row["requested_capability_families"] = deltaApproval.requestedCapabilityFamilies
        row["delta_capability_families"] = deltaApproval.deltaCapabilityFamilies
        row["grant_floor"] = deltaApproval.grantFloor
        row["approval_floor"] = deltaApproval.approvalFloor
    }

    private func supervisorUIReviewAgentEvidenceRef(
        from output: String?
    ) -> String? {
        guard let summary = structuredToolSummaryObject(from: output) else { return nil }
        let candidate = [
            summary["ui_review_agent_evidence_ref"]?.stringValue,
            summary["browser_runtime_ui_review_agent_evidence_ref"]?.stringValue
        ]
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .first(where: { !$0.isEmpty })
        return candidate
    }

    private func appendGovernanceTruthSnapshot(
        to row: inout [String: Any],
        rawOutput: String?
    ) {
        guard let summary = structuredToolSummaryObject(from: rawOutput) else { return }
        for (key, value) in xtPersistedGovernanceEvidenceFields(from: summary) {
            row[key] = foundationValue(from: value)
        }
    }

    private func structuredToolSummaryObject(
        from output: String?
    ) -> [String: JSONValue]? {
        let normalizedOutput = (output ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalizedOutput.isEmpty else { return nil }
        let parsed = ToolExecutor.parseStructuredToolOutput(normalizedOutput)
        guard case .object(let summary)? = parsed.summary else { return nil }
        return summary
    }

    private func supervisorUIReviewAgentEvidenceRef(
        requestId: String,
        ctx: AXProjectContext
    ) -> String? {
        let normalizedRequestId = requestId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalizedRequestId.isEmpty,
              let evidence = SupervisorSkillResultEvidenceStore.load(requestId: normalizedRequestId, for: ctx) else {
            return nil
        }
        return [
            evidence.uiReviewAgentEvidenceRef,
            supervisorUIReviewAgentEvidenceRef(from: evidence.rawOutput),
            supervisorUIReviewAgentEvidenceRef(from: evidence.rawOutputPreview)
        ]
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .first(where: { !$0.isEmpty })
    }

    private func supervisorUIReviewAgentEvidenceSnapshot(
        requestId: String,
        ctx: AXProjectContext
    ) -> XTUIReviewAgentEvidenceSnapshot? {
        guard let ref = supervisorUIReviewAgentEvidenceRef(requestId: requestId, ctx: ctx) else {
            return nil
        }
        return XTUIReviewAgentEvidenceStore.load(ref: ref, for: ctx)
    }

    private func supervisorSkillCallbackUIReviewExtraLines(
        requestId: String,
        ctx: AXProjectContext
    ) -> [String] {
        guard let ref = supervisorUIReviewAgentEvidenceRef(requestId: requestId, ctx: ctx),
              let snapshot = XTUIReviewAgentEvidenceStore.load(ref: ref, for: ctx) else {
            return []
        }

        let issueCodes = snapshot.issueCodes.isEmpty
            ? "(none)"
            : snapshot.issueCodes.joined(separator: ",")
        var lines = [
            "ui_review_agent_evidence_ref=\(ref)",
            "ui_review_verdict=\(snapshot.verdict.rawValue)",
            "ui_review_confidence=\(snapshot.confidence.rawValue)",
            "ui_review_objective_ready=\(snapshot.objectiveReady)",
            "ui_review_sufficient_evidence=\(snapshot.sufficientEvidence)",
            "ui_review_issue_codes=\(issueCodes)",
            "ui_review_summary=\(capped(snapshot.summary, maxChars: 220))"
        ]
        if let guidance = SupervisorUIReviewRepairPlanner.guidance(for: snapshot) {
            lines.append("ui_review_repair_action=\(guidance.actionCode)")
            lines.append("ui_review_repair_focus=\(guidance.focusArea)")
            lines.append("ui_review_repair_summary=\(capped(guidance.summary, maxChars: 220))")
            lines.append("ui_review_repair_prompt=\(capped(guidance.prompt, maxChars: 260))")
        }
        if let trend = snapshot.trend.first(where: { $0.lowercased().contains("status=") }) {
            lines.append("ui_review_trend=\(trend)")
        }
        if supervisorShouldRouteToUIReview(snapshot) {
            lines.append("next_safe_action=open_ui_review")
        }
        return lines
    }

    func supervisorShouldRouteToUIReview(
        requestId: String,
        ctx: AXProjectContext
    ) -> Bool {
        guard let snapshot = supervisorUIReviewAgentEvidenceSnapshot(requestId: requestId, ctx: ctx) else {
            return false
        }
        return supervisorShouldRouteToUIReview(snapshot)
    }

    private func supervisorShouldRouteToUIReview(
        _ snapshot: XTUIReviewAgentEvidenceSnapshot
    ) -> Bool {
        if snapshot.verdict != .ready {
            return true
        }
        if !snapshot.objectiveReady || !snapshot.sufficientEvidence {
            return true
        }

        let issueCodes = Set(
            snapshot.issueCodes.map {
                $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            }
        )
        if issueCodes.contains("critical_action_not_visible") ||
            issueCodes.contains("interactive_target_missing") {
            return true
        }

        return snapshot.trend.contains(where: {
            $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased().contains("status=regressed")
        })
    }

    func supervisorToolResultPolicyContext(
        from output: String
    ) -> (denyCode: String, policySource: String, policyReason: String) {
        let parsed = ToolExecutor.parseStructuredToolOutput(output)
        guard case .object(let summary)? = parsed.summary else {
            return ("", "", "")
        }
        let denyCode = normalizedSupervisorSkillPolicyScalar(summary["deny_code"]?.stringValue) ?? ""
        let policySource = normalizedSupervisorSkillPolicyScalar(summary["policy_source"]?.stringValue) ?? ""
        let runtimeSurfacePolicyReason = normalizedSupervisorSkillPolicyScalar(
            summary["runtime_surface_policy_reason"]?.stringValue
        ) ?? ""
        let policyReason = !runtimeSurfacePolicyReason.isEmpty
            ? runtimeSurfacePolicyReason
            : (normalizedSupervisorSkillPolicyScalar(summary["policy_reason"]?.stringValue) ?? "")
        return (denyCode, policySource, policyReason)
    }

    func summarizedSupervisorSkillOutput(
        _ output: String,
        ok: Bool,
        toolCall: ToolCall? = nil
    ) -> String {
        let trimmed = output.trimmingCharacters(in: .whitespacesAndNewlines)
        if let toolCall {
            let toolResult = ToolResult(
                id: toolCall.id,
                tool: toolCall.tool,
                ok: ok,
                output: output
            )
            if let specialized = ToolResultHumanSummary.specializedSummary(for: toolResult) {
                return capped(
                    "\(toolCall.tool.rawValue) \(ok ? "completed" : "failed"): \(specialized)",
                    maxChars: 320
                )
            }
            switch toolCall.tool {
            case .write_file:
                let path = toolCall.args["path"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if ok, trimmed == "ok" {
                    return capped("write_file completed: \(path)", maxChars: 320)
                }
                if !trimmed.isEmpty {
                    return capped("write_file \(ok ? "completed" : "failed"): \(path)\n\(trimmed)", maxChars: 320)
                }
            case .delete_path:
                let path = toolCall.args["path"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if ok, trimmed.hasPrefix("{") || trimmed.hasPrefix("delete_path") {
                    return capped("delete_path completed: \(path)", maxChars: 320)
                }
                if !trimmed.isEmpty {
                    return capped("delete_path \(ok ? "completed" : "failed"): \(path)\n\(trimmed)", maxChars: 320)
                }
            case .move_path:
                let fromPath = toolCall.args["from"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                let toPath = toolCall.args["to"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if ok, trimmed.hasPrefix("{") || trimmed.hasPrefix("move_path") {
                    return capped("move_path completed: \(fromPath) -> \(toPath)", maxChars: 320)
                }
                if !trimmed.isEmpty {
                    return capped("move_path \(ok ? "completed" : "failed"): \(fromPath) -> \(toPath)\n\(trimmed)", maxChars: 320)
                }
            case .run_command:
                let command = toolCall.args["command"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if ok, trimmed.hasPrefix("exit: 0") {
                    return capped("run_command completed: \(command)", maxChars: 320)
                }
                if !trimmed.isEmpty {
                    return capped("run_command \(ok ? "completed" : "failed"): \(command)\n\(trimmed)", maxChars: 320)
                }
            case .git_commit:
                let message = toolCall.args["message"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if !trimmed.isEmpty {
                    return capped("git_commit \(ok ? "completed" : "failed"): \(message)\n\(trimmed)", maxChars: 320)
                }
            case .git_push:
                let remote = toolCall.args["remote"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(default)"
                let branch = toolCall.args["branch"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(default)"
                if !trimmed.isEmpty {
                    return capped("git_push \(ok ? "completed" : "failed"): \(remote) \(branch)\n\(trimmed)", maxChars: 320)
                }
            case .process_start:
                let processId = firstNonEmptyString(
                    toolCall.args["process_id"]?.stringValue,
                    toolCall.args["name"]?.stringValue
                ) ?? "(none)"
                if !trimmed.isEmpty {
                    return capped("process_start \(ok ? "completed" : "failed"): \(processId)\n\(trimmed)", maxChars: 320)
                }
            case .process_status:
                let processId = toolCall.args["process_id"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "all"
                if !trimmed.isEmpty {
                    return capped("process_status \(ok ? "completed" : "failed"): \(processId)\n\(trimmed)", maxChars: 320)
                }
            case .process_logs:
                let processId = toolCall.args["process_id"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if !trimmed.isEmpty {
                    return capped("process_logs \(ok ? "completed" : "failed"): \(processId)\n\(trimmed)", maxChars: 320)
                }
            case .process_stop:
                let processId = toolCall.args["process_id"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if !trimmed.isEmpty {
                    return capped("process_stop \(ok ? "completed" : "failed"): \(processId)\n\(trimmed)", maxChars: 320)
                }
            case .pr_create:
                let title = toolCall.args["title"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(fill)"
                if !trimmed.isEmpty {
                    return capped("pr_create \(ok ? "completed" : "failed"): \(title)\n\(trimmed)", maxChars: 320)
                }
            case .ci_read:
                let workflow = toolCall.args["workflow"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(all)"
                if !trimmed.isEmpty {
                    return capped("ci_read \(ok ? "completed" : "failed"): \(workflow)\n\(trimmed)", maxChars: 320)
                }
            case .ci_trigger:
                let workflow = toolCall.args["workflow"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                if !trimmed.isEmpty {
                    return capped("ci_trigger \(ok ? "completed" : "failed"): \(workflow)\n\(trimmed)", maxChars: 320)
                }
            case .git_apply:
                let patchChars = toolCall.args["patch"]?.stringValue?.count ?? 0
                if ok, trimmed.hasPrefix("exit: 0") {
                    return capped("git_apply completed: patch_chars=\(patchChars)", maxChars: 320)
                }
                if !trimmed.isEmpty {
                    return capped("git_apply \(ok ? "completed" : "failed"): patch_chars=\(patchChars)\n\(trimmed)", maxChars: 320)
                }
            case .skills_search:
                let query = toolCall.args["query"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                let parsed = ToolExecutor.parseStructuredToolOutput(output)
                if case .object(let summary)? = parsed.summary,
                   case .number(let count)? = summary["results_count"] {
                    return capped("skills.search completed: \(query) (\(Int(count)) results)", maxChars: 320)
                }
                if !trimmed.isEmpty {
                    return capped("skills.search \(ok ? "completed" : "failed"): \(query)\n\(trimmed)", maxChars: 320)
                }
            case .skills_pin:
                let skillId = toolCall.args["skill_id"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                let scope = toolCall.args["scope"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "global"
                if !trimmed.isEmpty {
                    return capped("skills.pin \(ok ? "enabled" : "failed"): \(skillId) [\(scope)]\n\(trimmed)", maxChars: 320)
                }
            case .agentImportRecord:
                let stagingId = toolCall.args["staging_id"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "(none)"
                let parsed = ToolExecutor.parseStructuredToolOutput(output)
                if case .object(let summary)? = parsed.summary,
                   case .string(let vetterStatus)? = summary["vetter_status"] {
                    let warnCount = {
                        if case .number(let value)? = summary["vetter_warn_count"] {
                            return Int(value)
                        }
                        return 0
                    }()
                    let criticalCount = {
                        if case .number(let value)? = summary["vetter_critical_count"] {
                            return Int(value)
                        }
                        return 0
                    }()
                    return capped(
                        "agent.import.record \(ok ? "completed" : "failed"): \(stagingId) vetter=\(vetterStatus) c\(criticalCount)/w\(warnCount)",
                        maxChars: 320
                    )
                }
                if !trimmed.isEmpty {
                    return capped("agent.import.record \(ok ? "completed" : "failed"): \(stagingId)\n\(trimmed)", maxChars: 320)
                }
            case .summarize:
                let source = firstNonEmptyString(
                    toolCall.args["url"]?.stringValue,
                    toolCall.args["path"]?.stringValue,
                    toolCall.args["text"]?.stringValue
                ) ?? "(inline)"
                if !trimmed.isEmpty {
                    return capped("summarize \(ok ? "completed" : "failed"): \(source)\n\(trimmed)", maxChars: 320)
                }
            case .supervisorVoicePlayback:
                let action = toolCall.args["action"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "status"
                if !trimmed.isEmpty {
                    return capped("supervisor.voice.playback \(ok ? "completed" : "failed"): \(action)\n\(trimmed)", maxChars: 320)
                }
            case .memory_snapshot:
                let parsed = ToolExecutor.parseStructuredToolOutput(output)
                if case .object(let summary)? = parsed.summary,
                   case .string(let profile)? = summary["analysis_profile"],
                   profile == "self_improvement" {
                    let focus = summary["focus"]?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                    let label = focus.isEmpty ? "self_improvement" : "self_improvement: \(focus)"
                    if case .number(let count)? = summary["recommendation_count"] {
                        return capped("\(label) \(ok ? "completed" : "failed"): \(Int(count)) recommendations", maxChars: 320)
                    }
                    return capped("\(label) \(ok ? "completed" : "failed")", maxChars: 320)
                }
            default:
                break
            }
        }
        guard !trimmed.isEmpty else {
            return ok ? "tool execution completed" : "tool execution failed"
        }
        return capped(trimmed, maxChars: 320)
    }

    func isSupervisorSkillCanceled(requestId: String, ctx: AXProjectContext) -> Bool {
        SupervisorProjectSkillCallStore.load(for: ctx).calls.first(where: { $0.requestId == requestId })?.status == .canceled
    }

    func foundationJSONObject(from object: [String: JSONValue]) -> [String: Any] {
        object.reduce(into: [String: Any]()) { partial, item in
            partial[item.key] = foundationValue(from: item.value)
        }
    }

    private func foundationValue(from value: JSONValue) -> Any {
        switch value {
        case .string(let string):
            return string
        case .number(let number):
            return number
        case .bool(let bool):
            return bool
        case .object(let object):
            return foundationJSONObject(from: object)
        case .array(let array):
            return array.map { foundationValue(from: $0) }
        case .null:
            return NSNull()
        }
    }

    private func derivedPlanStatus(from steps: [SupervisorPlanStepRecord]) -> SupervisorPlanStatus {
        let statuses = steps.map(\.status)
        if statuses.isEmpty || statuses.allSatisfy({ $0 == .pending }) {
            return .planning
        }
        if statuses.contains(.awaitingAuthorization) {
            return .awaitingAuthorization
        }
        if statuses.contains(.blocked) {
            return .blocked
        }
        if statuses.allSatisfy({ $0 == .completed }) {
            return .completed
        }
        if statuses.contains(.failed) {
            return .failed
        }
        if statuses.allSatisfy({ $0 == .canceled }) {
            return .canceled
        }
        return .active
    }

    private func derivedJobStatus(from plan: SupervisorPlanRecord) -> SupervisorJobStatus {
        switch plan.status {
        case .planning:
            return .planning
        case .active:
            return .running
        case .blocked:
            return .blocked
        case .awaitingAuthorization:
            return .awaitingAuthorization
        case .completed:
            return .completed
        case .failed:
            return .failed
        case .canceled:
            return .canceled
        }
    }

    private func syncSupervisorProjectWorkflowCanonical(
        ctx: AXProjectContext,
        project: AXProjectEntry
    ) {
        defer { rebuildPendingSupervisorSkillApprovalViewState() }
        let jobSnapshot = SupervisorProjectJobStore.load(for: ctx)
        let planSnapshot = SupervisorProjectPlanStore.load(for: ctx)
        let skillCallSnapshot = SupervisorProjectSkillCallStore.load(for: ctx)
        guard let snapshot = SupervisorProjectWorkflowCanonicalSync.snapshot(
            projectId: project.projectId,
            projectName: project.displayName,
            jobSnapshot: jobSnapshot,
            planSnapshot: planSnapshot,
            skillCallSnapshot: skillCallSnapshot
        ) else {
            return
        }
        HubIPCClient.syncSupervisorProjectWorkflow(snapshot)
    }

    func syncSupervisorProjectHeartbeatMemoryProjection(
        ctx: AXProjectContext,
        project: AXProjectEntry,
        config: AXProjectConfig,
        schedule: SupervisorReviewScheduleState,
        nowMs: Int64
    ) {
        let projectMemoryDiagnostics = AXProjectContextAssemblyDiagnosticsStore.doctorSummary(
            for: ctx,
            config: config
        )
        var snapshot = XTProjectHeartbeatGovernanceDoctorBuilder.build(
            project: project,
            context: ctx,
            config: config,
            projectMemoryReadiness: projectMemoryDiagnostics.memoryAssemblyReadiness,
            now: Date(timeIntervalSince1970: Double(max(0, nowMs)) / 1000.0)
        )
        snapshot.projectMemoryContext = XTHeartbeatProjectMemoryContextSnapshot.from(
            summary: projectMemoryDiagnostics
        )
        let canonicalRecord = SupervisorProjectHeartbeatCanonicalSync.record(
            snapshot: snapshot,
            generatedAtMs: nowMs
        )
        _ = XTHeartbeatMemoryProjectionStore.record(
            ctx: ctx,
            snapshot: snapshot,
            schedule: schedule,
            canonicalRecord: canonicalRecord,
            generatedAtMs: nowMs
        )
        HubIPCClient.syncSupervisorProjectHeartbeat(canonicalRecord)
    }

    private func generateIdentityResponse(
        _ projects: [AXProjectEntry],
        personaSlot: SupervisorPersonaSlot? = nil
    ) -> String {
        let identity = currentSupervisorIdentityProfile(personaSlot: personaSlot)
        let route = currentSupervisorModelRouteSummary()
        return """
不是。当前这个入口的身份是 \(identity.name)，不是一个裸的 GPT 聊天窗口。

对外身份描述：
\(identity.roleSummary)

配置层面上，Supervisor 当前首选的模型路由是：
\(route)

但这条回复本身是本地直答，没有实际通过 Hub 调用模型。所以这里表达的是“当前配置准备优先走哪条路由”，不等于“这轮已经用了 GPT”。

当前接管项目数：\(projects.count)。
"""
    }

    private func supervisorRemoteVerificationHint() -> String {
        """
注意：问“你现在是什么模型”“当前路由是什么”“你是不是 GPT”这类问题，会被 Supervisor 本地直答拦截，不能拿来验证远端模型是否真的可用。

如果你要做真验证：
1. 先执行 `/hub route grpc`
2. 再发一条普通任务请求，例如“请用三句话总结当前项目状态，并给我两个下一步”

如果远端仍失败，我会直接返回 Hub 的失败原因，而不是静默掉回本地。
"""
    }

    private func generateModelRouteStatusResponse(_ projects: [AXProjectEntry]) -> String {
        let configuredRoute = currentSupervisorModelRouteSummary()
        let actualInvocation = lastSupervisorActualInvocationSummary()
        let verification = currentSupervisorModelVerificationSummary()
        let mismatch = currentSupervisorModelMismatchSummary()
        let transport = currentHubTransportSummary()
        return """
如果你问的是这条回复本身：这条是本地直答，没有实际通过 Hub 调用模型。

以下记录只针对 Supervisor 角色；Project AI / coder / reviewer 的模型路由与最近调用彼此独立，不能混读。

当前配置的 Supervisor 首选模型路由：
\(configuredRoute)

当前 Hub transport:
\(transport)

当前验证状态：
\(verification)

\(mismatch.map { "当前差异提示：\n\($0)\n" } ?? "")

最近一次真实调用记录：
\(actualInvocation)

所以你看到某次回复里自称“阿里巴巴集团研发”这类话，不能直接拿来判断当前实际模型，更不能据此断定 paid GPT 一定不可用。更可能是那一轮把“模型身份问题”交给了模型自由回答。

\(supervisorRemoteVerificationHint())

当前接管项目数：\(projects.count)。
"""
