    private func generateSupervisorMemoryRuntimeTruthResponse(
        _ userMessage: String,
        projects: [AXProjectEntry]
    ) -> String {
        let normalized = normalizedSupervisorIntentText(userMessage)
        let contract = XTMemoryRoleScopedRouter.contract(for: .supervisorOrchestration)
        let snapshot = supervisorMemoryAssemblySnapshot
        let memorySource = snapshot?.source.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            ? snapshot?.source ?? supervisorMemorySource
            : supervisorMemorySource
        let memorySourceLabel = XTMemorySourceTruthPresentation.explainableLabel(memorySource)
        let rawProfile = snapshot.flatMap {
            XTSupervisorRecentRawContextProfile(rawValue: $0.rawWindowProfile)
        } ?? currentSupervisorRecentRawContextProfile()
        let rawSource = snapshot?.rawWindowSource ?? "xt_cache"
        let rawSourceLabel = XTMemorySourceTruthPresentation.explainableLabel(rawSource)
        let constitutionLine = configuredSupervisorConstitutionOneLiner()
        let constitutionPath = configuredSupervisorConstitutionURL().path
        let allowedLayers = contract.allowedLayers
            .sorted { $0.rawValue < $1.rawValue }
            .map(\.rawValue)
            .joined(separator: ", ")

        let lead: String
        if isSupervisorConstitutionTruthQuestion(normalized) {
            lead = "先说 X-宪章：当前是生效的，但现在喂给 Supervisor 的是显式 `[L0_CONSTITUTION]` 摘要块，不是整份全文 dump。"
        } else if isSupervisorRecentContextTruthQuestion(normalized) {
            lead = "先说最近原始上下文：硬底线固定是 8 个来回，不是模型自己估的“十来轮左右”。"
        } else {
            lead = "先说记忆来源：现在不是纯 Hub-only。durable truth 目标在 Hub，但 XT 运行时仍保留本地 continuity overlay / fallback。"
        }

        var lines: [String] = [
            "这类问题我按本地 runtime truth 回，不走模型自由发挥。",
            "",
            lead,
            "",
            "当前事实：",
            "- durable truth 目标：Hub Writer + Gate",
            "- 当前 Supervisor 记忆装配来源：\(memorySourceLabel)",
            "- XT 本地角色：continuity overlay / fallback，不是新的 durable truth",
            "- 当前编排合同：supervisor_orchestration",
            "- 当前允许层：\(allowedLayers)",
            "- 长期记忆策略：\(contract.longtermPolicy.rawValue)（默认给摘要，不会把长历史全文直接塞进来）",
            "- X-宪章：已生效；当前会以 `[L0_CONSTITUTION]` 注入",
            "- 宪章来源：\(constitutionPath)",
            "- 当前宪章摘要：\(constitutionLine)"
        ]

        if contract.allowedLayers.contains(.l4RawEvidence) {
            lines.append("- L4 原始证据：当前 supervisor contract 允许直接下发")
        } else {
            lines.append("- L4 原始证据：当前 supervisor contract 默认不直接下发")
        }

        if let snapshot {
            let floorText = snapshot.continuityFloorSatisfied
                ? "已满足底线"
                : "还没满足底线"
            let ceilingText = snapshot.rawWindowCeilingPairs.map { "\($0) 个来回 ceiling" } ?? "Auto Max"
            lines.append("- 最近原始上下文：硬底线 \(snapshot.rawWindowFloorPairs) 个来回；最近一次实际带入 \(snapshot.rawWindowSelectedPairs) 组；来源 \(rawSourceLabel)；\(floorText)")
            lines.append("- 当前窗口档位：\(rawProfile.displayName)（\(rawProfile.shortLabel)，\(ceilingText)）")
        } else {
            let ceilingText = rawProfile.windowCeilingPairs.map { "\($0) 个来回 ceiling" } ?? "Auto Max"
            lines.append("- 最近原始上下文：硬底线 \(XTSupervisorRecentRawContextProfile.hardFloorPairs) 个来回；当前配置是 \(rawProfile.displayName)（\(ceilingText)）")
            lines.append("- 最近一次装配快照：暂无，所以这轮实际带入多少组还没有可报告的 runtime truth")
        }

        lines.append("")
        lines.append("这条回复本身是本地直答，只读取当前 runtime contract 和最近装配快照，不会再额外触发一次 Hub 模型调用。")
        lines.append("")
        lines.append("当前接管项目数：\(projects.count)。")
        return lines.joined(separator: "\n")
    }

