    private func configuredSupervisorConstitutionURL() -> URL {
        HubPaths.baseDir()
            .appendingPathComponent("memory", isDirectory: true)
            .appendingPathComponent("ax_constitution.json")
    }

    private func defaultSupervisorConstitutionFallback() -> String {
        "真实透明、最小化外发；仅在高风险或不可逆动作时先解释后执行；普通编程/创作请求直接给出可执行答案。"
    }

    private func configuredSupervisorConstitutionOneLiner() -> String {
        let url = configuredSupervisorConstitutionURL()
        guard let data = try? Data(contentsOf: url),
              let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return defaultSupervisorConstitutionFallback()
        }

        if let one = obj["one_liner"] as? [String: Any] {
            let zh = (one["zh"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            if !zh.isEmpty {
                return normalizedConstitutionOneLiner(zh)
            }
            let en = (one["en"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            if !en.isEmpty {
                return normalizedConstitutionOneLiner(en)
            }
        }
        return defaultSupervisorConstitutionFallback()
    }

    private func captureSupervisorPersonalMemoryIfNeeded(
        from userMessage: String
    ) -> SupervisorPersonalMemoryAutoCaptureResult? {
        let additionalRecords = SupervisorPersonalMemoryAutoCapture.extractAdditionalRecords(
            from: userMessage
        )
        for record in additionalRecords {
            supervisorPersonalMemoryStore.upsert(
                record,
                intent: .directCaptureFallback
            )
        }

        guard let capture = SupervisorPersonalMemoryAutoCapture.extract(from: userMessage) else {
            return nil
        }

        let currentName = currentSupervisorStoredPreferredUserName()?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        let nextName = capture.preferredUserName
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()

        if currentName != nextName {
            supervisorPersonalMemoryStore.upsert(
                capture.preferredUserNameRecord(),
                intent: .directCaptureFallback
            )
        }

        return capture
    }

    private func localSupervisorPersonalMemoryCaptureReply(
        for userMessage: String,
        capture: SupervisorPersonalMemoryAutoCaptureResult?
    ) -> String? {
        guard let capture, capture.isStandaloneStatement else { return nil }
        guard SupervisorPersonalMemoryAutoCapture.extract(from: userMessage) != nil else {
            return nil
        }
        return "记住了，我会叫你 \(capture.preferredUserName)。"
    }

