    private func inferredExecutionTrack(for userMessage: String) -> String {
        let normalized = normalizedSupervisorIntentText(userMessage)
        if containsAny(normalized, ["mac", "macos", "桌面"]) {
            return "macOS 桌面版"
        }
        if containsAny(normalized, ["ios", "iphone", "ipad"]) {
            return "iOS 版"
        }
        if containsAny(normalized, ["终端", "命令行", "cli"]) {
            return "终端版"
        }
        if containsAny(normalized, ["网页", "网站", "浏览器", "html", "web"]) {
            return "网页版"
        }
        if containsAny(normalized, ["游戏", "贪食蛇", "贪吃蛇", "snake", "game"]) {
            return "网页版"
        }
        return "最小可运行版本"
    }

    private func installPendingSupervisorExecutionIntake(
        for userMessage: String
    ) -> SupervisorPendingExecutionIntake {
        let goalSummary = executionIntakeGoalSummary(from: userMessage)
        let track = inferredExecutionTrack(for: userMessage)
        let suggestedProjectName = inferredExecutionProjectName(from: goalSummary, track: track)
        return installPendingSupervisorExecutionIntake(
            originalRequest: userMessage,
            goalSummary: goalSummary,
            track: track,
            suggestedProjectName: suggestedProjectName
        )
    }

    private func installPendingSupervisorExecutionIntake(
        originalRequest: String,
        goalSummary: String,
        track: String,
        suggestedProjectName: String
    ) -> SupervisorPendingExecutionIntake {
        let now = Date().timeIntervalSince1970
        let intake = SupervisorPendingExecutionIntake(
            originalRequest: originalRequest.trimmingCharacters(in: .whitespacesAndNewlines),
            goalSummary: goalSummary,
            track: track,
            suggestedProjectName: suggestedProjectName,
            createdAt: now,
            updatedAt: now
        )
        pendingSupervisorExecutionIntake = intake
        return intake
    }

    private func primeSupervisorMemoryAwareConversationStateIfNeeded(
        _ userMessage: String
    ) {
        let normalized = normalizedSupervisorIntentText(userMessage)
        guard isExecutionIntakeRequest(normalized) else { return }
        _ = installPendingSupervisorExecutionIntake(for: userMessage)
    }

    private func activePendingSupervisorExecutionIntake() -> SupervisorPendingExecutionIntake? {
        guard let intake = pendingSupervisorExecutionIntake else { return nil }
        let now = Date().timeIntervalSince1970
        if now - intake.updatedAt > supervisorEllipsisContextCarryWindowSec {
            clearPendingSupervisorExecutionIntake()
            return nil
        }
        return intake
    }

    private func clearPendingSupervisorExecutionIntake() {
        pendingSupervisorExecutionIntake = nil
    }

    private func restorePendingSupervisorExecutionIntake(
        _ intake: SupervisorPendingExecutionIntake
    ) {
        var restored = intake
        restored.updatedAt = Date().timeIntervalSince1970
        pendingSupervisorExecutionIntake = restored
    }

    private func installPendingSupervisorProjectCreationGoalRequest(
        projectId: String? = nil,
        projectName: String? = nil
    ) {
        let now = Date().timeIntervalSince1970
        let trimmedProjectID = projectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let normalizedProjectID = trimmedProjectID.isEmpty ? nil : trimmedProjectID
        let trimmedProjectName = projectName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let normalizedProjectName = trimmedProjectName.isEmpty
            ? nil
            : normalizedSupervisorProjectDisplayName(trimmedProjectName)
        if var existing = pendingSupervisorProjectCreationGoalRequest {
            if let normalizedProjectID {
                existing.projectId = normalizedProjectID
            }
            if let normalizedProjectName {
                existing.projectName = normalizedProjectName
            }
            existing.updatedAt = now
            pendingSupervisorProjectCreationGoalRequest = existing
            return
        }
        pendingSupervisorProjectCreationGoalRequest = SupervisorPendingProjectCreationGoalRequest(
            projectId: normalizedProjectID,
            projectName: normalizedProjectName,
            createdAt: now,
            updatedAt: now
        )
    }

    private func activePendingSupervisorProjectCreationGoalRequest() -> SupervisorPendingProjectCreationGoalRequest? {
        guard let request = pendingSupervisorProjectCreationGoalRequest else { return nil }
        let now = Date().timeIntervalSince1970
        if now - request.updatedAt > supervisorEllipsisContextCarryWindowSec {
            clearPendingSupervisorProjectCreationGoalRequest()
            return nil
        }
        return request
    }

    private func clearPendingSupervisorProjectCreationGoalRequest() {
        pendingSupervisorProjectCreationGoalRequest = nil
    }

    private func pendingSupervisorExecutionIntake(
        from proposal: SupervisorRecoveredProjectCreationProposal
    ) -> SupervisorPendingExecutionIntake {
        let now = Date().timeIntervalSince1970
        return SupervisorPendingExecutionIntake(
            originalRequest: proposal.sourceMessage.trimmingCharacters(in: .whitespacesAndNewlines),
            goalSummary: proposal.goalSummary,
            track: proposal.track,
            suggestedProjectName: proposal.projectName,
            createdAt: now,
            updatedAt: now
        )
    }

    private func resolveSupervisorProjectCreationReadiness(
        currentUserMessage: String?,
        skipTrailingUserMessages: Bool = false
    ) -> SupervisorProjectCreationReadiness {
        if pendingSupervisorExecutionBootstrapTask != nil {
            return .bootstrapInProgress
        }
        if let intake = activePendingSupervisorExecutionIntake() {
            return .pendingIntake(intake)
        }
        if let proposal = recentSupervisorProjectCreationProposal(
            currentUserMessage: currentUserMessage,
            skipTrailingUserMessages: skipTrailingUserMessages
        ) {
            return .recoveredProposal(proposal)
        }
        if activePendingSupervisorProjectCreationGoalRequest() != nil {
            return .awaitingGoal
        }
        return .unavailable
    }

    private func executionIntakeGoalSummary(from userMessage: String) -> String {
        let trimmed = userMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "新交付任务" }
        let clauses = trimmed
            .split(whereSeparator: { "，,。！？?；;\n".contains($0) })
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        if let goalClause = clauses.first(where: { clause in
            isSubstantiveExecutionGoalClause(normalizedSupervisorIntentText(clause))
        }) {
            return goalClause
        }
        return clauses.first ?? trimmed
    }

    private func isSubstantiveExecutionGoalClause(_ normalized: String) -> Bool {
        containsExecutionArtifactHint(normalized)
            || containsDefaultMVPDeliverySignal(normalized)
            || containsMinimumRunnableDeliverySignal(normalized)
            || (containsExecutionActionHint(normalized) && containsExecutionWorkstreamHint(normalized))
    }

    private func containsExecutionArtifactHint(_ normalized: String) -> Bool {
        containsAny(
            normalized,
            [
                "游戏", "贪食蛇", "贪吃蛇", "snake", "game",
                "app", "应用", "网站", "网页", "web", "工具", "tool",
                "脚本", "script", "demo", "原型", "feature", "功能",
                "插件", "扩展", "extension", "bot", "agent", "服务", "service"
            ]
        )
    }

    private func containsDefaultMVPDeliverySignal(_ normalized: String) -> Bool {
        containsAny(
            normalized,
            [
                "默认mvp",
                "默认 mvp",
                "默认的mvp",
                "默认的 mvp",
                "default mvp",
                "defaultmvp"
            ]
        )
    }

    private func containsMinimumRunnableDeliverySignal(_ normalized: String) -> Bool {
        containsAny(
            normalized,
            [
                "最小可运行版本",
                "最小可运行"
            ]
        )
    }

    private func containsExecutionActionHint(_ normalized: String) -> Bool {
        containsAny(
            normalized,
            [
                "做", "推进", "修", "修复", "收口", "接入", "补齐", "补全", "打通",
                "联调", "治理", "落地", "重构", "改造", "整理", "梳理", "优化",
                "升级", "实现", "搭建", "排查", "完成", "接上", "对齐"
            ]
        )
    }

    private func containsExecutionWorkstreamHint(_ normalized: String) -> Bool {
        containsAny(
            normalized,
            [
                "heartbeat", "review", "runtime", "repo", "browser", "device",
                "connector", "extension", "skill", "tool", "workflow", "memory",
                "grant", "policy", "doctor", "ui", "route", "lane", "voice",
                "hub", "scheduler", "governance", "supervisor", "coder",
                "protocol", "api",
                "心跳", "复盘", "路由", "记忆", "授权", "审计", "工单",
                "协议", "文档", "测试", "构建", "前端", "后端", "界面", "调度",
                "运行时", "浏览器", "设备", "技能", "模型", "语音"
            ]
        )
    }

    private func inlineExecutionIntakeFromExplicitProjectCreationRequest(
        _ userMessage: String
    ) -> SupervisorPendingExecutionIntake? {
        let goalSummary = normalizedExplicitProjectCreationGoalSummary(from: userMessage)
        guard isSubstantiveExecutionGoalClause(normalizedSupervisorIntentText(goalSummary)) else {
            return nil
        }

        let track = inferredExecutionTrack(for: userMessage)
        let intake = installPendingSupervisorExecutionIntake(
            originalRequest: userMessage,
            goalSummary: goalSummary,
            track: track,
            suggestedProjectName: inferredExecutionProjectName(from: goalSummary, track: track)
        )
        return pendingExecutionIntakeApplyingExplicitProjectCreationSignals(
            intake,
            userMessage: userMessage
        )
    }

    private func normalizedExplicitProjectCreationGoalSummary(from userMessage: String) -> String {
        let goalSummary = executionIntakeGoalSummary(from: userMessage)
        guard let projectName = explicitProjectCreationRequestedProjectName(from: userMessage) else {
            return goalSummary
        }

        let normalizedGoalSummary = normalizedSupervisorIntentText(goalSummary)
        let normalizedProjectName = normalizedSupervisorIntentText(projectName)
        let normalizedUserMessage = normalizedSupervisorIntentText(userMessage)
        guard containsDefaultMVPDeliverySignal(normalizedUserMessage)
            || containsDefaultMVPDeliverySignal(normalizedGoalSummary)
        else {
            return goalSummary
        }
        guard !normalizedGoalSummary.contains(normalizedProjectName) else {
            return goalSummary
        }
        return "交付《\(projectName)》的默认 MVP"
    }

    private func explicitProjectCreationRequestedProjectName(from userMessage: String) -> String? {
        if let overrideName = explicitProjectCreationNameOverride(from: userMessage) {
            return overrideName
        }

        let patterns = [
            #"(?:创建|新建|建立|创立|开|起)(?:一个|个)?(?:独立)?(?:project|项目)\s*[：:]?\s*([^\n，,。.!！？?]+)"#,
            #"(?:创建|新建|建立|创立|开|起)(?:一个|个)?([^\n，,。.!！？?]{2,40}?)项目(?:[，,。.!！？?\n]|$)"#
        ]
        for pattern in patterns {
            guard let captured = firstRegexCapture(in: userMessage, pattern: pattern) else {
                continue
            }
            let candidate = sanitizeProjectReference(captured)
            guard isMeaningfulExecutionProjectNameCandidate(candidate) else {
                continue
            }
            return capped(candidate, maxChars: 40)
        }
        return nil
    }

    private func explicitProjectCreationNameOverride(from userMessage: String) -> String? {
        let patterns = [
            #"(?:名字(?:先)?(?:就)?叫|项目名(?:先用)?|项目名叫|项目就叫|名叫)\s*[：:]?\s*([^\n，,。.!！？?]+)"#,
            #"(?:项目)?(?:名字)?(?:先)?(?:就)?叫(?:做)?\s*[：:]?\s*([^\n，,。.!！？?]+)"#
        ]
        for pattern in patterns {
            guard let captured = firstRegexCapture(in: userMessage, pattern: pattern) else {
                continue
            }
            let candidate = sanitizeProjectReference(captured)
            guard isMeaningfulExecutionProjectNameCandidate(candidate) else {
                continue
            }
            return capped(candidate, maxChars: 40)
        }
        return nil
    }

    private func pendingExecutionIntakeApplyingExplicitProjectCreationSignals(
        _ intake: SupervisorPendingExecutionIntake,
        userMessage: String
    ) -> SupervisorPendingExecutionIntake {
        var adjusted = intake
        var changed = false

        if let projectName = explicitProjectCreationRequestedProjectName(from: userMessage),
           projectName != adjusted.suggestedProjectName {
            adjusted.suggestedProjectName = projectName
            changed = true
        }

        let goalSummary = normalizedExplicitProjectCreationGoalSummary(from: userMessage)
        if isSubstantiveExecutionGoalClause(normalizedSupervisorIntentText(goalSummary)),
           goalSummary != adjusted.goalSummary {
            adjusted.goalSummary = goalSummary
            changed = true
        }

        if changed {
            adjusted.updatedAt = Date().timeIntervalSince1970
        }
        return adjusted
    }

    private func inferredExecutionProjectName(from goalSummary: String, track: String) -> String {
        let trimmedGoal = goalSummary.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedGoal = normalizedSupervisorIntentText(trimmedGoal)
        if containsAny(normalizedGoal, ["贪食蛇", "贪吃蛇", "snake"]) {
            return "贪食蛇游戏"
        }

        let cuePhrases = [
            "我要做个", "我要做一个", "我想做个", "我想做一个",
            "帮我做个", "帮我做一个", "给我做个", "给我做一个",
            "请做个", "请做一个", "做个", "做一个",
            "我想写个", "我想写一个", "写个", "写一个",
            "我想开发一个", "开发一个", "实现一个",
            "build me", "make me", "create a", "create an", "implement a", "implement an"
        ]
        for phrase in cuePhrases {
            guard let range = trimmedGoal.range(of: phrase, options: [.caseInsensitive]) else { continue }
            let suffix = String(trimmedGoal[range.upperBound...])
            let candidate = normalizedExecutionProjectNameCandidate(suffix)
            if !candidate.isEmpty {
                return capped(candidate, maxChars: 40)
            }
        }

        let directCandidate = normalizedExecutionProjectNameCandidate(trimmedGoal)
        if isMeaningfulExecutionProjectNameCandidate(directCandidate) {
            return capped(directCandidate, maxChars: 40)
        }

        switch track {
        case "网页版":
            return "新网页项目"
        case "iOS 版":
            return "新 iOS 项目"
        case "macOS 桌面版":
            return "新 macOS 项目"
        case "终端版":
            return "新终端项目"
        default:
            return "新交付项目"
        }
    }

    private func normalizedExecutionProjectNameCandidate(_ raw: String) -> String {
        var candidate = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimSet = CharacterSet(charactersIn: "：:，,。.!！？?\"'“”‘’()（）[]【】")
        candidate = candidate.trimmingCharacters(in: trimSet)

        let fillerPrefixes = ["一个", "1个", "个", "款", "套", "a ", "an "]
        for prefix in fillerPrefixes {
            if candidate.lowercased().hasPrefix(prefix.lowercased()) {
                candidate = String(candidate.dropFirst(prefix.count)).trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }

        let fillerSuffixes = [
            "吗", "么", "吧",
            "你能做个详细工单发给project ai去推进吗",
            "你能做个详细工单发给 project ai 去推进吗"
        ]
        for suffix in fillerSuffixes {
            if candidate.lowercased().hasSuffix(suffix.lowercased()) {
                candidate = String(candidate.dropLast(suffix.count)).trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }
        return candidate
    }

    private func isMeaningfulExecutionProjectNameCandidate(_ candidate: String) -> Bool {
        let trimmed = candidate.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 2 else { return false }
        let normalized = normalizedSupervisorIntentText(trimmed)
        let genericOnly = [
            "这个",
            "那个",
            "这个项目",
            "那个项目",
            "项目",
            "一个项目",
            "新项目",
            "前面说的",
            "刚才说的"
        ]
        return !genericOnly.contains(normalized)
    }

    private func resolvedPendingProjectCreationGoalSummary(
        _ userMessage: String,
        request: SupervisorPendingProjectCreationGoalRequest
    ) -> String? {
        let normalizedUserMessage = normalizedSupervisorIntentText(userMessage)
        if let projectName = request.projectName,
           request.projectId != nil,
           containsDefaultMVPDeliverySignal(normalizedUserMessage) {
            return "交付《\(projectName)》的默认 MVP"
        }

        let goalSummary = executionIntakeGoalSummary(from: userMessage)
        if isSubstantiveExecutionGoalClause(normalizedSupervisorIntentText(goalSummary)) {
            return goalSummary
        }

        guard let fallback = normalizedPendingProjectCreationGoalClarification(userMessage) else {
            return nil
        }
        guard let projectName = request.projectName,
              request.projectId != nil
        else {
            return fallback
        }

        let normalizedFallback = normalizedSupervisorIntentText(fallback)
        let normalizedProjectName = normalizedSupervisorIntentText(projectName)
        if normalizedFallback == normalizedProjectName || normalizedFallback.contains(normalizedProjectName) {
            return "交付《\(projectName)》的默认 MVP"
        }
        return fallback
    }

    private func directSupervisorPendingProjectCreationGoalFollowUpIfApplicable(
        _ userMessage: String,
        normalized: String
    ) -> String? {
        guard let request = activePendingSupervisorProjectCreationGoalRequest() else { return nil }
        guard !isExplicitProjectCreationRequest(normalized) else { return nil }
        guard pendingSupervisorExecutionBootstrapTask == nil else {
            return "上一轮默认建项目流程还在处理中。创建完成后，我会继续把工单和初始计划补进去。"
        }
        guard let goalSummary = resolvedPendingProjectCreationGoalSummary(
            userMessage,
            request: request
        ) else {
            return nil
        }

        let track = inferredExecutionTrack(for: goalSummary)
        let intake = installPendingSupervisorExecutionIntake(
            originalRequest: userMessage,
            goalSummary: goalSummary,
            track: track,
            suggestedProjectName: request.projectName ?? inferredExecutionProjectName(from: goalSummary, track: track)
        )
        clearPendingSupervisorProjectCreationGoalRequest()
        if let projectId = request.projectId?.trimmingCharacters(in: .whitespacesAndNewlines),
           !projectId.isEmpty,
           let project = appModel?.registry.project(for: projectId) {
            return beginPendingSupervisorExecutionBootstrapForExistingProject(
                project: project,
                intake: intake,
                triggerUserMessage: userMessage
            )
        }
        return beginPendingSupervisorExecutionIntakeProjectCreation(
            intake,
            triggerUserMessage: userMessage
        )
    }

    private func normalizedPendingProjectCreationGoalClarification(_ raw: String) -> String? {
        var candidate = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !candidate.isEmpty else { return nil }

        let leadingPhrases = [
            "就是前面说的",
            "就是刚才说的",
            "就是之前说的",
            "前面说的",
            "刚才说的",
            "之前说的",
            "前面那个",
            "刚才那个",
            "之前那个",
            "项目名先用",
            "项目名叫",
            "项目就叫",
            "就做",
            "就按",
            "就是",
            "叫做",
            "叫",
            "做"
        ]
        var strippedLeading = true
        while strippedLeading {
            strippedLeading = false
            for phrase in leadingPhrases {
                if candidate.lowercased().hasPrefix(phrase.lowercased()) {
                    candidate = String(candidate.dropFirst(phrase.count)).trimmingCharacters(in: .whitespacesAndNewlines)
                    strippedLeading = true
                }
            }
        }

        let trailingPhrases = [
            "吧",
            "就行",
            "就好",
            "这个项目",
            "这个"
        ]
        var strippedTrailing = true
        while strippedTrailing {
            strippedTrailing = false
            for phrase in trailingPhrases {
                if candidate.lowercased().hasSuffix(phrase.lowercased()) {
                    candidate = String(candidate.dropLast(phrase.count)).trimmingCharacters(in: .whitespacesAndNewlines)
                    strippedTrailing = true
                }
            }
        }

        candidate = normalizedExecutionProjectNameCandidate(candidate)
        guard isMeaningfulExecutionProjectNameCandidate(candidate) else { return nil }
        return candidate
    }

    private func isPendingExecutionIntakeProjectCreationConfirmation(_ normalized: String) -> Bool {
        let trimmed = normalized.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        let compact = trimmed
            .replacingOccurrences(of: " ", with: "")
            .trimmingCharacters(in: CharacterSet.punctuationCharacters.union(.symbols))
        let directTokens = [
            "就按这个建",
            "按这个建",
            "那就按这个建",
            "就按这个来建",
            "就按这个来",
            "那就按这个来",
            "就这样建",
            "就这么建",
            "按这个起项目",
            "按这个起盘",
            "直接建吧",
            "那就建吧",
            "就建吧",
            "开始建吧",
            "goahead",
            "buildit"
        ]
        if directTokens.contains(where: { compact.contains($0) }) {
            return true
        }

        let hasBuild = containsAny(compact, ["建", "创建", "起项目", "起盘", "build"])
        let hasReference = containsAny(compact, ["这个", "这样", "上述", "上面", "方案", "项目", "this"])
        let hasAffirm = containsAny(compact, ["就", "那就", "可以", "好", "行", "ok", "okay", "yes"])
        return hasBuild && hasReference && hasAffirm
    }

    private func recentSupervisorProjectCreationProposal(
        currentUserMessage: String? = nil,
        skipTrailingUserMessages: Bool = false,
        maxMessages: Int = 4
    ) -> SupervisorRecoveredProjectCreationProposal? {
        let currentNormalized = normalizedLookupKey(currentUserMessage ?? "")
        let now = Date().timeIntervalSince1970
        var skippedCurrentUserMessage = currentNormalized.isEmpty
        var encounteredAssistantOrSystem = false
        var inspected = 0

        for message in frontstageConversationMessages.reversed() {
            let messageNormalized = normalizedLookupKey(message.content)
            if messageNormalized.isEmpty {
                continue
            }
            if message.role == .user {
                if !skippedCurrentUserMessage,
                   messageNormalized == currentNormalized {
                    skippedCurrentUserMessage = true
                    continue
                }
                if skipTrailingUserMessages && !encounteredAssistantOrSystem {
                    continue
                }
                break
            }
            guard message.role == .assistant || message.role == .system else {
                continue
            }
            encounteredAssistantOrSystem = true
            if now - message.timestamp > supervisorEllipsisContextCarryWindowSec {
                break
            }
            inspected += 1
            if let proposal = parseSupervisorProjectCreationProposal(message.content) {
                return proposal
            }
            if inspected >= maxMessages {
                break
            }
        }
        return nil
    }

    private func parseSupervisorProjectCreationProposal(
        _ text: String
    ) -> SupervisorRecoveredProjectCreationProposal? {
        let normalized = normalizedLookupKey(text)
        guard normalizedContainsAny(
            normalized,
            [
                "系统里还没有这个项目",
                "先建项目",
                "建项目",
                "新建独立项目",
                "创建独立项目",
                "补 job",
                "job + initial plan",
                "执行骨架",
                "就按这个建",
                "接着往下走",
                "按这个方向继续",
                "直接重命名"
            ]
        ) else {
            return nil
        }

        let projectNamePatterns = [
            #"(?:项目名(?:先用)?|项目就叫|项目名叫|名字(?:就)?叫|名叫)\s*[：:]?\s*(?:\*\*)?([^\n*：:]+?)(?:\*\*)?(?:[，,。.!！？?\n]|$)"#,
            #"(?:你前面要做的是|前面要做的是|要做的是|这次要做的是|当前要做的是)\s*(?:\*\*)?([^\n*：:]+?)(?:\*\*)?(?:[，,。.!！？?\n]|$)"#
        ]
        let projectName = projectNamePatterns
            .compactMap { firstRegexCapture(in: text, pattern: $0) }
            .map(sanitizedSupervisorProposalField)
            .first(where: isMeaningfulExecutionProjectNameCandidate)
        guard let projectName else { return nil }

        let track = firstRegexCapture(
            in: text,
            pattern: #"(?:形态|track)\s*[：:]\s*(?:\*\*)?([^\n*]+?)(?:\*\*)?(?:\n|$)"#
        )
        .map(sanitizedSupervisorProposalField)
        .flatMap { $0.isEmpty ? nil : $0 }
            ?? inferredExecutionTrack(for: text)

        let goalSummary = firstRegexCapture(
            in: text,
            pattern: #"(?:你前面要做的是|前面要做的是|要做的是|这次要做的是|当前要做的是)\s*(?:\*\*)?([^\n*：:]+?)(?:\*\*)?(?:[，,。.!！？?\n]|$)"#
        )
        .map(sanitizedSupervisorProposalField)
        .flatMap { $0.isEmpty ? nil : $0 }
            ?? projectName

        return SupervisorRecoveredProjectCreationProposal(
            projectName: projectName,
            goalSummary: goalSummary,
            track: track,
            sourceMessage: text.trimmingCharacters(in: .whitespacesAndNewlines)
        )
    }

    private func sanitizedSupervisorProposalField(_ raw: String) -> String {
        raw
            .replacingOccurrences(of: "**", with: "")
            .trimmingCharacters(in: CharacterSet(charactersIn: "：:，,。.!！？?\"'“”‘’()（）[]【】 \n\t"))
    }

    private func beginPendingSupervisorExecutionIntakeProjectCreation(
        _ intake: SupervisorPendingExecutionIntake,
        triggerUserMessage: String
    ) -> String {
        clearPendingSupervisorExecutionIntake()
        let projectName = intake.suggestedProjectName
        let actionId = appendActionLedger(
            action: "create_project",
            targetRef: projectName,
            projectId: nil,
            projectName: nil,
            role: nil,
            modelId: nil,
            status: "pending",
            reasonCode: "pending_execution_intake",
            detail: "create project from pending execution intake",
            verifiedAt: nil,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )
        pendingSupervisorExecutionBootstrapTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.pendingSupervisorExecutionBootstrapTask = nil }
            if let project = await self.createProject(projectName) {
                self.updateActionLedger(
                    id: actionId,
                    status: "ok",
                    reasonCode: "ok",
                    detail: "created project \(project.displayName) from pending execution intake",
                    verifiedAt: Date().timeIntervalSince1970
                )
                let bootstrapReply = self.bootstrapCreatedProjectFromPendingExecutionIntake(
                    project: project,
                    intake: intake,
                    triggerUserMessage: triggerUserMessage
                )
                self.addSystemMessage(bootstrapReply)
            } else {
                self.restorePendingSupervisorExecutionIntake(intake)
                let failureMessage = "❌ 创建项目失败。上一轮默认方案我先保留着，你可以再说一次“按默认方案建项目”。"
                self.addSystemMessage(failureMessage)
                self.updateActionLedger(
                    id: actionId,
                    status: "failed",
                    reasonCode: "user_cancelled_or_create_failed",
                    detail: "create project cancelled or failed for pending execution intake",
                    verifiedAt: nil
                )
            }
        }

        return """
我会按上一轮默认方案创建《\(projectName)》。
目标先按“\(capped(intake.goalSummary, maxChars: 48))”来锁定；创建完成后，我会继续写入第一版详细工单，让 Project AI 可以直接接着推进。
"""
    }

    private func beginPendingSupervisorProjectCreationGoalCollection(
        projectName: String
    ) -> String {
        clearPendingSupervisorExecutionIntake()
        clearPendingSupervisorProjectCreationGoalRequest()
        let actionId = appendActionLedger(
            action: "create_project",
            targetRef: projectName,
            projectId: nil,
            projectName: nil,
            role: nil,
            modelId: nil,
            status: "pending",
            reasonCode: "project_goal_follow_up_required",
            detail: "create project before collecting execution goal",
            verifiedAt: nil,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )
        pendingSupervisorExecutionBootstrapTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.pendingSupervisorExecutionBootstrapTask = nil }
            if let project = await self.createProject(projectName) {
                self.installPendingSupervisorProjectCreationGoalRequest(
                    projectId: project.projectId,
                    projectName: project.displayName
                )
                self.updateActionLedger(
                    id: actionId,
                    status: "ok",
                    reasonCode: "ok",
                    detail: "created project \(project.displayName) and waiting for execution goal",
                    verifiedAt: Date().timeIntervalSince1970
                )
                self.addSystemMessage(
                    """
✅ 已先创建项目：《\(project.displayName)》

现在还差一句交付目标。你直接说“我要用默认的MVP”，或者说“第一版先做成最小可运行版本”，我就继续补第一版工单和 initial plan。
"""
                )
            } else {
                let failureMessage = "❌ 创建项目失败。你可以再说一次项目名，我重新帮你起。"
                self.addSystemMessage(failureMessage)
                self.updateActionLedger(
                    id: actionId,
                    status: "failed",
                    reasonCode: "user_cancelled_or_create_failed",
                    detail: "create project cancelled or failed before collecting execution goal",
                    verifiedAt: nil
                )
            }
        }

        return """
我先把《\(projectName)》建起来。
创建完成后，我再补问一个最关键的交付目标，然后继续把第一版工单挂进去。
"""
    }

    private func beginPendingSupervisorExecutionBootstrapForExistingProject(
        project: AXProjectEntry,
        intake: SupervisorPendingExecutionIntake,
        triggerUserMessage: String
    ) -> String {
        clearPendingSupervisorExecutionIntake()
        let actionId = appendActionLedger(
            action: "bootstrap_project",
            targetRef: project.displayName,
            projectId: project.projectId,
            projectName: project.displayName,
            role: nil,
            modelId: nil,
            status: "pending",
            reasonCode: "project_goal_follow_up_received",
            detail: "bootstrap existing project after goal clarification",
            verifiedAt: nil,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )
        pendingSupervisorExecutionBootstrapTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.pendingSupervisorExecutionBootstrapTask = nil }
            let bootstrapReply = self.bootstrapCreatedProjectFromPendingExecutionIntake(
                project: project,
                intake: intake,
                triggerUserMessage: triggerUserMessage
            )
            let ok = !bootstrapReply.contains("❌")
            self.updateActionLedger(
                id: actionId,
                status: ok ? "ok" : "failed",
                reasonCode: ok ? "ok" : "bootstrap_failed",
                detail: "bootstrapped existing project \(project.displayName) after goal clarification",
                verifiedAt: ok ? Date().timeIntervalSince1970 : nil
            )
            self.addSystemMessage(bootstrapReply)
        }

        return """
《\(project.displayName)》已经建好了。
目标先按“\(capped(intake.goalSummary, maxChars: 48))”来锁定；我现在继续写入第一版详细工单，让 Project AI 可以直接接着推进。
"""
    }

    private func normalizedSupervisorProjectDisplayName(_ raw: String) -> String {
        let sanitized = sanitizeProjectReference(raw)
        let compact = sanitized
            .split(whereSeparator: \.isWhitespace)
            .joined(separator: " ")
        return compact.isEmpty ? "新交付项目" : capped(compact, maxChars: 80)
    }

    private func defaultSupervisorProjectRootURL(for projectName: String) -> URL {
        let fm = FileManager.default
        let projectsBase = AXProjectRegistryStore.baseDir()
            .appendingPathComponent("Projects", isDirectory: true)
        try? fm.createDirectory(at: projectsBase, withIntermediateDirectories: true)

        let baseName = normalizedSupervisorProjectDirectoryName(projectName)
        var candidate = projectsBase.appendingPathComponent(baseName, isDirectory: true)
        var suffix = 2
        while fm.fileExists(atPath: candidate.path) {
            candidate = projectsBase.appendingPathComponent("\(baseName)-\(suffix)", isDirectory: true)
            suffix += 1
        }
        return candidate
    }

    private func normalizedSupervisorProjectDirectoryName(_ raw: String) -> String {
        let preferred = normalizedSupervisorProjectDisplayName(raw)
        let invalidCharacters = CharacterSet(charactersIn: "/:\\\n\r\t")
        let parts = preferred.components(separatedBy: invalidCharacters)
        let joined = parts.joined(separator: " ")
        let compact = joined
            .split(whereSeparator: \.isWhitespace)
            .joined(separator: " ")
            .trimmingCharacters(in: CharacterSet(charactersIn: ". "))
        return compact.isEmpty ? "新交付项目" : capped(compact, maxChars: 80)
    }

    private func bootstrapCreatedProjectFromPendingExecutionIntake(
        project: AXProjectEntry,
        intake: SupervisorPendingExecutionIntake,
        triggerUserMessage: String
    ) -> String {
        let ctx = AXProjectContext(root: URL(fileURLWithPath: project.rootPath, isDirectory: true))
        let spec = buildExecutionProjectBootstrapSpec(
            project: project,
            intake: intake
        )
        var warnings: [String] = []
        do {
            _ = try AXProjectStore.loadOrCreateConfig(for: ctx)
            var memory = try AXProjectStore.loadOrCreateMemory(for: ctx)
            memory.goal = spec.goal
            memory.requirements = orderedUniqueReviewScalars(spec.requirements)
            memory.currentState = [spec.currentState]
            memory.decisions = orderedUniqueReviewScalars(spec.decisions)
            memory.nextSteps = [spec.nextStep]
            memory.openQuestions = []
            memory.risks = []
            memory.recommendations = []
            memory.updatedAt = Date().timeIntervalSince1970
            try AXProjectStore.saveMemory(memory, for: ctx)

            let specCapsule = SupervisorProjectSpecCapsuleBuilder.build(
                projectId: project.projectId,
                goal: spec.goal,
                mvpDefinition: spec.doneDefinition,
                nonGoals: spec.nonGoals,
                approvedTechStack: spec.approvedTechStack,
                milestoneMap: spec.milestones,
                sourceRefs: ["supervisor_execution_intake_bootstrap"]
            )
            _ = try SupervisorProjectSpecCapsuleStore.upsert(specCapsule, for: ctx)
        } catch {
            warnings.append("项目 anchor 初始化失败：\(error.localizedDescription)")
        }

        let statusUpdate = AXProjectRegistryStore.updateStatusDigest(
            forRoot: ctx.root,
            digest: spec.statusDigest,
            lastSummaryAt: Date().timeIntervalSince1970,
            currentState: spec.currentState,
            nextStep: spec.nextStep,
            blocker: nil
        )
        if let appModel {
            appModel.registry = statusUpdate.registry
            appModel.selectedProjectId = project.projectId
        }

        let createPayload = SupervisorCreateJobPayload(
            projectRef: project.projectId,
            goal: spec.jobGoal,
            priority: SupervisorJobPriority.high.rawValue,
            source: SupervisorJobSource.user.rawValue,
            currentOwner: "coder"
        )
        let createResult = createSupervisorJob(
            from: createPayload,
            userMessage: triggerUserMessage,
            triggerSource: .userTurn,
            emitSystemMessage: false
        )
        _ = appendActionLedger(
            action: "create_job",
            targetRef: project.displayName,
            projectId: createResult.projectId,
            projectName: createResult.projectName,
            role: nil,
            modelId: nil,
            status: createResult.ok ? "ok" : "failed",
            reasonCode: createResult.reasonCode,
            detail: createResult.message,
            verifiedAt: createResult.ok ? Date().timeIntervalSince1970 : nil,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )
        guard createResult.ok, let jobId = createResult.jobId else {
            return renderExecutionIntakeBootstrapFailure(
                projectName: project.displayName,
                stage: "创建任务",
                warnings: warnings,
                details: [createResult.message]
            )
        }

        let planPayload = SupervisorUpsertPlanPayload(
            projectRef: project.projectId,
            jobId: jobId,
            planId: spec.planId,
            currentOwner: "coder",
            steps: spec.steps
        )
        let planResult = upsertSupervisorPlan(
            from: planPayload,
            userMessage: triggerUserMessage,
            triggerSource: .userTurn,
            emitSystemMessage: false
        )
        _ = appendActionLedger(
            action: "upsert_plan",
            targetRef: project.displayName,
            projectId: planResult.projectId,
            projectName: planResult.projectName,
            role: nil,
            modelId: nil,
            status: planResult.ok ? "ok" : "failed",
            reasonCode: planResult.reasonCode,
            detail: planResult.message,
            verifiedAt: planResult.ok ? Date().timeIntervalSince1970 : nil,
            triggerSource: SupervisorCommandTriggerSource.userTurn.rawValue
        )
        guard planResult.ok else {
            return renderExecutionIntakeBootstrapFailure(
                projectName: project.displayName,
                stage: "写入计划",
                warnings: warnings,
                details: [createResult.message, planResult.message]
            )
        }

        return renderExecutionIntakeBootstrapSuccess(
            project: project,
            intake: intake,
            spec: spec,
            jobId: jobId,
            warnings: warnings
        )
    }

    private func renderExecutionIntakeBootstrapSuccess(
        project: AXProjectEntry,
        intake: SupervisorPendingExecutionIntake,
        spec: SupervisorExecutionProjectBootstrapSpec,
        jobId: String,
        warnings: [String]
    ) -> String {
        var lines = [
            "✅ 已按上一轮默认方案创建《\(project.displayName)》，并把第一版工单挂给 Project AI 了。",
            "",
            "job_id: \(jobId)",
            "plan_id: \(spec.planId)",
            "目标：\(spec.goal)",
            "完成标准：\(spec.doneDefinition)",
            "下一步：\(spec.nextStep)",
            "计划步骤：",
            spec.steps.enumerated().map { index, step in
                let owner = (step.currentOwner ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
                let status = SupervisorPlanStepStatus.parse(step.status).rawValue
                let ownerSuffix = owner.isEmpty ? "" : " / \(owner)"
                return "\(index + 1). \(step.title)（\(status)\(ownerSuffix)）"
            }.joined(separator: "\n"),
            "",
            "你现在直接说“继续”或“自动继续”，Supervisor 就会沿着这份工单往下推。"
        ]
        if !warnings.isEmpty {
            lines.append("")
            lines.append("附注：\(warnings.joined(separator: "；"))")
        }
        if !intake.originalRequest.isEmpty {
            lines.append("来源请求：\(capped(intake.originalRequest, maxChars: 72))")
        }
        return lines.joined(separator: "\n")
    }

    private func renderExecutionIntakeBootstrapFailure(
        projectName: String,
        stage: String,
        warnings: [String],
        details: [String]
    ) -> String {
        var lines = [
            "⚠️ 《\(projectName)》已经创建出来了，但在\(stage)这一步没有完全落稳。"
        ]
        if !warnings.isEmpty {
            lines.append("附注：\(warnings.joined(separator: "；"))")
        }
        lines.append(contentsOf: details.filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty })
        return lines.joined(separator: "\n")
    }

    private func sanitizeSupervisorRemoteResponse(
        _ response: String,
        userMessage: String,
        projects: [AXProjectEntry]
    ) -> String {
        let trimmed = response.trimmingCharacters(in: CharacterSet.whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return response }

        let lowered = trimmed.lowercased()
        let dangerSignals = [
            "<private",
            "-----begin private key-----",
            "authorization:",
            "set-cookie:",
            "bearer sk-",
            "ghp_",
            "gho_",
            "ghu_",
            "sk-ant-"
        ]
        if dangerSignals.contains(where: { lowered.contains($0) }) {
            return """
            远端回复包含疑似敏感或不可信内容，Supervisor 已改用本地安全兜底结果。

            \(generateFallbackResponse(userMessage))
            """
        }

        let hallucinatedGlobalClaims = [
            "我已经检查了你所有项目的完整记忆文件",
            "我已经读取了所有项目的原始邮件",
            "我已经拿到了所有项目的密钥"
        ]
        if hallucinatedGlobalClaims.contains(where: { lowered.contains($0.lowercased()) }) && !projects.isEmpty {
            return """
            远端回复超出了当前 Supervisor memory 的可见范围，已切换到本地摘要兜底结果。

            \(generateFallbackResponse(userMessage))
            """
        }

        let normalizedResponse = normalizedSupervisorIntentText(response)
        guard !normalizedResponse.isEmpty else { return response }
        if responseAppearsToFabricateRuntimeConstraints(normalizedResponse, userMessage: userMessage)
            || responseAppearsToIgnoreUserIntent(normalizedResponse)
            || responseAppearsToLeakTranscriptScaffolding(trimmed)
            || responseAppearsToOverGovernSimpleGreeting(normalizedResponse, userMessage: userMessage) {
            return generateFallbackResponse(userMessage)
        }
        return response
    }

    private func responseAppearsToFabricateRuntimeConstraints(
        _ normalizedResponse: String,
        userMessage: String
    ) -> Bool {
        let normalizedUser = normalizedSupervisorIntentText(userMessage)
        let userExplicitlyAskedForJSON = containsAny(normalizedUser, ["json", "结构化", "machine readable"])
        if userExplicitlyAskedForJSON {
            return false
        }

        if containsAny(
            normalizedResponse,
            [
                "不能直接落地文件",
                "不能创建文件",
                "不能写文件",
                "纯对话环境",
                "没有直接挂到",
                "没法真的打开本地",
                "无法真的打开本地",
                "没法打开本地文件",
                "没有直接访问本地",
                "当前我还没执行工具调用",
                "当前我还未执行工具调用",
                "cannot create files",
                "cannot write files",
                "can't create files"
            ]
        ) {
            return true
        }

        if responseAppearsToFabricateDelegatedExecutionLimits(normalizedResponse) {
            return true
        }

        let claimsJSONOnly = containsAny(
            normalizedResponse,
            [
                "纯 json",
                "纯json",
                "json 结果",
                "json结果",
                "json-only",
                "json only"
            ]
        ) && containsAny(normalizedResponse, ["只能", "只可", "要求", "must", "only"])
        if claimsJSONOnly {
            return true
        }

        let demandsTriggerPhrase = containsAny(normalizedResponse, ["开始生成", "start generating"])
            && containsAny(normalizedResponse, ["回复我一句", "reply with", "回复一句"])
        return demandsTriggerPhrase
    }

    private func responseAppearsToFabricateDelegatedExecutionLimits(_ normalizedResponse: String) -> Bool {
        let blanketNegative = containsAny(
            normalizedResponse,
            [
                "没办法",
                "无法",
                "不能",
                "做不到",
                "can't",
                "cannot",
                "unable"
            ]
        )
        let mentionsProjectAI = containsAny(
            normalizedResponse,
            [
                "project ai",
                "project-ai",
                "项目 ai",
                "项目ai",
                "coder"
            ]
        )
        let mentionsDispatch = containsAny(
            normalizedResponse,
            [
                "工单",
                "任务",
                "job",
                "丢给",
                "交给",
                "派给",
                "分派",
                "delegate"
            ]
        )
        let mentionsExecutionLoop = containsAny(
            normalizedResponse,
            [
                "执行",
                "推进",
                "干完",
                "做完",
                "完成",
                "run",
                "finish"
            ]
        )
        let mentionsReportBack = containsAny(
            normalizedResponse,
            [
                "回来",
                "回来跟我说",
                "回来告诉我",
                "回来汇报",
                "汇报",
                "report back",
                "come back"
            ]
        )
        let nuanceSignals = containsAny(
            normalizedResponse,
            [
                "绕过",
                "黑箱",
                "无边界",
                "无限放权",
                "不受治理",
                "脱离治理",
                "ungoverned",
                "unbounded"
            ]
        )

        return blanketNegative
            && mentionsProjectAI
            && (mentionsDispatch || mentionsExecutionLoop)
            && mentionsReportBack
            && !nuanceSignals
    }

    private func responseAppearsToIgnoreUserIntent(_ normalizedResponse: String) -> Bool {
        let signals = [
            normalizedResponse.contains("我已收到你的指令"),
            normalizedResponse.contains("作为 supervisor"),
            normalizedResponse.contains("你刚才说的是")
        ]
        return signals.filter { $0 }.count >= 2
    }

    private func responseAppearsToLeakTranscriptScaffolding(_ response: String) -> Bool {
        let lowered = response.lowercased()
        let scaffoldSignals = [
            "raw_messages:",
            "latest_user:",
            "recent_user_intent:",
            "recent_assistant_commitments:",
            "focused_project_recent_dialogue_recovery:"
        ]
        if scaffoldSignals.contains(where: { lowered.contains($0) }) {
            return true
        }

        let transcriptPrefixes = [
            "- assistant:",
            "- user:",
            "assistant:",
            "user:",
            "- system:",
            "system:"
        ]
        return response
            .split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
            .contains { line in
                transcriptPrefixes.contains(where: { line.hasPrefix($0) })
            }
    }

    private func responseAppearsToOverGovernSimpleGreeting(
        _ normalizedResponse: String,
        userMessage: String
    ) -> Bool {
        guard isSupervisorGreetingPrompt(userMessage) else { return false }

        if containsAny(
            normalizedResponse,
            [
                "这是一条普通的问候语",
                "普通的问候语",
                "只是一句问候语"
            ]
        ) {
            return true
        }

        let governanceSignals = containsAny(
            normalizedResponse,
            [
                "项目治理流程",
                "治理流程",
                "记忆深度达标",
                "长期目标和完成标准",
                "关键决策原因",
                "当前卡点",
                "合规替代方案"
            ]
        )
        let riskSignals = containsAny(
            normalizedResponse,
            [
                "高风险或不可逆的动作",
                "需要检查是否有高风险",
                "先解释后果与风险",
                "风险与后果"
            ]
        )
        let projectStatusSignals = containsAny(
            normalizedResponse,
            [
                "项目状态的查询",
                "项目处于阻塞状态",
                "补齐长期目标",
                "确认记忆深度"
            ]
        )

        return [governanceSignals, riskSignals, projectStatusSignals].filter { $0 }.count >= 2
    }

    private func naturalizeModelAssignmentResponse(
        result: ModelAssignmentResult,
        intent: DirectModelAssignmentIntent
    ) -> String {
        guard result.ok else {
            return "我试着改了，但这次没成功。\n\n\(result.message)"
        }

        let projectPhrase: String
        if intent.appliesToAllProjects {
            projectPhrase = "所有项目"
        } else if let projectRef = intent.projectRef, !projectRef.isEmpty {
            projectPhrase = "《\(projectRef)》"
        } else {
            projectPhrase = "当前项目"
        }

        let rolePhrase = naturalRolePhrase(intent.role)
        let modelPhrase = intent.modelId == "auto" ? "自动路由" : intent.modelId
        var lines: [String] = []

        if intent.appliesToAllProjects {
            lines.append("已经把\(projectPhrase)的 \(rolePhrase) 模型切到 \(modelPhrase)。")
        } else if intent.modelId == "auto" {
            lines.append("已经把\(projectPhrase)的 \(rolePhrase) 恢复到自动路由。")
        } else {
            lines.append("已经把\(projectPhrase)的 \(rolePhrase) 模型切到 \(modelPhrase)。")
        }

        if intent.usedDefaultRole {
            lines.append("你这句里没单独写角色，所以我默认按 coder 处理。")
        }

        return lines.joined(separator: "\n\n")
    }

    private func naturalRolePhrase(_ role: AXRole) -> String {
        switch role {
        case .coder:
            return "coder"
        case .coarse:
            return "coarse"
        case .refine:
            return "refine"
        case .reviewer:
            return "reviewer"
        case .advisor:
            return "advisor"
        case .supervisor:
            return "supervisor"
        }
    }

    private func calculateProgress(_ project: AXProjectEntry) -> Int {
        var progress = 55
        let runtime = runtimeStatus(for: project)
        if let state = project.currentStateSummary, !state.isEmpty { progress += 10 }
        if let next = project.nextStepSummary, !next.isEmpty { progress += 10 }
        if let blocker = project.blockerSummary, !blocker.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { progress -= 20 }
        if runtime.state == .paused { progress -= 8 }
        if project.lastOpenedAt > Date().timeIntervalSince1970 - 3600 { progress += 5 }
        return min(100, max(5, progress))
    }

    func calculatePriority(_ project: AXProjectEntry) -> Int {
        var priority = 100 - calculateProgress(project)
        if let blocker = project.blockerSummary, !blocker.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            priority += 15
        }
        if project.lastOpenedAt > Date().timeIntervalSince1970 - 3600 {
            priority += 8
        }
        return min(100, max(1, priority))
    }

    private func buildSupervisorMemoryV1(
        userMessage: String,
        triggerSource: SupervisorCommandTriggerSource = .userTurn
    ) async -> SupervisorMemoryBuildInfo {
        let composition = await composeSupervisorMemoryV1(
            userMessage: userMessage,
            triggerSource: triggerSource
        )
        let updatedAt = Date().timeIntervalSince1970
        let result = await HubIPCClient.requestMemoryContextDetailed(
            useMode: .supervisorOrchestration,
            requesterRole: .supervisor,
            projectId: nil,
            projectRoot: nil,
            displayName: "Supervisor",
            latestUser: userMessage,
            reviewLevelHint: composition.reviewLevelHint.rawValue,
            constitutionHint: composition.constitution,
            dialogueWindowText: composition.dialogueWindow,
            portfolioBriefText: composition.portfolioBrief,
            focusedProjectAnchorPackText: composition.focusedProjectAnchorPack,
            longtermOutlineText: composition.longtermOutline,
            deltaFeedText: composition.deltaFeed,
            conflictSetText: composition.conflictSet,
            contextRefsText: composition.contextRefs,
            evidencePackText: composition.evidencePack,
            canonicalText: composition.canonical,
            observationsText: composition.observations,
            workingSetText: composition.workingSet,
            rawEvidenceText: composition.rawEvidence,
            servingProfile: composition.servingProfile,
            progressiveDisclosure: true,
            budgets: nil,
            timeoutSec: 1.2
        )
        if let hub = result.response {
            let src = XTProjectMemoryGovernance.normalizedResolvedSource(hub.source)
            let text = injectedSupervisorCrossLinkRefsSection(
                into: sanitizeSupervisorOutboundPrompt(hub.text),
                crossLinkRefs: composition.crossLinkRefs
            )
            return SupervisorMemoryBuildInfo(
                text: text,
                source: src,
                updatedAt: updatedAt,
                assemblySnapshot: supervisorMemoryAssemblySnapshot(
                    from: composition,
                    resolution: result,
                    finalSource: src,
                    finalText: text,
                    updatedAt: updatedAt
                ),
                projectDigests: composition.projectDigests,
                skillRegistrySnapshot: composition.skillRegistrySnapshot
            )
        }
        if HubIPCClient.isRustMemoryGatewayRequiredFailure(result) {
            let text = sanitizeSupervisorOutboundPrompt(
                HubIPCClient.rustMemoryGatewayRequiredFailureMemoryText(result)
            )
            return SupervisorMemoryBuildInfo(
                text: text,
                source: result.source,
                updatedAt: updatedAt,
                assemblySnapshot: supervisorMemoryAssemblySnapshot(
                    from: composition,
                    resolution: result,
                    finalSource: result.source,
                    finalText: text,
                    updatedAt: updatedAt
                ),
                projectDigests: composition.projectDigests,
                skillRegistrySnapshot: composition.skillRegistrySnapshot
            )
        }
        let fallbackText = sanitizeSupervisorOutboundPrompt(composition.localText)
        return SupervisorMemoryBuildInfo(
            text: fallbackText,
            source: "local_fallback",
            updatedAt: updatedAt,
            assemblySnapshot: supervisorMemoryAssemblySnapshot(
                from: composition,
                resolution: result,
                finalSource: "local_fallback",
                finalText: fallbackText,
                updatedAt: updatedAt
            ),
            projectDigests: composition.projectDigests,
            skillRegistrySnapshot: composition.skillRegistrySnapshot
        )
    }

    private func composeSupervisorMemoryV1(
        userMessage: String,
        triggerSource: SupervisorCommandTriggerSource = .userTurn
    ) async -> SupervisorMemoryComposition {
        let constitution = loadConstitutionOneLiner(userMessage: userMessage)
        let projects = projectsForTriggerSource(triggerSource)
        let projectDigests = collectSupervisorProjectMemoryDigests(projects: projects)
        let turnRoutingDecision = resolveSupervisorTurnRoutingDecision(
            userMessage: userMessage,
            projects: projects
        )
        let candidateFocusedProjectSelection = focusedSupervisorCommandProjectSelection(
            projects: projects,
            userMessage: userMessage
        )
        let projectMemoryBinding = resolvedSupervisorProjectMemoryBinding(
            triggerSource: triggerSource,
            userMessage: userMessage,
            routingDecision: turnRoutingDecision,
            selection: candidateFocusedProjectSelection
        )
        let focusedProjectSelection = projectMemoryBinding.effectiveSelection
        let reviewLevelHint = preferredSupervisorReviewLevelHintForMemory(userMessage: userMessage)
        let explicitReviewTrigger = explicitSupervisorReviewTriggerHint(in: userMessage)
        let explicitReviewRunKind = explicitSupervisorReviewRunKindHint(in: userMessage)
        let assemblyPurpose = preferredSupervisorMemoryAssemblyPurpose(
            triggerSource: triggerSource,
            userMessage: userMessage,
            reviewLevelHint: reviewLevelHint,
            dominantMode: turnRoutingDecision.mode,
            focusedProjectSelected: focusedProjectSelection != nil,
            projectMemoryBindingStrength: projectMemoryBinding.strength
        )
        let governanceReviewTrigger = supervisorMemoryGovernanceReviewTrigger(
            triggerSource: triggerSource,
            assemblyPurpose: assemblyPurpose,
            explicitTrigger: explicitReviewTrigger,
            userMessage: userMessage
        )
        let governanceReviewRunKind = supervisorMemoryGovernanceReviewRunKind(
            triggerSource: triggerSource,
            assemblyPurpose: assemblyPurpose,
            trigger: governanceReviewTrigger,
            explicitRunKind: explicitReviewRunKind
        )
        let focusedProjectGovernance = focusedSupervisorProjectGovernanceForMemory(
            selection: focusedProjectSelection
        )
        let crossLinkRefs = supervisorMemoryCrossLinkRefs(
            projects: projects,
            turnRoutingDecision: turnRoutingDecision
        )
        let crossLinkContextAvailable = supervisorAssemblyHasMeaningfulContent(crossLinkRefs)

        let memoryPolicy = resolveSupervisorMemoryPolicyForAssembly(
            reviewLevelHint: reviewLevelHint,
            dominantMode: turnRoutingDecision.mode,
            focusedProjectSelected: focusedProjectSelection != nil,
            crossLinkContextAvailable: crossLinkContextAvailable,
            userMessage: userMessage,
            triggerSource: triggerSource,
            governanceReviewTrigger: governanceReviewTrigger,
            governanceReviewRunKind: governanceReviewRunKind,
            reviewMemoryCeiling: focusedProjectGovernance?.supervisorReviewMemoryCeiling,
            assemblyPurpose: assemblyPurpose,
            projectMemoryBinding: projectMemoryBinding
        )
        let servingProfile = memoryPolicy.effectiveServingProfile
        let focusedSkillProject = focusedProjectSelection?.project
        let skillRegistrySnapshot = await supervisorSkillRegistrySnapshotForMemory(
            focusedProject: focusedSkillProject
        )
        let memoryFragments = await supervisorMemoryFocusedProjectFragments(
            projects: projects,
            userMessage: userMessage,
            projectDigests: projectDigests,
            focusedProjectSelection: focusedProjectSelection,
            servingProfile: servingProfile,
            reviewLevelHint: reviewLevelHint
        )
        let governorMetadata = supervisorServingGovernorMetadata(
            servingProfile: servingProfile,
            reviewLevelHint: reviewLevelHint,
            focusedProjectSelected: focusedProjectSelection != nil,
            assemblyPurpose: assemblyPurpose,
            reviewMemoryCeiling: memoryPolicy.sTierReviewMemoryCeiling
        )
        let evidenceLayers = supervisorMemoryEvidenceLayers(
            servingContext: memoryFragments.servingContext,
            projectDigests: projectDigests,
            userMessage: userMessage
        )
        let dialogueWindowSelection = await renderSupervisorDialogueWindow(
            messages: frontstageConversationMessages,
            userMessage: userMessage,
            servingProfile: servingProfile,
            rawContextProfile: memoryPolicy.effectiveSupervisorRecentRawContextProfile,
            turnRoutingDecision: turnRoutingDecision,
            focusedProjectSelection: focusedProjectSelection
        )
        let dialogueWindow = sanitizeSupervisorPromptIdentifiers(
            dialogueWindowSelection.text
        )
        let scopedPromptRecovery = supervisorScopedPromptRecovery(
            focusedSelection: focusedProjectSelection,
            dialogueRecoveryIncluded: dialogueWindowSelection.continuityTraceLines.contains(
                "focused_project_dialogue_recovery=project_recent_context"
            )
        )
        let workingSetLayer = supervisorMemoryWorkingSetLayerForAssembly(
            focusedProjectSelection: focusedProjectSelection,
            workflowSlice: memoryFragments.workflowSlice,
            executionBrief: memoryFragments.executionBrief,
            focusedProjectRetrieval: memoryFragments.focusedProjectRetrieval
        )
        let rawEvidence = supervisorMemoryRawEvidenceLayer(
            availableModels: modelManager.availableModels,
            focusedSkillProject: focusedSkillProject,
            skillRegistrySnapshot: skillRegistrySnapshot
        )
        let canonical = memoryFragments.canonicalLayer
        let observations = memoryFragments.observationsLayer
        let workingSet = workingSetLayer
        let servingGovernorSection = supervisorServingGovernorSection(
            servingProfile: servingProfile,
            reviewLevelHint: reviewLevelHint,
            focusedProjectSelected: focusedProjectSelection != nil,
            assemblyPurpose: assemblyPurpose,
            reviewMemoryCeiling: memoryPolicy.sTierReviewMemoryCeiling
        )
        let servingObjectContract = supervisorServingObjectContract(
            memoryPolicy: memoryPolicy,
            minimumPack: governorMetadata.minimumPack,
            crossLinkRefs: crossLinkRefs
        )
        let localPrompt = renderSupervisorLocalMemoryV1(
            servingProfile: servingProfile,
            servingGovernorSection: servingGovernorSection,
            servingObjectContract: servingObjectContract,
            constitution: constitution,
            canonicalLayer: memoryFragments.canonicalLayer,
            observationsLayer: memoryFragments.observationsLayer,
            workingSetLayer: workingSetLayer,
            rawEvidence: rawEvidence,
            latestUserMessage: userMessage,
            dialogueWindow: dialogueWindow,
            portfolioBrief: memoryFragments.portfolioBrief,
            focusedProjectAnchorPack: memoryFragments.focusedProjectAnchorPack,
            crossLinkRefs: crossLinkRefs,
            longtermOutline: memoryFragments.longtermOutline,
            deltaFeed: memoryFragments.deltaFeed,
            conflictSet: evidenceLayers.conflictSet,
            contextRefs: evidenceLayers.contextRefs,
            evidencePack: evidenceLayers.evidencePack,
            contextRefsRender: evidenceLayers.contextRefsRender,
            evidencePackRender: evidenceLayers.evidencePackRender
        )
        let local = localPrompt.text

        return SupervisorMemoryComposition(
            memoryPolicy: memoryPolicy,
            servingProfile: servingProfile,
            triggerSource: triggerSource,
            governanceReviewTrigger: governanceReviewTrigger,
            governanceReviewRunKind: governanceReviewRunKind,
            reviewLevelHint: reviewLevelHint,
