            dialogueWindowContinuityTraceLines: dialogueWindowSelection.continuityTraceLines,
            dialogueWindowLowSignalDropSampleLines: dialogueWindowSelection.lowSignalDropSampleLines,
            portfolioBrief: memoryFragments.portfolioBrief,
            focusedProjectAnchorPack: memoryFragments.focusedProjectAnchorPack,
            crossLinkRefs: crossLinkRefs,
            longtermOutline: memoryFragments.longtermOutline,
            deltaFeed: memoryFragments.deltaFeed,
            conflictSet: evidenceLayers.conflictSet,
            contextRefs: evidenceLayers.contextRefs,
            evidencePack: evidenceLayers.evidencePack,
            canonical: canonical,
            observations: observations,
            workingSet: workingSet,
            rawEvidence: rawEvidence,
            localText: local,
            focusedProjectId: focusedProjectSelection?.project.projectId,
            profileFloor: memoryPolicy.minimumRequiredReviewServingProfile,
            minimumPack: governorMetadata.minimumPack,
            servingObjectContract: servingObjectContract,
            compressionPolicy: governorMetadata.compressionPolicy,
            selectedSections: localPrompt.selectedSections,
