            evidenceItemsSelectedCount: localPrompt.evidenceItemsSelectedCount,
            evidenceItemsOmittedCount: localPrompt.evidenceItemsOmittedCount,
            latestReviewNoteAvailable: memoryFragments.servingContext?.latestReview != nil,
            latestGuidanceAvailable: memoryFragments.servingContext?.latestGuidance != nil,
            latestGuidanceAckStatus: memoryFragments.servingContext?.latestGuidance?.ackStatus.rawValue ?? "",
            latestGuidanceAckRequired: memoryFragments.servingContext?.latestGuidance?.ackRequired,
