    private func supervisorGuidanceInjection(
        from note: SupervisorReviewNoteRecord,
        policy: SupervisorReviewPolicyDecision,
        injectedAtMs: Int64
    ) -> SupervisorGuidanceInjectionRecord {
        let guidanceText = supervisorGuidanceText(for: note)
        let lifecycle = supervisorGuidanceLifecycle(policy: policy, injectedAtMs: injectedAtMs)
        return SupervisorGuidanceInjectionBuilder.build(
            injectionId: "guidance-\(note.reviewId)",
            reviewId: note.reviewId,
            projectId: note.projectId,
            targetRole: note.targetRole,
            deliveryMode: note.deliveryMode,
            interventionMode: policy.interventionMode,
            safePointPolicy: policy.safePointPolicy,
            guidanceText: guidanceText,
            ackStatus: .pending,
            ackRequired: policy.ackRequired,
            effectiveSupervisorTier: note.effectiveSupervisorTier,
            effectiveWorkOrderDepth: note.effectiveWorkOrderDepth,
            workOrderRef: note.workOrderRef,
            ackNote: "",
            injectedAtMs: injectedAtMs,
            ackUpdatedAtMs: 0,
            expiresAtMs: lifecycle.expiresAtMs,
            retryAtMs: 0,
            retryCount: 0,
            maxRetryCount: lifecycle.maxRetryCount,
            auditRef: "audit-guidance-\(note.reviewId)"
        )
    }

    private func supervisorGuidanceLifecycle(
        policy: SupervisorReviewPolicyDecision,
        injectedAtMs: Int64
    ) -> (expiresAtMs: Int64, maxRetryCount: Int) {
        let ttlMinutes: Int64
        let maxRetryCount: Int

        switch policy.interventionMode {
        case .stopImmediately:
            ttlMinutes = 15
            maxRetryCount = 1
        case .replanNextSafePoint:
            ttlMinutes = policy.reviewLevel == .r3Rescue ? 60 : 120
            maxRetryCount = policy.reviewLevel == .r3Rescue ? 1 : 2
        case .suggestNextSafePoint:
            ttlMinutes = policy.reviewLevel == .r1Pulse ? 45 : 90
            maxRetryCount = 2
        case .observeOnly:
            ttlMinutes = 30
            maxRetryCount = 0
        }

        return (
            expiresAtMs: injectedAtMs + ttlMinutes * 60 * 1000,
            maxRetryCount: maxRetryCount
        )
    }

    private func supervisorGuidanceText(
        for note: SupervisorReviewNoteRecord
    ) -> String {
        var lines: [String] = [
            "verdict=\(note.verdict.rawValue)",
            "summary=\(note.summary)",
            "effective_supervisor_tier=\(note.effectiveSupervisorTier?.rawValue ?? "(none)")",
            "effective_work_order_depth=\(note.effectiveWorkOrderDepth?.rawValue ?? "(none)")",
            "work_order_ref=\(note.workOrderRef ?? "(none)")"
        ]
        if !note.recommendedActions.isEmpty {
            lines.append("actions=\(note.recommendedActions.joined(separator: " | "))")
        }
        return lines.joined(separator: "\n")
    }

    private func supervisorReviewWorkOrderRef(
        job: SupervisorJobRecord?,
        plan: SupervisorPlanRecord?
    ) -> String? {
        if let planId = plan?.planId.trimmingCharacters(in: .whitespacesAndNewlines),
           !planId.isEmpty {
            return "plan:\(planId)"
        }
        if let jobId = job?.jobId.trimmingCharacters(in: .whitespacesAndNewlines),
           !jobId.isEmpty {
            return "job:\(jobId)"
        }
        return nil
    }

    func focusedSupervisorReviewConstraintDigest(
        specCapsule: SupervisorProjectSpecCapsule?,
        config: AXProjectConfig,
        effectiveRuntimeSurface: AXProjectRuntimeSurfaceEffectivePolicy
    ) -> String {
        var lines: [String] = []
        if let specCapsule {
            if !specCapsule.nonGoals.isEmpty {
                lines.append("- non_goals: \(focusedSupervisorJoinedValueList(specCapsule.nonGoals, maxItems: 3, maxChars: 72))")
            }
            if !specCapsule.techStackBlacklist.isEmpty {
                lines.append("- tech_stack_blacklist: \(focusedSupervisorJoinedValueList(specCapsule.techStackBlacklist, maxItems: 3, maxChars: 72))")
            }
            if !specCapsule.approvedTechStack.isEmpty {
                lines.append("- approved_tech_stack: \(focusedSupervisorJoinedValueList(specCapsule.approvedTechStack, maxItems: 3, maxChars: 72))")
            }
        }
        lines.append(
            "- runtime_surface_guard: configured=\(config.runtimeSurfaceMode.rawValue), effective=\(effectiveRuntimeSurface.effectiveMode.rawValue), override=\(effectiveRuntimeSurface.hubOverrideMode.rawValue), kill_switch=\(effectiveRuntimeSurface.killSwitchEngaged ? "yes" : "no")"
        )
        return lines.isEmpty ? "(none)" : lines.joined(separator: "\n")
    }

    func focusedSupervisorInlineConstraintDigest(
        specCapsule: SupervisorProjectSpecCapsule?,
        config: AXProjectConfig,
        effectiveRuntimeSurface: AXProjectRuntimeSurfaceEffectivePolicy
    ) -> String {
        var items: [String] = []
        if let specCapsule, !specCapsule.nonGoals.isEmpty {
            items.append("non_goals=\(focusedSupervisorJoinedValueList(specCapsule.nonGoals, maxItems: 2, maxChars: 48))")
        }
        if let specCapsule, !specCapsule.techStackBlacklist.isEmpty {
            items.append("blacklist=\(focusedSupervisorJoinedValueList(specCapsule.techStackBlacklist, maxItems: 2, maxChars: 48))")
        }
        if let specCapsule, !specCapsule.approvedTechStack.isEmpty {
            items.append("stack=\(focusedSupervisorJoinedValueList(specCapsule.approvedTechStack, maxItems: 2, maxChars: 48))")
        }
        items.append("surface=\(config.runtimeSurfaceMode.rawValue)->\(effectiveRuntimeSurface.effectiveMode.rawValue)")
        items.append("override=\(effectiveRuntimeSurface.hubOverrideMode.rawValue)")
        return items.joined(separator: " | ")
    }

    func focusedSupervisorApprovedDecisionDigest(
        _ hardDecisions: [SupervisorDecisionCategory: SupervisorDecisionTrackEvent]
    ) -> String {
        let rows = hardDecisions.values
            .sorted { lhs, rhs in
                if lhs.updatedAtMs != rhs.updatedAtMs {
                    return lhs.updatedAtMs > rhs.updatedAtMs
                }
                return lhs.category.rawValue < rhs.category.rawValue
            }
            .prefix(4)
            .map { decision in
                "- \(decision.category.rawValue)=\(capped(firstNonEmptyLine(in: decision.statement), maxChars: 140))"
            }
        return rows.isEmpty ? "(none)" : rows.joined(separator: "\n")
    }

    func focusedSupervisorRuntimeGovernanceDigest(
        governance: SupervisorProjectDigestGovernanceContext,
        config: AXProjectConfig,
        effectiveRuntimeSurface: AXProjectRuntimeSurfaceEffectivePolicy
    ) -> String {
        guard let resolved = governance.resolvedGovernance else {
            return """
runtime_surface: configured=\(config.runtimeSurfaceMode.rawValue) effective=\(effectiveRuntimeSurface.effectiveMode.rawValue) override=\(effectiveRuntimeSurface.hubOverrideMode.rawValue) ttl_remaining_sec=\(effectiveRuntimeSurface.remainingSeconds)
"""
        }

        let adaptation = resolved.supervisorAdaptation
        let strength = adaptation.projectAIStrengthProfile
        let strengthAuditRef = strength?.auditRef.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        return """
runtime_surface: configured=\(config.runtimeSurfaceMode.rawValue) effective=\(resolved.effectiveRuntimeSurface.effectiveMode.rawValue) override=\(resolved.effectiveRuntimeSurface.hubOverrideMode.rawValue) ttl_remaining_sec=\(resolved.effectiveRuntimeSurface.remainingSeconds)
execution_tier: configured=\(resolved.configuredBundle.executionTier.rawValue) effective=\(resolved.effectiveBundle.executionTier.rawValue)
supervisor_tier: configured=\(adaptation.configuredSupervisorTier.rawValue) baseline_recommended=\(adaptation.baselineRecommendedSupervisorTier.rawValue) recommended=\(adaptation.recommendedSupervisorTier.rawValue) effective=\(adaptation.effectiveSupervisorTier.rawValue)
work_order_depth: recommended=\(adaptation.recommendedWorkOrderDepth.rawValue) effective=\(adaptation.effectiveWorkOrderDepth.rawValue) adaptation_mode=\(adaptation.adaptationPolicy.adaptationMode.rawValue)
project_ai_strength: band=\(strength?.strengthBand.rawValue ?? AXProjectAIStrengthBand.unknown.rawValue) confidence=\(focusedSupervisorConfidenceText(strength?.confidence ?? 0)) audit_ref=\(strengthAuditRef.isEmpty ? "(none)" : strengthAuditRef)
project_ai_strength_reasons: \(focusedSupervisorJoinedValueList(strength?.reasons ?? [], maxItems: 4, maxChars: 72))
supervisor_escalation_reasons: \(focusedSupervisorJoinedValueList(adaptation.escalationReasons, maxItems: 3, maxChars: 72))
governance_warnings: \(focusedSupervisorJoinedValueList(resolved.validation.warningReasons, maxItems: 3, maxChars: 64))
governance_invalid: \(focusedSupervisorJoinedValueList(resolved.validation.invalidReasons, maxItems: 3, maxChars: 64))
allowed_capabilities: \(focusedSupervisorJoinedValueList(resolved.capabilityBundle.allowedCapabilityLabels, maxItems: 6, maxChars: 40))
"""
    }

    func focusedSupervisorRuntimeGovernanceInlineDigest(
        governance: SupervisorProjectDigestGovernanceContext,
        config: AXProjectConfig,
        effectiveRuntimeSurface: AXProjectRuntimeSurfaceEffectivePolicy
    ) -> String {
        guard let resolved = governance.resolvedGovernance else {
            return capped(
                "surface=\(config.runtimeSurfaceMode.rawValue)->\(effectiveRuntimeSurface.effectiveMode.rawValue)",
                maxChars: 160
            )
        }

        let adaptation = resolved.supervisorAdaptation
        let strength = adaptation.projectAIStrengthProfile
        return capped(
            "exec=\(resolved.effectiveBundle.executionTier.rawValue) supervisor=\(adaptation.configuredSupervisorTier.rawValue)->\(adaptation.effectiveSupervisorTier.rawValue) depth=\(adaptation.effectiveWorkOrderDepth.rawValue) strength=\(strength?.strengthBand.rawValue ?? AXProjectAIStrengthBand.unknown.rawValue)(\(focusedSupervisorConfidenceText(strength?.confidence ?? 0))) mode=\(adaptation.adaptationPolicy.adaptationMode.rawValue)",
            maxChars: 220
        )
    }

    func focusedSupervisorRuntimeGovernanceReasonsInlineDigest(
        _ governance: SupervisorProjectDigestGovernanceContext
    ) -> String {
        guard let resolved = governance.resolvedGovernance else {
            return "(none)"
        }
        let adaptation = resolved.supervisorAdaptation
        return focusedSupervisorJoinedValueList(
            adaptation.escalationReasons + (adaptation.projectAIStrengthProfile?.reasons ?? []),
            maxItems: 4,
            maxChars: 56
        )
    }

    private func focusedSupervisorConfidenceText(_ value: Double) -> String {
        String(format: "%.2f", min(1, max(0, value)))
    }

    private func supervisorScopedPromptRecovery(
        focusedSelection: SupervisorFocusedProjectSelection?,
        dialogueRecoveryIncluded: Bool
    ) -> (mode: String?, sections: [String]) {
        guard let focusedSelection else {
            return (nil, [])
        }

        let explicitHiddenProjectFocus = focusedSelection.source == "explicit_user_mention" &&
            !projectVisibleInCurrentSupervisorJurisdiction(focusedSelection.project)
        guard explicitHiddenProjectFocus else {
            return (nil, [])
        }

        var sections = [
            "l1_canonical.focused_project_anchor_pack",
            "l2_observations.project_recent_events",
            "l3_working_set.project_activity_memory"
        ]
        if dialogueRecoveryIncluded {
            sections.append("dialogue_window.project_recent_context")
        }
        return ("explicit_hidden_project_focus", sections)
    }

    private func loadConstitutionOneLiner(userMessage: String) -> String {
        // Keep routine coding asks concise to avoid over-triggering policy-style refusals.
        if shouldUseConciseConstitutionForLowRiskRequest(userMessage) {
            return "优先给出可执行答案；保持真实透明并保护隐私。"
        }
        return configuredSupervisorConstitutionOneLiner()
    }

    private func normalizedConstitutionOneLiner(_ raw: String) -> String {
        let t = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !t.isEmpty else {
            return defaultSupervisorConstitutionFallback()
        }

        let legacy = "真实透明、最小化外发、关键风险先解释后执行。"
        var out = t
        if out == legacy {
            out = "真实透明、最小化外发；仅在高风险或不可逆动作时先解释后执行；普通编程/创作请求直接给出可执行答案。"
        }

        let lower = out.lowercased()
        let zhRiskFocused =
            out.contains("高风险") ||
            out.contains("合规") ||
            out.contains("法律") ||
            out.contains("隐私") ||
            out.contains("安全") ||
            out.contains("伤害") ||
            out.contains("必要时拒绝") ||
            out.contains("关键风险先解释后执行")
        let enRiskFocused =
            lower.contains("high-risk") ||
            lower.contains("compliance") ||
            lower.contains("legal") ||
            lower.contains("privacy") ||
            lower.contains("safety") ||
            lower.contains("harm") ||
            lower.contains("refuse")

        let zhHasCarveout =
            out.contains("仅在高风险") ||
            out.contains("低风险") ||
            out.contains("普通编程") ||
            out.contains("普通创作") ||
            out.contains("普通请求") ||
            out.contains("直接给出可执行答案") ||
            out.contains("直接回答")
        let enHasCarveout =
            lower.contains("only for high-risk") ||
            lower.contains("normal coding") ||
            lower.contains("creative requests") ||
            lower.contains("respond directly") ||
            lower.contains("answer normal")

        if zhRiskFocused && !zhHasCarveout {
            return out + " 仅在高风险或不可逆动作时先解释后执行；普通编程/创作请求直接给出可执行答案。"
        }
        if enRiskFocused && !enHasCarveout {
            return out + " Explain first only for high-risk or irreversible actions; answer normal coding/creative requests directly."
        }
        return out
    }

    private func shouldUseConciseConstitutionForLowRiskRequest(_ userText: String) -> Bool {
        let t = userText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if t.isEmpty { return false }

        let codingSignals = [
            "写一个", "写个", "代码", "程序", "脚本", "函数", "类", "项目", "网页", "网站", "游戏", "赛车游戏",
            "write", "code", "script", "function", "class", "build", "create", "game", "app", "web"
        ]
        let riskSignals = [
            "绕过", "规避", "破解", "入侵", "提权", "钓鱼", "木马", "勒索", "盗号", "删日志",
            "违法", "犯罪", "武器", "爆炸", "毒品", "未成年人", "自杀", "自残", "伤害", "暴力",
            "法律", "合规", "隐私", "保密", "风险", "后果",
            "bypass", "circumvent", "hack", "exploit", "privilege escalation", "phishing", "malware", "ransomware",
            "illegal", "weapon", "explosive", "drugs", "minor", "suicide", "self-harm", "violence",
            "legal", "compliance", "privacy", "risk", "consequence"
        ]
        let hasCoding = codingSignals.contains(where: { t.contains($0) })
        let hasRisk = riskSignals.contains(where: { t.contains($0) })
        return hasCoding && !hasRisk
    }

    @discardableResult
    func applySupervisorJurisdictionRegistry(
        _ registry: SupervisorJurisdictionRegistry,
        persist: Bool = true,
        normalizeWithKnownProjects: Bool = true
    ) -> SupervisorJurisdictionRegistry {
        let normalized = normalizeWithKnownProjects
            ? registry.normalized(for: knownProjects())
            : registry
        supervisorJurisdictionRegistry = normalized
        if persist && persistSupervisorRuntimeState {
            SupervisorJurisdictionRegistryStore.save(normalized)
        }
        supervisorMemoryProjectDigests = normalized.filteredDigests(supervisorMemoryProjectDigests)
        supervisorPortfolioSnapshot = SupervisorPortfolioSnapshotBuilder.build(from: supervisorMemoryProjectDigests)
        rebuildVisibleRecentProjectActionEvents()
        rebuildVisibleRecentEvents()
        if supervisorMemoryUpdatedAt > 0 || !supervisorMemorySource.isEmpty {
            supervisorMemoryStatusLine = "memory=\(supervisorMemorySource) · projects=\(supervisorMemoryProjectDigests.count) · updated=\(Int(supervisorMemoryUpdatedAt))"
        }
        return normalized
    }

    func syncSupervisorJurisdictionRegistry(with projects: [AXProjectEntry]) -> SupervisorJurisdictionRegistry {
        let normalized = supervisorJurisdictionRegistry.normalized(for: projects)
        guard normalized != supervisorJurisdictionRegistry else { return supervisorJurisdictionRegistry }
        supervisorJurisdictionRegistry = normalized
        if persistSupervisorRuntimeState {
            SupervisorJurisdictionRegistryStore.save(normalized)
        }
        supervisorMemoryProjectDigests = normalized.filteredDigests(supervisorMemoryProjectDigests)
        supervisorPortfolioSnapshot = SupervisorPortfolioSnapshotBuilder.build(from: supervisorMemoryProjectDigests)
        rebuildVisibleRecentProjectActionEvents()
        rebuildVisibleRecentEvents()
        return normalized
    }

    func knownProjects() -> [AXProjectEntry] {
        let registry = appModel?.registry ?? (
            allowPersistentProjectRegistryFallback
                ? AXProjectRegistryStore.load()
                : .empty()
        )
        let projects = AXProjectRegistryStore.sanitizeLoadedRegistry(registry).registry.projects
        return projects.sorted { a, b in
            if a.pinned != b.pinned { return a.pinned && !b.pinned }
            if a.lastOpenedAt != b.lastOpenedAt { return a.lastOpenedAt > b.lastOpenedAt }
            return a.displayName.localizedCaseInsensitiveCompare(b.displayName) == .orderedAscending
        }
    }

    private func automationCommandProjects() -> [AXProjectEntry] {
        let projects = knownProjects()
        guard let snapshotProject = automationSnapshotProject else {
            return projects
        }
        let normalizedSnapshotRoot = AXProjectRegistryStore.normalizedRootPath(
            URL(fileURLWithPath: snapshotProject.rootPath)
        )
        if projects.contains(where: { candidate in
            if candidate.projectId.compare(snapshotProject.projectId, options: .caseInsensitive) == .orderedSame {
                return true
            }
            let rootPath = candidate.rootPath.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !rootPath.isEmpty else { return false }
            return AXProjectRegistryStore.normalizedRootPath(URL(fileURLWithPath: rootPath)) == normalizedSnapshotRoot
        }) {
            return projects
        }
        return [snapshotProject] + projects
    }

    func allProjects() -> [AXProjectEntry] {
        let projects = knownProjects()
        let registry = syncSupervisorJurisdictionRegistry(with: projects)
        return registry.filteredProjects(projects)
    }

