    @discardableResult
    func reconcileProjectNotificationCenterState(
        activeEventIDs: [String],
        now: Date = Date()
    ) -> SupervisorProjectNotificationCenterState {
        let activeIDs = Set(
            activeEventIDs.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
        )
        let normalized = supervisorProjectNotificationCenterState.normalized(
            now: now,
            activeEventIDs: activeIDs
        )
        applyProjectNotificationCenterState(normalized, now: now)
        return supervisorProjectNotificationCenterState
    }

