    var frontstageSupervisorEventLoopStatusLine: String {
        let visibleQueuedCount = pendingSupervisorEventLoopTriggers.filter {
            supervisorEventLoopTriggerVisibleInCurrentSupervisorJurisdictionOrUnknown($0)
        }.count
        let visibleActivities = frontstageRecentSupervisorEventLoopActivities
        let hasVisibleRunning = visibleActivities.contains { activity in
            activity.status.trimmingCharacters(in: .whitespacesAndNewlines)
                .localizedCaseInsensitiveCompare("running") == .orderedSame
        }
        if hasVisibleRunning, visibleQueuedCount > 0 {
            return "running · queued \(visibleQueuedCount)"
        }
        if hasVisibleRunning {
            return "running"
        }
        if visibleQueuedCount > 0 {
            return "queued \(visibleQueuedCount)"
        }
        return visibleActivities.isEmpty ? "idle" : "idle · recent activity"
    }

    private func projectsForTriggerSource(
        _ triggerSource: SupervisorCommandTriggerSource
    ) -> [AXProjectEntry] {
        triggerSource == .userTurn ? allProjects() : knownProjects()
    }

    private func recentEventVisibleInCurrentSupervisorJurisdiction(
        _ record: SupervisorRecentEventRecord
    ) -> Bool {
        let projectId = record.projectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let projectName = record.projectName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if projectId.isEmpty && projectName.isEmpty {
            return !record.requiresKnownProjectMatch
        }
        if record.requiresKnownProjectMatch {
            guard let knownProject = knownProjectMatching(
                projectId: projectId,
                projectName: projectName
            ) else {
                return false
            }
            return projectVisibleInCurrentSupervisorJurisdiction(knownProject)
        }
        return projectVisibleInCurrentSupervisorJurisdictionOrUnknown(
            projectId: projectId,
            projectName: projectName
        )
    }

    func supervisorRecentEventRecord(
        _ record: SupervisorRecentEventRecord,
        matches project: AXProjectEntry
    ) -> Bool {
        let projectId = record.projectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let projectName = record.projectName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !projectId.isEmpty,
           projectId.compare(project.projectId, options: .caseInsensitive) == .orderedSame {
            return true
        }
        if !projectName.isEmpty,
           projectName.compare(project.displayName, options: .caseInsensitive) == .orderedSame {
            return true
        }
        return false
    }

    func supervisorRecentEventRecordsForPrompt(
        focusedSelection: SupervisorFocusedProjectSelection?
    ) -> [SupervisorRecentEventRecord] {
        guard let focusedSelection else {
            return supervisorRecentEventRecords.filter(recentEventVisibleInCurrentSupervisorJurisdiction(_:))
        }

        let explicitHiddenProjectFocus = focusedSelection.source == "explicit_user_mention" &&
            !projectVisibleInCurrentSupervisorJurisdiction(focusedSelection.project)
        if explicitHiddenProjectFocus {
            return supervisorRecentEventRecords.filter {
                supervisorRecentEventRecord($0, matches: focusedSelection.project)
            }
        }

        return supervisorRecentEventRecords.filter(recentEventVisibleInCurrentSupervisorJurisdiction(_:))
    }

    private func rebuildVisibleRecentEvents() {
        recentEvents = supervisorRecentEventRecords
            .filter(recentEventVisibleInCurrentSupervisorJurisdiction(_:))
            .map(\.text)
        if recentEvents.count > supervisorRecentEventMaxEntries {
            recentEvents.removeFirst(recentEvents.count - supervisorRecentEventMaxEntries)
        }
    }

    private func rebuildVisibleRecentProjectActionEvents() {
        supervisorRecentProjectActionEvents = supervisorJurisdictionRegistry
            .filteredEvents(supervisorProjectActionEventRecords)
        if supervisorRecentProjectActionEvents.count > supervisorProjectActionEventMaxEntries {
            supervisorRecentProjectActionEvents.removeLast(
                supervisorRecentProjectActionEvents.count - supervisorProjectActionEventMaxEntries
            )
        }
    }

    func supervisorDeltaFeedProjectActionEvents(
        focusedSelection: SupervisorFocusedProjectSelection?
    ) -> [SupervisorProjectActionEvent] {
        guard let focusedSelection else {
            return frontstageRecentProjectActionEvents
        }

        let explicitHiddenProjectFocus = focusedSelection.source == "explicit_user_mention" &&
            !projectVisibleInCurrentSupervisorJurisdiction(focusedSelection.project)
        if explicitHiddenProjectFocus {
            return supervisorProjectActionEventRecords.filter { event in
                event.projectId.compare(
                    focusedSelection.project.projectId,
                    options: .caseInsensitive
                ) == .orderedSame
            }
        }

        return frontstageRecentProjectActionEvents
    }

    private func appendRecentEventRecord(
        _ text: String,
        projectId: String? = nil,
        projectName: String? = nil,
        requiresKnownProjectMatch: Bool = false
    ) {
        let cleaned = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleaned.isEmpty else { return }
        supervisorRecentEventRecords.append(
            SupervisorRecentEventRecord(
                id: UUID().uuidString,
                createdAt: Date().timeIntervalSince1970,
                text: cleaned,
                projectId: projectId,
                projectName: projectName,
                requiresKnownProjectMatch: requiresKnownProjectMatch
            )
        )
        if supervisorRecentEventRecords.count > supervisorRecentEventRecordMaxEntries {
            supervisorRecentEventRecords.removeFirst(
                supervisorRecentEventRecords.count - supervisorRecentEventRecordMaxEntries
            )
        }
        rebuildVisibleRecentEvents()
    }

