    private func appendProjectActionEvent(_ event: SupervisorProjectActionEvent) {
        if let first = supervisorProjectActionEventRecords.first,
           first.projectId == event.projectId,
           first.eventType == event.eventType,
           first.actionSummary == event.actionSummary,
           first.nextAction == event.nextAction,
           abs(first.occurredAt - event.occurredAt) <= 30 {
            return
        }

        supervisorProjectActionEventRecords.insert(event, at: 0)
        if supervisorProjectActionEventRecords.count > supervisorProjectActionEventMaxEntries {
            supervisorProjectActionEventRecords.removeLast(
                supervisorProjectActionEventRecords.count - supervisorProjectActionEventMaxEntries
            )
        }
        rebuildVisibleRecentProjectActionEvents()
    }

    private func deliverProjectActionNotificationIfNeeded(
        _ event: SupervisorProjectActionEvent,
        now: TimeInterval = Date().timeIntervalSince1970
    ) {
        let decision = SupervisorProjectNotificationPolicy.decide(for: event)
        guard supervisorJurisdictionRegistry.allowsEventVisibility(event) else {
            updateProjectNotificationSnapshot(
                event: event,
                channel: decision.channel,
                status: .suppressedJurisdiction,
                now: now
            )
            return
        }
        let fingerprint = SupervisorProjectNotificationPolicy.dedupeFingerprint(for: event, channel: decision.channel)
        if decision.shouldDedupe,
           let last = supervisorProjectNotificationLastDeliveredAt[fingerprint],
           now - last < decision.dedupeWindowSec {
            updateProjectNotificationSnapshot(
                event: event,
                channel: decision.channel,
                status: .suppressedDuplicate,
                now: now
            )
            return
        }

        supervisorProjectNotificationLastDeliveredAt[fingerprint] = now
        if decision.shouldAddSystemMessage, let message = decision.systemMessage {
            addSystemMessage(message)
        }
        if decision.shouldOpenConversationWindow {
            conversationWindowBridge.requestOpen(
                reason: "project_event:\(event.projectId):\(event.eventType.rawValue)",
                focusConversation: false
            )
        }
        pushProjectActionNotificationIfNeeded(
            event: event,
            channel: decision.channel,
            dedupeKey: fingerprint
        )
        updateProjectNotificationSnapshot(
            event: event,
            channel: decision.channel,
            status: .delivered,
            now: now
        )
    }

    private func pushProjectActionNotificationIfNeeded(
        event: SupervisorProjectActionEvent,
        channel: SupervisorProjectNotificationChannel,
        dedupeKey: String
    ) {
        switch channel {
        case .interruptNow, .briefCard:
            let actionURL = resumeProjectActionURL(projectId: event.projectId)
            let hubDedupeKey = "x_terminal_project_action_\(dedupeKey)"
            guard shouldMirrorNotificationToHub(actionURL: actionURL) else {
                HubIPCClient.removeNotification(dedupeKey: hubDedupeKey)
                return
            }
            let body = """
summary=\(event.actionSummary)
next=\(event.nextAction)
why=\(event.whyItMatters)
"""
            HubIPCClient.pushNotification(
                source: "X-Terminal",
                title: event.actionTitle,
                body: body,
                dedupeKey: hubDedupeKey,
                actionURL: actionURL,
                unread: true
            )
        case .badgeOnly, .silentLog:
            return
        }
    }

    func shouldMirrorNotificationToHub(actionURL: String?) -> Bool {
        if HubAIClient.transportMode() == .fileIPC {
            return true
        }
        let raw = actionURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !raw.isEmpty, let url = URL(string: raw) else {
            return true
        }
        return (url.scheme ?? "").lowercased() != "xterminal"
    }

    private func updateProjectNotificationSnapshot(
        event: SupervisorProjectActionEvent,
        channel: SupervisorProjectNotificationChannel,
        status: SupervisorProjectNotificationDeliveryStatus,
        now: TimeInterval
    ) {
        let deliverySummary = SupervisorProjectNotificationPolicy.deliverySummary(
            event: event,
            channel: channel,
            status: status
        )
        appendProjectNotificationRecord(
            event: event,
            channel: channel,
            status: status,
            now: now,
            deliverySummary: deliverySummary
        )

        guard status != .suppressedJurisdiction else {
            appendProjectActionAudit(event: event, channel: channel, status: status)
            return
        }

        var snapshot = supervisorProjectNotificationSnapshot
        snapshot.updatedAt = now
        snapshot.lastDeliverySummary = deliverySummary

        if status == .suppressedDuplicate {
            snapshot.suppressedDuplicates += 1
            supervisorProjectNotificationSnapshot = snapshot
            appendProjectActionAudit(event: event, channel: channel, status: status)
            return
        }

        switch channel {
        case .interruptNow:
            snapshot.deliveredInterrupts += 1
        case .briefCard:
            snapshot.deliveredBriefs += 1
        case .badgeOnly:
            snapshot.deliveredBadges += 1
        case .silentLog:
            snapshot.mutedLogs += 1
        }
        supervisorProjectNotificationSnapshot = snapshot
        appendProjectActionAudit(event: event, channel: channel, status: status)
    }

    private func appendProjectNotificationRecord(
        event: SupervisorProjectActionEvent,
        channel: SupervisorProjectNotificationChannel,
        status: SupervisorProjectNotificationDeliveryStatus,
        now: TimeInterval,
        deliverySummary: String
    ) {
        supervisorProjectNotificationRecords.append(
            SupervisorProjectNotificationRecord(
                projectId: event.projectId,
                projectName: event.projectName,
                eventType: event.eventType,
                severity: event.severity,
                channel: channel,
                status: status,
                occurredAt: now,
                deliverySummary: deliverySummary
            )
        )
        if supervisorProjectNotificationRecords.count > supervisorProjectNotificationRecordMaxEntries {
            supervisorProjectNotificationRecords.removeFirst(
                supervisorProjectNotificationRecords.count - supervisorProjectNotificationRecordMaxEntries
            )
        }
    }

    private func appendProjectActionAudit(
        event: SupervisorProjectActionEvent,
        channel: SupervisorProjectNotificationChannel,
        status: SupervisorProjectNotificationDeliveryStatus
    ) {
        let jurisdictionRole = supervisorJurisdictionRegistry.role(for: event.projectId).rawValue
        let grantedScope = supervisorJurisdictionRegistry
            .allowedDrillDownScopes(projectId: event.projectId)
            .sorted { $0.rank < $1.rank }
            .last?
            .rawValue
        HubIPCClient.appendSupervisorProjectActionAudit(
            eventID: event.eventId,
            projectID: event.projectId,
            projectName: event.projectName,
            eventType: event.eventType.rawValue,
            severity: event.severity.rawValue,
            actionTitle: event.actionTitle,
            actionSummary: event.actionSummary,
            whyItMatters: event.whyItMatters,
            nextAction: event.nextAction,
            occurredAtMs: Int64((event.occurredAt * 1000.0).rounded()),
            deliveryChannel: channel.rawValue,
            deliveryStatus: status.rawValue,
            jurisdictionRole: jurisdictionRole,
            grantedScope: grantedScope,
            auditRef: "project_action_audit:\(event.eventId)"
        )
    }

    @discardableResult
    func appendActionLedger(
        action: String,
        targetRef: String,
        projectId: String?,
        projectName: String?,
        role: String?,
        modelId: String?,
        status: String,
        reasonCode: String,
        detail: String,
        verifiedAt: Double?,
        triggerSource: String? = nil
    ) -> String {
        let entry = SupervisorActionLedgerEntry(
            id: UUID().uuidString,
            createdAt: Date().timeIntervalSince1970,
            action: action,
            targetRef: targetRef,
            projectId: projectId,
            projectName: projectName,
            role: role,
            modelId: modelId,
            status: status,
            reasonCode: reasonCode,
            detail: capped(detail, maxChars: 220),
            verifiedAt: verifiedAt,
            triggerSource: triggerSource
        )
        actionLedger.append(entry)
        if actionLedger.count > actionLedgerMaxEntries {
            actionLedger.removeFirst(actionLedger.count - actionLedgerMaxEntries)
        }
        saveActionLedgerToDisk()
        return entry.id
    }

    private func updateActionLedger(
        id: String,
        status: String,
        reasonCode: String,
        detail: String,
        verifiedAt: Double?
    ) {
        guard let idx = actionLedger.lastIndex(where: { $0.id == id }) else { return }
        actionLedger[idx].status = status
        actionLedger[idx].reasonCode = reasonCode
        actionLedger[idx].detail = capped(detail, maxChars: 220)
        actionLedger[idx].verifiedAt = verifiedAt
        saveActionLedgerToDisk()
    }

    func generateActionLedgerSummary(
        maxItems: Int,
        focusedSelection: SupervisorFocusedProjectSelection? = nil
    ) -> String {
        let items = actionLedgerEntriesForPrompt(focusedSelection: focusedSelection)
        guard !items.isEmpty else { return "" }
        return items.suffix(maxItems).map { item in
            let target: String
            if let name = item.projectName, !name.isEmpty {
                target = name
            } else if let pid = item.projectId, !pid.isEmpty {
                target = "project_ref:\(compactSupervisorIdentifier(pid, fallback: "project"))"
            } else {
                target = sanitizeSupervisorPromptIdentifiers(item.targetRef)
            }
            let model = (item.modelId ?? "").isEmpty ? "-" : (item.modelId ?? "-")
            return "- \(item.action) target=\(target) role=\(item.role ?? "-") model=\(model) status=\(item.status) reason=\(item.reasonCode)"
        }.joined(separator: "\n")
    }

    private func sanitizeSupervisorOutboundPrompt(_ text: String) -> String {
        sanitizeSupervisorPromptIdentifiers(text)
    }

    func sanitizeSupervisorPromptIdentifiers(_ text: String) -> String {
        var output = text
        output = replaceSupervisorPromptPattern(
            output,
            pattern: #"(?i)\b([0-9a-f]{8})-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b"#,
            template: "id:$1"
        )
        output = replaceSupervisorPromptPattern(
            output,
            pattern: #"(?i)\b([0-9a-f]{8})[0-9a-f]{24,120}\b"#,
            template: "hex:$1"
        )
        return output
    }

    private func replaceSupervisorPromptPattern(
        _ text: String,
        pattern: String,
        template: String
    ) -> String {
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else {
            return text
        }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        return regex.stringByReplacingMatches(in: text, options: [], range: range, withTemplate: template)
    }

    private func compactSupervisorIdentifier(_ raw: String, fallback: String) -> String {
        let cleaned = raw
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard !cleaned.isEmpty else { return fallback }
        let compact = cleaned.filter { $0.isLetter || $0.isNumber }
        guard !compact.isEmpty else { return fallback }
        return String(compact.prefix(8))
    }

    private func loadActionLedgerFromDisk() {
        let url = actionLedgerURL()
        guard let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode([SupervisorActionLedgerEntry].self, from: data) else {
            return
        }
        actionLedger = Array(decoded.suffix(actionLedgerMaxEntries))
    }

    private func saveActionLedgerToDisk() {
        guard persistSupervisorRuntimeState else { return }
        let url = actionLedgerURL()
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        guard let data = try? encoder.encode(actionLedger) else { return }
        do {
            try SupervisorStoreWriteSupport.writeSnapshotData(data, to: url)
        } catch {
            // Best effort only; failure should not block Supervisor flows.
        }
    }

    private func applyProjectNotificationCenterState(
        _ state: SupervisorProjectNotificationCenterState,
        now: Date = Date()
    ) {
        let normalized = state.normalized(now: now)
        guard normalized != supervisorProjectNotificationCenterState else { return }
        supervisorProjectNotificationCenterState = normalized
        saveRuntimeStateToDisk()
    }

    private func loadRuntimeStateFromDisk() {
        let url = supervisorRuntimeStateURL()
        guard let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(SupervisorRuntimeState.self, from: data) else {
            return
        }
        lastHeartbeatRouteAttentionAlertToken = decoded.lastHeartbeatRouteAttentionAlertToken
            .trimmingCharacters(in: .whitespacesAndNewlines)
        lastHeartbeatRouteAttentionAlertAt = max(0, decoded.lastHeartbeatRouteAttentionAlertAt)
        supervisorFocusPointerState = (decoded.focusPointerState ?? .empty).normalized()
        supervisorProjectNotificationCenterState = (
            decoded.notificationCenterState ?? .empty
        ).normalized()
    }

    private func saveRuntimeStateToDisk() {
        guard persistSupervisorRuntimeState else { return }
        let url = supervisorRuntimeStateURL()
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let notificationCenterState = supervisorProjectNotificationCenterState.normalized()
        let state = SupervisorRuntimeState(
            schemaVersion: SupervisorRuntimeState.currentSchemaVersion,
            lastHeartbeatRouteAttentionAlertToken: lastHeartbeatRouteAttentionAlertToken,
            lastHeartbeatRouteAttentionAlertAt: lastHeartbeatRouteAttentionAlertAt,
            focusPointerState: supervisorFocusPointerState.normalized(),
            notificationCenterState: notificationCenterState
        )
        guard let data = try? encoder.encode(state) else { return }
        do {
            try SupervisorStoreWriteSupport.writeSnapshotData(data, to: url)
        } catch {
            // Best effort only; failure should not block Supervisor flows.
        }
    }

    private func supervisorRuntimeStateURL() -> URL {
        AXProjectRegistryStore.baseDir()
            .appendingPathComponent("supervisor", isDirectory: true)
            .appendingPathComponent("runtime_state.json")
    }

    private func heartbeatRouteAttentionAlertProjectId(
        _ alertToken: String
    ) -> String {
        let normalized = alertToken.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return "" }
        return normalized
            .split(separator: "|", maxSplits: 1, omittingEmptySubsequences: false)
            .first
            .map(String.init)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    }

    func updateHeartbeatRouteAttentionAlertState(
        token: String,
        at: TimeInterval
    ) {
        let normalizedToken = token.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedAt = max(0, at)
        guard normalizedToken != lastHeartbeatRouteAttentionAlertToken ||
                normalizedAt != lastHeartbeatRouteAttentionAlertAt else {
            return
        }
        lastHeartbeatRouteAttentionAlertToken = normalizedToken
        lastHeartbeatRouteAttentionAlertAt = normalizedAt
        saveRuntimeStateToDisk()
    }

    func routeAttentionReminderStatus(
        for item: AXRouteRepairProjectWatchItem,
        now: Date = Date()
    ) -> RouteAttentionReminderStatus {
        let alertToken = heartbeatRouteAttentionAlertToken(item)
        let lastAlertAt = lastHeartbeatRouteAttentionAlertAt > 0 ? lastHeartbeatRouteAttentionAlertAt : nil
        let matchesCurrentIssue = !alertToken.isEmpty &&
            alertToken == lastHeartbeatRouteAttentionAlertToken
        let cooldownRemainingSec: Int
        if matchesCurrentIssue, let lastAlertAt {
            let remaining = heartbeatRouteAttentionReminderCooldownSec - max(0, now.timeIntervalSince1970 - lastAlertAt)
            cooldownRemainingSec = max(0, Int(ceil(remaining)))
        } else {
            cooldownRemainingSec = 0
        }
        return RouteAttentionReminderStatus(
            lastAlertAt: matchesCurrentIssue ? lastAlertAt : nil,
            quietingCurrentIssue: matchesCurrentIssue && cooldownRemainingSec > 0,
            cooldownRemainingSec: cooldownRemainingSec
        )
    }

    func clearRouteAttentionReminderState(
        projectId: String? = nil
    ) {
        let normalizedProjectId = projectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !normalizedProjectId.isEmpty {
            let alertedProjectId = heartbeatRouteAttentionAlertProjectId(lastHeartbeatRouteAttentionAlertToken)
            guard alertedProjectId == normalizedProjectId else { return }
        }
        updateHeartbeatRouteAttentionAlertState(token: "", at: 0)
    }

    private func actionLedgerURL() -> URL {
        AXProjectRegistryStore.baseDir()
            .appendingPathComponent("supervisor", isDirectory: true)
            .appendingPathComponent("action_ledger.json")
    }

    private func loadEscalationPolicyFromDefaults() {
        let defaults = UserDefaults.standard

        let savedThreshold: Int = {
            guard defaults.object(forKey: escalationThresholdDefaultsKey) != nil else {
                if defaults.object(forKey: legacyEscalationThresholdDefaultsKey) != nil {
                    let legacy = defaults.integer(forKey: legacyEscalationThresholdDefaultsKey)
                    defaults.set(legacy, forKey: escalationThresholdDefaultsKey)
                    return legacy
                }
                return Self.defaultsThreshold
            }
            return defaults.integer(forKey: escalationThresholdDefaultsKey)
        }()
        let savedCooldownMinutes: Int = {
            guard defaults.object(forKey: escalationCooldownMinutesDefaultsKey) != nil else {
                if defaults.object(forKey: legacyEscalationCooldownMinutesDefaultsKey) != nil {
                    let legacy = defaults.integer(forKey: legacyEscalationCooldownMinutesDefaultsKey)
                    defaults.set(legacy, forKey: escalationCooldownMinutesDefaultsKey)
                    return legacy
                }
                return Self.defaultsCooldownMinutes
            }
            return defaults.integer(forKey: escalationCooldownMinutesDefaultsKey)
        }()

        blockerEscalationThreshold = normalizedEscalationThreshold(savedThreshold)
        blockerEscalationCooldownSec = Double(normalizedEscalationCooldownMinutes(savedCooldownMinutes)) * 60.0
    }

    private func normalizedEscalationThreshold(_ value: Int) -> Int {
        min(max(1, value), 20)
    }

    private func normalizedEscalationCooldownMinutes(_ value: Int) -> Int {
        min(max(1, value), 240)
    }

    private func restartHeartbeatTimer() {
        heartbeatTimer?.invalidate()
        heartbeatTimer = Timer.scheduledTimer(withTimeInterval: heartbeatIntervalSec, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.emitHeartbeatIfNeeded(force: false, reason: "timer")
            }
        }
        RunLoop.main.add(heartbeatTimer!, forMode: .common)
    }

    func supervisorCandidateReviewProjectIDs(
        _ item: HubIPCClient.SupervisorCandidateReviewItem
    ) -> [String] {
        var ids = [item.projectId] + item.projectIds
        ids = ids
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        var deduped: [String] = []
        var seen = Set<String>()
        for id in ids where seen.insert(id).inserted {
            deduped.append(id)
        }
        return deduped
    }

    func rebuildPendingHubGrantViewState(now: TimeInterval) {
        let previousGrants = pendingHubGrants
        let projects = knownProjects()
        let nextFreshSnapshot = hasFreshPendingGrantSnapshot(now: now)
        if hasFreshPendingHubGrantSnapshot != nextFreshSnapshot {
            hasFreshPendingHubGrantSnapshot = nextFreshSnapshot
        }

        if let snapshot = pendingGrantSnapshot {
            let nextGrants = normalizedPendingHubGrants(
                projects: projects,
                allowStaleSnapshot: false,
                now: now
            )
            if pendingHubGrants != nextGrants {
                pendingHubGrants = nextGrants
            }
            let nextSource = snapshot.source.trimmingCharacters(in: .whitespacesAndNewlines)
            if pendingHubGrantSource != nextSource {
                pendingHubGrantSource = nextSource
            }
            let updatedAtSec = snapshot.updatedAtMs > 0 ? snapshot.updatedAtMs / 1000.0 : pendingGrantLastSuccessAt
            let nextUpdatedAt = max(0, updatedAtSec)
            if pendingHubGrantUpdatedAt != nextUpdatedAt {
                pendingHubGrantUpdatedAt = nextUpdatedAt
            }
        } else {
            if pendingHubGrantSource != "" {
                pendingHubGrantSource = ""
            }
            if pendingHubGrantUpdatedAt != 0 {
                pendingHubGrantUpdatedAt = 0
            }
            if !pendingHubGrants.isEmpty {
                pendingHubGrants = []
            }
        }

        if pendingHubGrantActionsInFlight.isEmpty {
            updatePendingHubGrantVoiceAnnouncementState(
                previousGrants: previousGrants,
                now: now
            )
            return
        }
        let activeGrantIds = Set(pendingHubGrants.map(\.grantRequestId))
        let nextActionsInFlight = Set(pendingHubGrantActionsInFlight.filter { activeGrantIds.contains($0) })
        if pendingHubGrantActionsInFlight != nextActionsInFlight {
            pendingHubGrantActionsInFlight = nextActionsInFlight
        }
        updatePendingHubGrantVoiceAnnouncementState(
            previousGrants: previousGrants,
            now: now
        )
    }

    func rebuildSupervisorCandidateReviewViewState(now: TimeInterval) {
        let nextFreshSnapshot = hasFreshSupervisorCandidateReviewSnapshot(now: now)
        if hasFreshSupervisorCandidateReviewSnapshot != nextFreshSnapshot {
            hasFreshSupervisorCandidateReviewSnapshot = nextFreshSnapshot
        }

        if let snapshot = supervisorCandidateReviewSnapshot {
            let nextReviews = normalizedSupervisorCandidateReviews(snapshot.items)
            if supervisorCandidateReviews != nextReviews {
                supervisorCandidateReviews = nextReviews
            }
            let nextSource = snapshot.source.trimmingCharacters(in: .whitespacesAndNewlines)
            if supervisorCandidateReviewSource != nextSource {
                supervisorCandidateReviewSource = nextSource
            }
            let updatedAtSec = snapshot.updatedAtMs > 0
                ? snapshot.updatedAtMs / 1000.0
                : supervisorCandidateReviewLastSuccessAt
            let nextUpdatedAt = max(0, updatedAtSec)
            if supervisorCandidateReviewUpdatedAt != nextUpdatedAt {
                supervisorCandidateReviewUpdatedAt = nextUpdatedAt
            }
        } else {
            if !supervisorCandidateReviews.isEmpty {
                supervisorCandidateReviews = []
            }
            if supervisorCandidateReviewSource != "" {
                supervisorCandidateReviewSource = ""
            }
            if supervisorCandidateReviewUpdatedAt != 0 {
                supervisorCandidateReviewUpdatedAt = 0
            }
        }

        if supervisorCandidateReviewActionsInFlight.isEmpty {
            return
        }

        let activeRequestIds = Set(
            supervisorCandidateReviews.map { $0.requestId.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
        )
        let nextActionsInFlight = Set(supervisorCandidateReviewActionsInFlight.filter { activeRequestIds.contains($0) })
        if supervisorCandidateReviewActionsInFlight != nextActionsInFlight {
            supervisorCandidateReviewActionsInFlight = nextActionsInFlight
        }
    }

    private func updatePendingHubGrantVoiceAnnouncementState(
        previousGrants: [SupervisorPendingGrant],
        now: TimeInterval
    ) {
        let currentVisibleGrants = frontstagePendingHubGrants
        let previousVisibleGrants = previousGrants.filter { grant in
            projectVisibleInCurrentSupervisorJurisdictionOrUnknown(
                projectId: grant.projectId,
                projectName: grant.projectName
            )
        }
        let currentTokens = Set(currentVisibleGrants.map(pendingGrantStableToken))
        pendingHubGrantAnnouncementBacklog = pendingHubGrantAnnouncementBacklog.filter { currentTokens.contains($0.key) }
        if !currentTokens.contains(lastPendingHubGrantVoiceContextToken) {
            lastPendingHubGrantVoiceContextToken = ""
            lastPendingHubGrantVoiceContextAt = 0
        }

        guard hasFreshPendingHubGrantSnapshot else { return }

        let previousTokens = Set(previousVisibleGrants.map(pendingGrantStableToken))
        if !hasObservedPendingHubGrantSnapshot {
            hasObservedPendingHubGrantSnapshot = true
            return
        }

        for grant in currentVisibleGrants {
            let token = pendingGrantStableToken(grant)
            guard !previousTokens.contains(token) else { continue }
            pendingHubGrantAnnouncementBacklog[token] = grant
        }

        flushPendingHubGrantVoiceAnnouncementBacklogIfNeeded(now: now)
    }

    private func flushPendingHubGrantVoiceAnnouncementBacklogIfNeeded(
        now: TimeInterval = Date().timeIntervalSince1970
    ) {
        guard !pendingHubGrantAnnouncementBacklog.isEmpty else { return }
        guard conversationSessionController.snapshot.wakeMode != .pushToTalk else { return }
        guard voiceRouteDecision.route.supportsLiveCapture else { return }
        guard !isProcessing else { return }
        suspendWakeArmedCaptureIfNeeded(reasonCode: "pending_grant_announcement")
        guard !voiceSessionCoordinator.isRecording else { return }
        guard activeVoiceChallenge == nil else { return }
        guard activeVoicePendingGrantAction == nil else { return }
        guard !voiceAuthorizationInFlight else { return }

        let frontstageGrants = frontstagePendingHubGrants
        guard let grant = frontstageGrants.first(where: {
            pendingHubGrantAnnouncementBacklog[pendingGrantStableToken($0)] != nil
        }) else {
            return
        }

        let token = pendingGrantStableToken(grant)
        pendingHubGrantAnnouncementBacklog.removeValue(forKey: token)

        let announcement = buildPendingHubGrantVoiceAnnouncement(
            grant: grant,
            pendingCount: frontstageGrants.count,
            now: now
        )
        let spokenOutcome = dispatchSupervisorVoiceJob(
            announcement.job,
            preferences: currentVoicePreferences(),
            source: "pending_grant_arrival",
            now: Date(timeIntervalSince1970: now),
            suppressRapidSameSourceRepeat: true,
            cancelPendingHeartbeat: true
        )
        guard spokenOutcome == .spoken else {
            appendRecentEvent("pending hub grant voice alert suppressed: \(token)")
            return
        }

        rememberPendingHubGrantVoiceContext(grant, now: now)
        completeSupervisorAssistantTurn(
            SupervisorAfterTurnLifecycleContext(
                userMessage: "",
                responseText: announcement.text,
                triggerSource: .grantResolution,
                triggeredByVoice: false,
                spokenOutcome: spokenOutcome,
                replySource: "pending_grant_arrival",
                personaSlot: nil,
                allowProactiveResume: true,
                lifecycle: .nonReviewAssistantReply
            )
        )
        conversationWindowBridge.requestOpen(
            reason: "pending_hub_grant:\(grant.projectId)",
            focusConversation: false
        )
        appendRecentEvent("pending hub grant voice alert delivered: \(token)")
    }

    private func buildPendingHubGrantVoiceAnnouncement(
        grant: SupervisorPendingGrant,
        pendingCount: Int,
        now: TimeInterval = Date().timeIntervalSince1970
    ) -> (text: String, job: SupervisorVoiceTTSJob) {
        let capabilityText = grantCapabilityText(
            capability: grant.capability,
            modelId: grant.modelId
        )
        let scopeText = pendingGrantScopeText(grant)
        let reasonText = pendingGrantReasonText(grant)
        let token = pendingGrantStableToken(grant)
        let ingressContext = pendingGrantIngressContext(for: grant, now: now)

        var lines: [String] = []
        if pendingCount > 1 {
            lines.append("🛂 当前共有 \(pendingCount) 笔待处理的 Hub 授权，我先报最紧急的一笔。")
        } else {
            lines.append("🛂 检测到新的 Hub 授权。")
        }
        lines.append("《\(grant.projectName)》现在需要处理一笔 \(capabilityText) 授权。")
        if let ingressContext {
            lines.append("来源：\(ingressContext.provider) / \(ingressContext.ingress)")
        }
        if let scopeText {
            lines.append(scopeText)
        }
        if let reasonText {
            lines.append("原因：\(capped(reasonText, maxChars: 96))")
        }
        lines.append("直接说“批准这笔授权”或“拒绝这笔授权”即可。")
        lines.append(userFacingGrantIdentifier(token))

        let text = lines.joined(separator: "\n")
        let script = heartbeatScriptPrefixedWithMemoryReadiness(
            SupervisorVoiceScriptBuilder.pendingGrantAnnouncementScript(
                pendingCount: pendingCount,
                projectName: grant.projectName,
                capabilitySummary: capabilityText,
                scopeSummary: scopeText,
                reasonSummary: reasonText.map { capped($0, maxChars: 56) },
                sourceSummary: ingressContext.map { "\($0.provider) 的\($0.ingress)" }
            )
        )
        let job = SupervisorVoiceTTSJob(
            trigger: .authorization,
            priority: .normal,
            script: script,
            dedupeKey: "pending_grant_arrival:\(token)"
        )
        return (text: text, job: job)
    }

    private func rememberPendingHubGrantVoiceContext(
        _ grant: SupervisorPendingGrant,
        now: TimeInterval = Date().timeIntervalSince1970
    ) {
        lastPendingHubGrantVoiceContextToken = pendingGrantStableToken(grant)
        lastPendingHubGrantVoiceContextAt = now
    }

    private func updatePendingSupervisorSkillApprovalVoiceAnnouncementState(
        previousApprovals: [SupervisorPendingSkillApproval],
        now: TimeInterval
    ) {
        let currentVisibleApprovals = frontstagePendingSupervisorSkillApprovals
        let previousVisibleApprovals = previousApprovals.filter { approval in
            projectVisibleInCurrentSupervisorJurisdictionOrUnknown(
                projectId: approval.projectId,
                projectName: approval.projectName
            )
        }
        let currentTokens = Set(currentVisibleApprovals.map(pendingSupervisorSkillApprovalStableToken))
        pendingSupervisorSkillApprovalAnnouncementBacklog =
            pendingSupervisorSkillApprovalAnnouncementBacklog.filter { currentTokens.contains($0.key) }
        if !currentTokens.contains(lastPendingSupervisorSkillApprovalVoiceContextToken) {
            lastPendingSupervisorSkillApprovalVoiceContextToken = ""
            lastPendingSupervisorSkillApprovalVoiceContextAt = 0
        }

        let previousTokens = Set(previousVisibleApprovals.map(pendingSupervisorSkillApprovalStableToken))
        if !hasObservedPendingSupervisorSkillApprovalState {
            hasObservedPendingSupervisorSkillApprovalState = true
            return
        }

        for approval in currentVisibleApprovals {
            let token = pendingSupervisorSkillApprovalStableToken(approval)
            guard !previousTokens.contains(token) else { continue }
            pendingSupervisorSkillApprovalAnnouncementBacklog[token] = approval
        }

        flushPendingSupervisorSkillApprovalVoiceAnnouncementBacklogIfNeeded(now: now)
    }

    private func flushPendingSupervisorSkillApprovalVoiceAnnouncementBacklogIfNeeded(
        now: TimeInterval = Date().timeIntervalSince1970
    ) {
        guard !pendingSupervisorSkillApprovalAnnouncementBacklog.isEmpty else { return }
        guard pendingHubGrantAnnouncementBacklog.isEmpty else { return }
        guard !hasActivePendingSupervisorSkillApprovalVoiceContext(now: now) else { return }
        guard conversationSessionController.snapshot.wakeMode != .pushToTalk else { return }
        guard voiceRouteDecision.route.supportsLiveCapture else { return }
        guard !isProcessing else { return }
        suspendWakeArmedCaptureIfNeeded(reasonCode: "pending_skill_approval_announcement")
        guard !voiceSessionCoordinator.isRecording else { return }
        guard activeVoiceChallenge == nil else { return }
        guard activeVoicePendingGrantAction == nil else { return }
        guard !voiceAuthorizationInFlight else { return }

        let frontstageApprovals = frontstagePendingSupervisorSkillApprovals
        guard let approval = frontstageApprovals.first(where: {
            pendingSupervisorSkillApprovalAnnouncementBacklog[pendingSupervisorSkillApprovalStableToken($0)] != nil
        }) else {
            return
        }

        let token = pendingSupervisorSkillApprovalStableToken(approval)
        pendingSupervisorSkillApprovalAnnouncementBacklog.removeValue(forKey: token)

        let announcement = buildPendingSupervisorSkillApprovalVoiceAnnouncement(
            approval: approval,
            pendingCount: frontstageApprovals.count
        )
        let spokenOutcome = dispatchSupervisorVoiceJob(
            announcement.job,
            preferences: currentVoicePreferences(),
            source: "pending_skill_approval_arrival",
            now: Date(timeIntervalSince1970: now),
            suppressRapidSameSourceRepeat: true,
            cancelPendingHeartbeat: true
        )
        guard spokenOutcome == .spoken else {
            appendRecentEvent("pending supervisor skill approval voice alert suppressed: \(token)")
            return
        }

        rememberPendingSupervisorSkillApprovalVoiceContext(approval, now: now)
        completeSupervisorAssistantTurn(
            SupervisorAfterTurnLifecycleContext(
                userMessage: "",
                responseText: announcement.text,
                triggerSource: .approvalResolution,
                triggeredByVoice: false,
                spokenOutcome: spokenOutcome,
                replySource: "pending_local_skill_approval_arrival",
                personaSlot: nil,
                allowProactiveResume: true,
                lifecycle: .nonReviewAssistantReply
            )
        )
        conversationWindowBridge.requestOpen(
            reason: "pending_local_skill_approval:\(approval.projectId)",
            focusConversation: false
        )
        appendRecentEvent("pending supervisor skill approval voice alert delivered: \(token)")
    }

    private func buildPendingSupervisorSkillApprovalVoiceAnnouncement(
        approval: SupervisorPendingSkillApproval,
        pendingCount: Int
    ) -> (text: String, job: SupervisorVoiceTTSJob) {
        let toolSummary = approval.toolSummary.trimmingCharacters(in: .whitespacesAndNewlines)
        let reasonSummary = approval.reason.trimmingCharacters(in: .whitespacesAndNewlines)
        let skillSummary = supervisorPendingApprovalDisplaySummary(approval)
        let routingNarrative = SupervisorSkillActivityPresentation.routingNarrative(
            requestedSkillId: approval.requestedSkillId,
            effectiveSkillId: approval.skillId,
            routingReasonCode: approval.routingReasonCode,
            routingExplanation: approval.routingExplanation
        )?.trimmingCharacters(in: .whitespacesAndNewlines)
        let mode = pendingSupervisorSkillAuthorizationMode(for: approval)
        let summaryLabel = pendingSupervisorSkillSummaryLabel(for: mode)
        var lines: [String] = []
        if pendingCount > 1 {
            lines.append("🛂 当前有 \(pendingCount) 条待处理的\(summaryLabel)，我先报最早的一条。")
        } else {
            switch mode {
            case .localApproval:
                lines.append("🛂 检测到新的本地技能调用待审批。")
            case .hubGrant:
                lines.append("🛂 检测到新的技能授权待处理。")
            case .blocked:
                lines.append("🛂 检测到新的技能治理阻塞待处理。")
            }
        }
        lines.append("《\(approval.projectName)》现在有一条待处理的\(summaryLabel)：\(skillSummary)。")
        if let routingNarrative, !routingNarrative.isEmpty {
            lines.append("路由说明：\(capped(routingNarrative, maxChars: 96))")
        }
        if !toolSummary.isEmpty {
            lines.append("目标：\(capped(toolSummary, maxChars: 96))")
        }
        if !reasonSummary.isEmpty {
            lines.append("原因：\(capped(reasonSummary, maxChars: 96))")
        }
        lines.append(pendingSupervisorSkillVoiceActionHint(for: mode))
        lines.append(userFacingRequestIdentifier(approval.requestId))

        let text = lines.joined(separator: "\n")
        let script = heartbeatScriptPrefixedWithMemoryReadiness(
            SupervisorVoiceScriptBuilder.pendingSkillApprovalAnnouncementScript(
                pendingCount: pendingCount,
                authorizationMode: mode,
                projectName: approval.projectName,
                skillSummary: skillSummary,
                routingSummary: routingNarrative,
                toolSummary: toolSummary.isEmpty ? nil : capped(toolSummary, maxChars: 56),
                reasonSummary: reasonSummary.isEmpty ? nil : capped(reasonSummary, maxChars: 56)
            )
        )
        let job = SupervisorVoiceTTSJob(
            trigger: .authorization,
            priority: .normal,
            script: script,
            dedupeKey: "pending_skill_approval_arrival:\(pendingSupervisorSkillApprovalStableToken(approval))"
        )
        return (text: text, job: job)
    }

    private func rememberPendingSupervisorSkillApprovalVoiceContext(
        _ approval: SupervisorPendingSkillApproval,
        now: TimeInterval = Date().timeIntervalSince1970
    ) {
        lastPendingSupervisorSkillApprovalVoiceContextToken =
            pendingSupervisorSkillApprovalStableToken(approval)
        lastPendingSupervisorSkillApprovalVoiceContextAt = now
    }

    private func hasActivePendingSupervisorSkillApprovalVoiceContext(
        now: TimeInterval = Date().timeIntervalSince1970
    ) -> Bool {
        let token = lastPendingSupervisorSkillApprovalVoiceContextToken
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !token.isEmpty else { return false }
        guard now - lastPendingSupervisorSkillApprovalVoiceContextAt <=
            supervisorEllipsisContextCarryWindowSec else {
            return false
        }
        return pendingSupervisorSkillApprovals.contains {
            pendingSupervisorSkillApprovalStableToken($0) == token
        }
    }

