    func latestConnectorIngressReceipt(
        for grant: SupervisorPendingGrant,
        now: TimeInterval
    ) -> HubIPCClient.ConnectorIngressReceipt? {
        guard let snapshot = connectorIngressSnapshot else { return nil }
        let snapshotUpdatedAtSec = snapshot.updatedAtMs > 0
            ? snapshot.updatedAtMs / 1000.0
            : connectorIngressLastSuccessAt
        guard snapshotUpdatedAtSec > 0, now - snapshotUpdatedAtSec <= schedulerSnapshotStaleSec else {
            return nil
        }

        let projectId = grant.projectId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !projectId.isEmpty else { return nil }

        return snapshot.items.filter { receipt in
            receipt.projectId.trimmingCharacters(in: .whitespacesAndNewlines) == projectId
                && now - (max(0, receipt.receivedAtMs) / 1000.0) <= 180
        }
        .sorted { lhs, rhs in
            if lhs.receivedAtMs != rhs.receivedAtMs {
                return lhs.receivedAtMs > rhs.receivedAtMs
            }
            return lhs.eventSequence > rhs.eventSequence
        }
        .first
    }

    func pendingGrantIngressContext(
        for grant: SupervisorPendingGrant,
        now: TimeInterval
    ) -> PendingGrantIngressContext? {
        guard let receipt = latestConnectorIngressReceipt(for: grant, now: now) else {
            return nil
        }
        return PendingGrantIngressContext(
            provider: remoteChannelProviderDisplayName(receipt.connector),
            ingress: hubConnectorIngressDisplayName(
                receipt,
                triggerType: hubConnectorIngressTriggerType(for: receipt)
            ),
            receiptId: receipt.receiptId
        )
    }

    func rebuildPendingSupervisorSkillApprovalViewState(
        force: Bool = true,
        reason: String = "direct",
        now: TimeInterval = Date().timeIntervalSince1970
    ) {
        if !force,
           supervisorSkillViewStateLastFingerprintCheckAt > 0,
           now - supervisorSkillViewStateLastFingerprintCheckAt < supervisorSkillViewStateFingerprintMinIntervalSec {
            XTPerformanceTrace.event(
                "XT Supervisor Skill View State Rebuild Coalesced",
                "reason=\(reason)"
            )
            return
        }
        supervisorSkillViewStateLastFingerprintCheckAt = now

        let projects = knownProjects()
        let inputFingerprint = supervisorSkillViewStateInputFingerprint(projects: projects)
        if !force,
           supervisorSkillViewStateLastRebuildAt > 0,
           inputFingerprint == lastSupervisorSkillViewStateInputFingerprint,
           now - supervisorSkillViewStateLastRebuildAt < supervisorSkillViewStatePollStaleRefreshSec {
            XTPerformanceTrace.event(
                "XT Supervisor Skill View State Rebuild Skipped",
                "reason=\(reason)"
            )
            return
        }

        let previousApprovals = pendingSupervisorSkillApprovals
        refreshResolvedSkillsCacheSynchronouslyForSkillViewState(projects: projects)
        let nextApprovals = normalizedPendingSupervisorSkillApprovals(projects: projects)
        let nextActivities = normalizedRecentSupervisorSkillActivities(projects: projects)
        let approvalsChanged = pendingSupervisorSkillApprovals != nextApprovals

        if approvalsChanged {
            pendingSupervisorSkillApprovals = nextApprovals
        }
        if recentSupervisorSkillActivities != nextActivities {
            recentSupervisorSkillActivities = nextActivities
        }

        lastSupervisorSkillViewStateInputFingerprint = inputFingerprint
        supervisorSkillViewStateLastRebuildAt = now

        if approvalsChanged || force {
            updatePendingSupervisorSkillApprovalVoiceAnnouncementState(
                previousApprovals: previousApprovals,
                now: now
            )
        }
        XTPerformanceTrace.event(
            "XT Supervisor Skill View State Rebuilt",
            "reason=\(reason) approvals=\(nextApprovals.count) activities=\(nextActivities.count)"
        )
    }

