        focusedProjectId: String? = nil,
        focusedProjectName: String? = nil
    ) {
        let normalizedProjectId = focusedProjectId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedProjectName = focusedProjectName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let routingDecision: SupervisorTurnRoutingDecision? =
            (normalizedProjectId?.isEmpty == false || normalizedProjectName?.isEmpty == false)
            ? SupervisorTurnRoutingDecision(
                mode: .projectFirst,
                focusedProjectId: normalizedProjectId,
                focusedProjectName: normalizedProjectName,
                focusedPersonName: nil,
                focusedCommitmentId: nil,
                confidence: 1,
                routingReasons: ["test_scope"]
            )
            : nil
        completeSupervisorAssistantTurn(
            SupervisorAfterTurnLifecycleContext(
                userMessage: userMessage,
                responseText: responseText,
                triggerSource: SupervisorCommandTriggerSource.parse(triggerSource),
                triggeredByVoice: false,
                spokenOutcome: .suppressed("testing"),
                replySource: "testing",
                personaSlot: nil,
                turnRoutingDecision: routingDecision,
                lifecycle: .backgroundAssistantReply
            )
        )
    }

