    func applySupervisorRemotePromptVariantForTesting(
        label: String,
        memoryText: String,
        promptMode: SupervisorSystemPromptMode = .minimal,
        promptTokenEstimate: Int = 400,
        maxTokens: Int = 512,
        totalTokenEstimate: Int? = nil,
        singleRequestBudgetTokens: Int = 12_000,
        singleRequestBudgetSource: String = "testing"
    ) -> SupervisorMemoryAssemblySnapshot? {
        let servingContract = supervisorMemoryAssemblySnapshot?.servingObjectContract ?? []
        let actualSectionSelection = supervisorActualSectionSelection(
            in: memoryText,
            contract: servingContract
        )
        let baseContextRefsSelected = supervisorMemoryAssemblySnapshot?.contextRefsSelected ?? 0
        let baseContextRefsOmitted = supervisorMemoryAssemblySnapshot?.contextRefsOmitted ?? 0
        let totalContextRefs = baseContextRefsSelected + baseContextRefsOmitted
        let baseEvidenceItemsSelected = supervisorMemoryAssemblySnapshot?.evidenceItemsSelected ?? 0
        let baseEvidenceItemsOmitted = supervisorMemoryAssemblySnapshot?.evidenceItemsOmitted ?? 0
        let totalEvidenceItems = baseEvidenceItemsSelected + baseEvidenceItemsOmitted
        let variant = SupervisorRemotePromptVariant(
            label: label,
            prompt: "",
            promptMode: promptMode,
            maxTokens: maxTokens,
            promptTokenEstimate: promptTokenEstimate,
            totalTokenEstimate: totalTokenEstimate ?? (promptTokenEstimate + max(0, maxTokens)),
            selectedSections: actualSectionSelection.selected,
            omittedSections: actualSectionSelection.omitted,
            contextRefsSelected: actualSectionSelection.selected.contains("context_refs")
                ? baseContextRefsSelected
                : 0,
            contextRefsOmitted: actualSectionSelection.selected.contains("context_refs")
                ? baseContextRefsOmitted
                : totalContextRefs,
            evidenceItemsSelected: actualSectionSelection.selected.contains("evidence_pack")
                ? baseEvidenceItemsSelected
                : 0,
            evidenceItemsOmitted: actualSectionSelection.selected.contains("evidence_pack")
                ? baseEvidenceItemsOmitted
                : totalEvidenceItems
        )
        syncSupervisorMemoryAssemblySnapshotRemotePromptVariant(
            variant,
            singleRequestBudgetTokens: singleRequestBudgetTokens,
            singleRequestBudgetSource: singleRequestBudgetSource
        )
        return supervisorMemoryAssemblySnapshot
    }

