    private func prepareConversationStreamingAssistantMessageIfNeeded() -> String? {
        guard isProcessing else { return nil }
        if let activeConversationStreamingMessageID,
           messages.contains(where: { $0.id == activeConversationStreamingMessageID }) {
            return activeConversationStreamingMessageID
        }

        let message = SupervisorMessage(
            id: UUID().uuidString,
            role: .assistant,
            content: "",
            isVoice: false,
            timestamp: Date().timeIntervalSince1970
        )
        messages.append(message)
        activeConversationStreamingMessageID = message.id
        return message.id
    }

