    private func refreshVoiceReadinessSnapshot() {
        guard let appModel else {
            voiceReadinessSnapshot = .empty
            voiceCallEntryPreflight = nil
            return
        }

        let session = currentVoiceReadinessSession()
        voiceReadinessSnapshot = buildVoiceReadinessSnapshot(
            appModel: appModel,
            session: session
        )
        refreshVoiceCallEntryPreflight()
    }

    private func refreshVoiceCallEntryPreflight(
        workspaceRoot: URL? = nil
    ) {
        voiceCallEntryPreflight = makeVoiceCallEntryPreflight(workspaceRoot: workspaceRoot)
    }

    private func makeVoiceCallEntryPreflight(
        workspaceRoot: URL? = nil
    ) -> SupervisorVoiceCallEntryPreflight? {
        let resolvedWorkspaceRoot = workspaceRoot ?? effectiveVoiceCallEntryWorkspaceRoot()
        let snapshot = voiceReadinessSnapshotOverrideForTesting ?? voiceReadinessSnapshot
        return buildVoiceCallEntryPreflight(
            workspaceRoot: resolvedWorkspaceRoot,
            readinessSnapshot: snapshot
        )
    }

    private func effectiveVoiceCallEntryWorkspaceRoot() -> URL {
        voiceCallEntryWorkspaceRootOverrideForTesting ?? XTUnifiedDoctorStore.workspaceRootFromEnvOrCWD()
    }

    private func currentVoiceReadinessSession() -> AXSessionInfo? {
        guard let appModel else { return nil }
        if let selectedProjectId = appModel.selectedProjectId,
           selectedProjectId != AXProjectRegistry.globalHomeId,
           let session = sessionManager.primarySession(for: selectedProjectId) {
            return session
        }
        if let activeSessionId = sessionManager.activeSessionId,
           let session = sessionManager.session(for: activeSessionId) {
            return session
        }
        var newestSession: AXSessionInfo?
        for session in sessionManager.sessions {
            guard let current = newestSession else {
                newestSession = session
                continue
            }
            if session.updatedAt > current.updatedAt
                || (session.updatedAt == current.updatedAt && session.id < current.id) {
                newestSession = session
            }
        }
        return newestSession
    }

    func startVoiceAuthorization(
        _ request: SupervisorVoiceAuthorizationRequest
    ) async -> SupervisorVoiceAuthorizationResolution {
        guard !voiceAuthorizationInFlight else {
            let resolution = makeVoiceAuthorizationManagerFailureResolution(
                requestId: request.requestId,
                projectId: request.projectId,
                templateId: request.templateId,
                riskTier: request.riskTier,
                reasonCode: "voice_authorization_inflight",
                challenge: activeVoiceChallenge
            )
            let preserveActiveChallengeOnFailClosed = shouldPreserveActiveVoiceAuthorizationStateAfterFailClosed(
                resolution,
                preserveRequested: activeVoiceChallenge != nil
            )
            applyVoiceAuthorizationResolution(
                resolution,
                request: activeVoiceAuthorizationRequest ?? request,
                preserveActiveChallengeOnFailClosed: preserveActiveChallengeOnFailClosed
            )
            finalizeVoicePendingGrantActionContext(
                resolution: resolution,
                request: request,
                forceCancel: false,
                preserveActiveChallengeOnFailClosed: preserveActiveChallengeOnFailClosed
            )
            return resolution
        }

        voiceAuthorizationInFlight = true
        let resolution = await voiceAuthorizationBridge.beginAuthorization(request)
        applyVoiceAuthorizationResolution(
            resolution,
            request: request,
            preserveActiveChallengeOnFailClosed: false
        )
        voiceAuthorizationInFlight = false
        finalizeVoicePendingGrantActionContext(
            resolution: resolution,
            request: request,
            forceCancel: false,
            preserveActiveChallengeOnFailClosed: false
        )
        return resolution
    }

    func confirmVoiceAuthorization(
        _ verification: SupervisorVoiceAuthorizationVerificationInput
    ) async -> SupervisorVoiceAuthorizationResolution {
        guard !voiceAuthorizationInFlight else {
            let resolution = makeVoiceAuthorizationManagerFailureResolution(
                requestId: verification.requestId,
                projectId: activeVoiceAuthorizationRequest?.projectId,
                templateId: activeVoiceAuthorizationRequest?.templateId ?? "voice.grant.v1",
                riskTier: activeVoiceAuthorizationRequest?.riskTier ?? .high,
                reasonCode: "voice_authorization_inflight",
                challenge: activeVoiceChallenge
            )
            let preserveActiveChallengeOnFailClosed = shouldPreserveActiveVoiceAuthorizationStateAfterFailClosed(
                resolution,
                preserveRequested: activeVoiceChallenge != nil
            )
            applyVoiceAuthorizationResolution(
                resolution,
                request: activeVoiceAuthorizationRequest,
                preserveActiveChallengeOnFailClosed: preserveActiveChallengeOnFailClosed
            )
            finalizeVoicePendingGrantActionContext(
                resolution: resolution,
                request: activeVoiceAuthorizationRequest,
                forceCancel: false,
                preserveActiveChallengeOnFailClosed: preserveActiveChallengeOnFailClosed
            )
            return resolution
        }

        guard let request = activeVoiceAuthorizationRequest,
              let challenge = activeVoiceChallenge else {
            let resolution = makeVoiceAuthorizationManagerFailureResolution(
                requestId: verification.requestId,
                projectId: nil,
                templateId: "voice.grant.v1",
                riskTier: .high,
                reasonCode: "voice_authorization_not_started",
                challenge: nil
            )
            applyVoiceAuthorizationResolution(
                resolution,
                request: nil,
                preserveActiveChallengeOnFailClosed: false
            )
            finalizeVoicePendingGrantActionContext(
                resolution: resolution,
                request: nil,
                forceCancel: false,
                preserveActiveChallengeOnFailClosed: false
            )
            return resolution
        }

        voiceAuthorizationInFlight = true
        let resolution = await voiceAuthorizationBridge.verifyAuthorization(
            request: request,
            challenge: challenge,
            verification: verification
        )
        let preserveActiveChallengeOnFailClosed = shouldPreserveActiveVoiceAuthorizationStateAfterFailClosed(
            resolution,
            preserveRequested: activeVoiceChallenge != nil || resolution.challenge != nil
        )
        applyVoiceAuthorizationResolution(
            resolution,
            request: request,
            preserveActiveChallengeOnFailClosed: preserveActiveChallengeOnFailClosed
        )
        await applyVoiceAuthorizationRuntimeSideEffects(
            resolution,
            request: request,
            forceCancel: false
        )
        voiceAuthorizationInFlight = false
        finalizeVoicePendingGrantActionContext(
            resolution: resolution,
            request: request,
            forceCancel: false,
            preserveActiveChallengeOnFailClosed: preserveActiveChallengeOnFailClosed
        )
        return resolution
    }

    func retryVoiceAuthorizationVerification(
        transcript: String,
        semanticMatchScore: Double = 0.99,
        mobileConfirmed: Bool? = nil
    ) async -> SupervisorVoiceAuthorizationResolution {
        let requestId = activeVoiceAuthorizationRequest?.requestId
            ?? voiceAuthorizationResolution?.requestId
            ?? "voice-authorization-retry"
        let normalizedTranscript = transcript.trimmingCharacters(in: .whitespacesAndNewlines)
        let boundDeviceId: String? = {
            let token = activeVoiceChallenge?.boundDeviceId.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            return token.isEmpty ? nil : token
        }()
        let clippedScore = max(0, min(1, semanticMatchScore))
        let effectiveMobileConfirmed = mobileConfirmed ?? voiceAuthorizationMobileConfirmationLatched

        return await confirmVoiceAuthorization(
            SupervisorVoiceAuthorizationVerificationInput(
                requestId: requestId,
                challengeCode: activeVoiceChallenge?.challengeCode,
                transcript: normalizedTranscript.isEmpty ? nil : normalizedTranscript,
                semanticMatchScore: clippedScore,
                actionText: activeVoiceAuthorizationRequest?.actionText ?? "",
                scopeText: activeVoiceAuthorizationRequest?.scopeText ?? "",
                amountText: activeVoiceAuthorizationRequest?.amountText,
                verifyNonce: UUID().uuidString.lowercased(),
                boundDeviceId: boundDeviceId,
                mobileConfirmed: effectiveMobileConfirmed
            )
        )
    }

    func setVoiceAuthorizationMobileConfirmed(
        _ confirmed: Bool,
        source: String,
        emitSystemMessage: Bool = false
    ) {
        let sourceToken = source.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "unspecified"
            : source.trimmingCharacters(in: .whitespacesAndNewlines)
        let changed = voiceAuthorizationMobileConfirmationLatched != confirmed
        if changed {
            voiceAuthorizationMobileConfirmationLatched = confirmed
            let stateText = confirmed ? "latched" : "cleared"
            appendRecentEvent("voice authorization mobile confirmation \(stateText): \(sourceToken)")
            appendVoiceReplayEvent(
                category: .authorization,
                state: confirmed ? .mobileConfirmed : .mobileCleared,
                summary: confirmed ? "移动端确认已记录" : "移动端确认已清除",
                reasonCode: sourceToken,
                metadata: [
                    "challenge_id": activeVoiceChallenge?.challengeId ?? "",
                    "source": sourceToken,
                ]
            )
        }
        guard emitSystemMessage else { return }
        let messageText = confirmed
            ? "已记录移动端确认；现在继续说授权短语即可。"
            : "已清除移动端确认记录。"
        addSystemMessage(messageText)
    }

    func cancelVoiceAuthorization() {
        guard let request = activeVoiceAuthorizationRequest ?? voiceAuthorizationResolution.map({
            SupervisorVoiceAuthorizationRequest(
                requestId: $0.requestId,
                projectId: $0.projectId,
                templateId: $0.templateId,
                actionText: "",
                scopeText: "",
                amountText: nil,
                riskTier: LaneRiskTier(rawValue: $0.riskTier) ?? .high,
                boundDeviceId: activeVoiceChallenge?.boundDeviceId,
                mobileTerminalId: activeVoiceChallenge?.mobileTerminalId,
                challengeCode: activeVoiceChallenge?.challengeCode,
                ttlMs: 120_000
            )
        }) else {
            return
        }

        let resolution = makeVoiceAuthorizationManagerFailureResolution(
            requestId: request.requestId,
            projectId: request.projectId,
            templateId: request.templateId,
            riskTier: request.riskTier,
            reasonCode: "user_cancelled",
            challenge: activeVoiceChallenge
        )
        applyVoiceAuthorizationResolution(
            resolution,
            request: nil,
            preserveActiveChallengeOnFailClosed: false,
            forceCancel: true
        )
        finalizeVoicePendingGrantActionContext(
            resolution: resolution,
            request: request,
            forceCancel: true,
            preserveActiveChallengeOnFailClosed: false
        )
    }

    private func applyVoiceAuthorizationResolution(
        _ resolution: SupervisorVoiceAuthorizationResolution,
        request: SupervisorVoiceAuthorizationRequest?,
        preserveActiveChallengeOnFailClosed: Bool,
        forceCancel: Bool = false
    ) {
        let previousChallengeId = activeVoiceChallenge?.challengeId
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let previousRequestId = activeVoiceAuthorizationRequest?.requestId
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        voiceAuthorizationResolution = resolution
        let preserveMobileConfirmation = shouldPreserveVoiceAuthorizationMobileConfirmationLatch(
            resolution: resolution,
            request: request,
            previousChallengeId: previousChallengeId,
            previousRequestId: previousRequestId
        )

        switch resolution.state {
        case .pending, .escalatedToMobile:
            rememberVoiceAuthorizationRestartContext(request: request)
            if resolution.state == .pending || !preserveMobileConfirmation {
                setVoiceAuthorizationMobileConfirmed(
                    false,
                    source: resolution.state == .pending ? "voice_authorization_pending" : "voice_authorization_escalated",
                    emitSystemMessage: false
                )
            }
            activeVoiceAuthorizationRequest = request
            activeVoiceChallenge = resolution.challenge
        case .verified:
            clearVoiceAuthorizationRestartContext()
            setVoiceAuthorizationMobileConfirmed(
                false,
                source: "voice_authorization_verified",
                emitSystemMessage: false
            )
            activeVoiceAuthorizationRequest = nil
            activeVoiceChallenge = nil
        case .denied:
            rememberVoiceAuthorizationRestartContext(request: request)
            setVoiceAuthorizationMobileConfirmed(
                false,
                source: "voice_authorization_denied",
                emitSystemMessage: false
            )
            activeVoiceAuthorizationRequest = nil
            activeVoiceChallenge = nil
        case .failClosed:
            if forceCancel ||
                HubRouteStateMachine.normalizedReasonToken(resolution.reasonCode) == "user_cancelled" {
                clearVoiceAuthorizationRestartContext()
            } else if request != nil {
                rememberVoiceAuthorizationRestartContext(request: request)
            }
            if forceCancel || !preserveActiveChallengeOnFailClosed || !preserveMobileConfirmation {
                setVoiceAuthorizationMobileConfirmed(
                    false,
                    source: forceCancel ? "voice_authorization_cancelled" : "voice_authorization_fail_closed",
                    emitSystemMessage: false
                )
            }
            if forceCancel || !preserveActiveChallengeOnFailClosed {
                activeVoiceAuthorizationRequest = nil
                activeVoiceChallenge = nil
            } else if let request {
                activeVoiceAuthorizationRequest = request
                activeVoiceChallenge = resolution.challenge ?? activeVoiceChallenge
            }
        }

        let challengeId = resolution.challengeId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let challengeToken = challengeId.isEmpty ? "n/a" : challengeId
        let reasonToken = resolution.reasonCode?.trimmingCharacters(in: .whitespacesAndNewlines)
        let denyToken = resolution.denyCode?.trimmingCharacters(in: .whitespacesAndNewlines)
        let activeChallengeAfterResolution = activeVoiceChallenge?.challengeId
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let preservedChallengeAfterInterrupt = !previousChallengeId.isEmpty
            && activeChallengeAfterResolution == previousChallengeId

        let eventText: String
        let messageText: String
        switch resolution.state {
        case .pending:
            eventText = "voice authorization challenge issued: \(challengeToken)"
            messageText = "语音授权挑战已发起（challenge=\(challengeToken)）"
        case .escalatedToMobile:
            eventText = "voice authorization escalated to mobile: \(challengeToken)"
            messageText = "语音授权已升级到移动端确认（challenge=\(challengeToken)）"
        case .verified:
            eventText = "voice authorization verified: \(challengeToken)"
            messageText = "语音授权已验证通过（challenge=\(challengeToken)）"
        case .denied:
            let deny = denyToken ?? "denied"
            eventText = "voice authorization denied: \(challengeToken) -> \(deny)"
            let reasonText = voiceAuthorizationReasonText(for: resolution)
                ?? annotatedUserVisibleReason(raw: deny, display: nil, fallback: "语音授权未通过")
            messageText = "语音授权被拒绝（challenge=\(challengeToken)）。原因：\(reasonText)。"
        case .failClosed:
            let reason = reasonToken ?? "unknown"
            eventText = "voice authorization fail-closed: \(challengeToken) -> \(reason)"
            if forceCancel, reason == "user_cancelled" {
                messageText = "已取消语音授权挑战（challenge=\(challengeToken)）"
            } else {
                let reasonText = voiceAuthorizationReasonText(for: resolution)
                    ?? annotatedUserVisibleReason(raw: reason, display: nil)
                messageText = "语音授权失败闭锁（challenge=\(challengeToken)）。原因：\(reasonText)。"
            }
        }

        appendVoiceReplayEvent(
            category: .authorization,
            state: replayStateForVoiceAuthorizationResolution(
                resolution: resolution,
                forceCancel: forceCancel
            ),
            summary: replaySummaryForVoiceAuthorizationResolution(
                resolution: resolution,
                challengeToken: challengeToken,
                forceCancel: forceCancel
            ),
            reasonCode: denyToken ?? reasonToken ?? "",
            detail: resolution.nextAction,
            metadata: [
                "challenge_id": challengeId.isEmpty ? previousChallengeId : challengeId,
                "request_id": resolution.requestId,
                "risk_tier": resolution.riskTier,
                "requires_mobile_confirm": resolution.requiresMobileConfirm ? "true" : "false",
                "mobile_confirmed": voiceAuthorizationMobileConfirmationLatched ? "true" : "false",
            ]
        )
        if preservedChallengeAfterInterrupt {
            appendVoiceReplayEvent(
                category: .authorization,
                state: .preserved,
                summary: "待决挑战保持不变",
                reasonCode: reasonToken ?? "",
                metadata: [
                    "challenge_id": previousChallengeId,
                    "request_id": resolution.requestId,
                ]
            )
        }

        appendRecentEvent(eventText)
        addSystemMessage(messageText)
        speakSupervisorVoiceAuthorizationUpdate(
            resolution: resolution,
            challengeToken: challengeToken
        )
    }

    private func rememberVoiceAuthorizationRestartContext(
        request: SupervisorVoiceAuthorizationRequest?
    ) {
        guard let request else { return }
        let pendingGrantAction: SupervisorVoicePendingGrantActionContext? = {
            guard let action = activeVoicePendingGrantAction,
                  action.requestId == request.requestId else {
                return nil
            }
            return action
        }()
        lastVoiceAuthorizationRestartContext = SupervisorVoiceAuthorizationRestartContext(
            request: request,
            pendingGrantAction: pendingGrantAction
        )
    }

    private func clearVoiceAuthorizationRestartContext() {
        lastVoiceAuthorizationRestartContext = nil
    }

    private func restartableVoiceAuthorizationContext() -> SupervisorVoiceAuthorizationRestartContext? {
        guard let context = lastVoiceAuthorizationRestartContext else { return nil }
        guard !context.request.requestId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return nil
        }
        if let pendingGrantAction = context.pendingGrantAction {
            let grantId = pendingGrantAction.grant.grantRequestId
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !grantId.isEmpty,
                  pendingHubGrants.contains(where: { $0.grantRequestId == grantId }) else {
                return nil
            }
        }
        return context
    }

    private func applyVoiceAuthorizationRuntimeSideEffects(
        _ resolution: SupervisorVoiceAuthorizationResolution,
        request: SupervisorVoiceAuthorizationRequest?,
        forceCancel: Bool
    ) async {
        guard !forceCancel else { return }
        guard resolution.state == .verified else { return }
        if await applyVerifiedPendingGrantVoiceAuthorization(request: request) {
            return
        }
        guard isCurrentGuardedOneShotVoiceAuthorization(request) else { return }
        guard let intakeRequest = oneShotIntakeRequest,
              let planDecision = oneShotAdaptivePoolPlan,
              oneShotRunState?.state == .awaitingGrant else {
            return
        }

        let resumedRunState = oneShotRunStateStore.transition(
            to: .launching,
            owner: .supervisor,
            activePools: planDecision.poolPlan.map(\.poolID),
            activeLanes: planDecision.poolPlan.flatMap(\.laneIDs),
            topBlocker: "none",
            nextDirectedTarget: "Supervisor",
            userVisibleSummary: "voice authorization verified; guarded one-shot launch resumed",
            evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
            auditRef: intakeRequest.auditRef
        )
        oneShotRunState = resumedRunState
        appendRecentEvent("guarded one-shot launch resumed after voice authorization")
        addSystemMessage("高风险 one-shot 语音授权已通过，正在接入真实启动链路。")

        let outcome = await executePreparedOneShotLaunch(
            request: intakeRequest,
            planDecision: planDecision
        )
        applyGuardedOneShotLaunchResumeOutcome(
            outcome,
            request: intakeRequest,
            planDecision: planDecision
        )
    }

    private func finalizeVoicePendingGrantActionContext(
        resolution: SupervisorVoiceAuthorizationResolution,
        request: SupervisorVoiceAuthorizationRequest?,
        forceCancel: Bool,
        preserveActiveChallengeOnFailClosed: Bool
    ) {
        guard let context = activeVoicePendingGrantAction else { return }
        let requestId = request?.requestId.trimmingCharacters(in: .whitespacesAndNewlines)
            ?? resolution.requestId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !requestId.isEmpty, context.requestId == requestId else { return }

        switch resolution.state {
        case .pending, .escalatedToMobile:
            return
        case .verified, .denied:
            activeVoicePendingGrantAction = nil
        case .failClosed:
            if forceCancel ||
                !preserveActiveChallengeOnFailClosed ||
                activeVoiceChallenge == nil ||
                activeVoiceAuthorizationRequest == nil {
                activeVoicePendingGrantAction = nil
            }
        }
    }

    private func applyVerifiedPendingGrantVoiceAuthorization(
        request: SupervisorVoiceAuthorizationRequest?
    ) async -> Bool {
        guard let request,
              let context = activeVoicePendingGrantAction,
              context.requestId == request.requestId else {
            return false
        }

        let grant = context.grant
        let grantId = grant.grantRequestId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !grantId.isEmpty else {
            let replyText = "语音授权已验证，但授权单号为空，我没有执行对应的 Hub 授权。"
            let spokenOutcome = speakSupervisorVoiceReply(replyText)
            completeSupervisorAssistantTurn(
                SupervisorAfterTurnLifecycleContext(
                    userMessage: request.actionText,
                    responseText: replyText,
                    triggerSource: .grantResolution,
                    triggeredByVoice: true,
                    spokenOutcome: spokenOutcome,
                    replySource: "pending_grant_missing_id",
                    personaSlot: nil,
                    lifecycle: .nonReviewAssistantReply
                )
            )
            return true
        }

        guard !pendingHubGrantActionsInFlight.contains(grantId) else {
            let replyText = "语音授权已验证，但《\(grant.projectName)》这笔 Hub 授权仍在处理中（授权单号：\(grantId)）。"
            let spokenOutcome = speakSupervisorVoiceReply(replyText)
            completeSupervisorAssistantTurn(
                SupervisorAfterTurnLifecycleContext(
                    userMessage: request.actionText,
                    responseText: replyText,
                    triggerSource: .grantResolution,
                    triggeredByVoice: true,
                    spokenOutcome: spokenOutcome,
                    replySource: "pending_grant_inflight",
                    personaSlot: nil,
                    lifecycle: .nonReviewAssistantReply
                )
            )
            return true
        }

        pendingHubGrantActionsInFlight.insert(grantId)
        let projectId = grant.projectId.trimmingCharacters(in: .whitespacesAndNewlines)
        let result: HubIPCClient.PendingGrantActionResult
        if context.approve {
            let ttlOverride = grant.requestedTtlSec > 0 ? grant.requestedTtlSec : nil
            let tokenOverride = grant.requestedTokenCap > 0 ? grant.requestedTokenCap : nil
            result = await approvePendingHubGrantRequest(
                grantRequestId: grantId,
                projectId: projectId.isEmpty ? nil : projectId,
                requestedTtlSec: ttlOverride,
                requestedTokenCap: tokenOverride,
                note: "x_terminal_supervisor_voice_grant_approve:\(request.requestId)"
            )
        } else {
            result = await denyPendingHubGrantRequest(
                grantRequestId: grantId,
                projectId: projectId.isEmpty ? nil : projectId,
                reason: "voice_authorized_supervisor_denial:\(request.requestId)"
            )
        }

        await completePendingHubGrantAction(
            grantId: grantId,
            grant: grant,
            approve: context.approve,
            result: result
        )

        let followUp = await voicePendingGrantPostActionReply(
            grant: grant,
            approve: context.approve,
            result: result
        )
        completeSupervisorAssistantTurn(
            SupervisorAfterTurnLifecycleContext(
                userMessage: request.actionText,
                responseText: followUp.text,
                triggerSource: .grantResolution,
                triggeredByVoice: true,
                spokenOutcome: followUp.spokenOutcome,
                replySource: "pending_grant_follow_up",
                personaSlot: nil,
                lifecycle: .nonReviewAssistantReply
            )
        )
        return true
    }

    private func executePreparedOneShotLaunch(
        request: SupervisorOneShotIntakeRequest,
        planDecision: AdaptivePoolPlanDecision
    ) async -> GuardedOneShotLaunchResumeOutcome {
        guard let buildResult = oneShotPreparedSplitBuildResult else {
            return .failedClosed(reason: "guarded_one_shot_split_plan_missing")
        }

        if let executor = preparedOneShotLaunchExecutorForTesting {
            return await executor(request, planDecision, buildResult)
        }

        guard let legacyRuntime = appModel?.ensureLegacySupervisorRuntimeContext() else {
            return .failedClosed(reason: "legacy_supervisor_runtime_unavailable")
        }
        let supervisor = legacyRuntime.supervisor
        let orchestrator = legacyRuntime.orchestrator
        _ = await ensureOneShotAnchorProject(
            in: supervisor,
            request: request,
            planDecision: planDecision
        )
        _ = orchestrator.adoptPreparedSplitProposal(
            buildResult,
            auditDetail: "guarded one-shot prepared proposal adopted after voice authorization"
        )

        if buildResult.validation.hasBlockingIssues {
            let reason = buildResult.validation.blockingIssues.first?.code ?? "split_proposal_blocked"
            return .blocked(reason: reason, report: nil)
        }

        guard let promptResult = orchestrator.confirmActiveSplitProposal(globalContext: request.userGoal) else {
            let reason = normalizedOneShotFailureReason(
                orchestrator.splitFlowErrorMessage,
                fallback: "prompt_contract_confirmation_failed"
            )
            return .blocked(reason: reason, report: nil)
        }

        if promptResult.status != .ready || promptResult.lintResult.hasBlockingErrors {
            let lintReason = promptResult.lintResult.blockingIssues.first?.code
            let reason = normalizedOneShotFailureReason(lintReason, fallback: "prompt_contract_blocked")
            return .blocked(reason: reason, report: nil)
        }

        guard let launchReport = await orchestrator.executeActiveSplitProposal() else {
            let reason = normalizedOneShotFailureReason(
                orchestrator.splitFlowErrorMessage,
                fallback: "lane_launch_execution_failed"
            )
            return .blocked(reason: reason, report: nil)
        }

        if !launchReport.launchedLaneIDs.isEmpty {
            return .launched(launchReport)
        }

        let blockedReason = primaryBlockedReason(from: launchReport)
        return .blocked(reason: blockedReason, report: launchReport)
    }

    private func ensureOneShotAnchorProject(
        in runtimeHost: any SupervisorProjectRuntimeHosting,
        request: SupervisorOneShotIntakeRequest,
        planDecision: AdaptivePoolPlanDecision
    ) async -> ProjectModel {
        if let existing = runtimeHost.activeProjects.first(where: { $0.name == "Root" }) {
            existing.taskDescription = request.userGoal
            existing.status = .running
            applyOneShotAnchorExecutionProfile(to: existing, planDecision: planDecision)
            return existing
        }

        if let existing = runtimeHost.activeProjects.first(where: {
            $0.status == .running || $0.status == .pending
        }) {
            existing.taskDescription = request.userGoal
            if existing.status == .pending {
                existing.status = .running
            }
            applyOneShotAnchorExecutionProfile(to: existing, planDecision: planDecision)
            return existing
        }

        let root = ProjectModel(
            name: "Root",
            taskDescription: request.userGoal,
            taskIcon: "point.3.connected.trianglepath.dotted",
            status: .running,
            modelName: oneShotAnchorModelName(for: planDecision),
            executionTier: planDecision.riskSurface >= .high ? .a4OpenClaw : .a3DeliverAuto,
            supervisorInterventionTier: planDecision.riskSurface == .low ? .s2PeriodicReview : .s3StrategicCoach,
            budget: Budget(
                daily: planDecision.riskSurface >= .high ? 40.0 : 20.0,
                monthly: planDecision.riskSurface >= .high ? 1200.0 : 600.0
            )
        )
        applyOneShotAnchorExecutionProfile(to: root, planDecision: planDecision)
        runtimeHost.addActiveProjectIfNeeded(root)
        await runtimeHost.onProjectCreated(root)
        return root
    }

    private func applyOneShotAnchorExecutionProfile(
        to project: ProjectModel,
        planDecision: AdaptivePoolPlanDecision
    ) {
        let capability: ModelCapability
        let executionTier: AXProjectExecutionTier
        let supervisorTier: AXProjectSupervisorInterventionTier
        let modelName: String

        switch planDecision.riskSurface {
        case .critical:
            capability = .expert
            executionTier = .a4OpenClaw
            supervisorTier = .s4TightSupervision
            modelName = "one-shot-anchor-critical"
        case .high:
            capability = .advanced
            executionTier = .a4OpenClaw
            supervisorTier = .s3StrategicCoach
            modelName = "one-shot-anchor-high"
        case .medium:
            capability = .advanced
            executionTier = .a3DeliverAuto
            supervisorTier = .s3StrategicCoach
            modelName = "one-shot-anchor-medium"
        case .low:
            capability = .intermediate
            executionTier = .a3DeliverAuto
            supervisorTier = .s2PeriodicReview
            modelName = "one-shot-anchor-low"
        }

        let governance = AXProjectGovernanceBundle.recommended(
            for: executionTier,
            supervisorInterventionTier: supervisorTier
        )
        project.updateGovernance(
            executionTier: governance.executionTier,
            supervisorInterventionTier: governance.supervisorInterventionTier,
            reviewPolicyMode: governance.reviewPolicyMode,
            progressHeartbeatSeconds: governance.schedule.progressHeartbeatSeconds,
            reviewPulseSeconds: governance.schedule.reviewPulseSeconds,
            brainstormReviewSeconds: governance.schedule.brainstormReviewSeconds,
            eventDrivenReviewEnabled: governance.schedule.eventDrivenReviewEnabled,
            eventReviewTriggers: governance.schedule.eventReviewTriggers
        )
        project.currentModel = ModelInfo(
            id: modelName,
            name: modelName,
            displayName: modelName,
            type: .hubPaid,
            capability: capability,
            speed: capability == .expert ? .slow : .medium,
            costPerMillionTokens: capability == .expert ? 5.0 : 3.0,
            memorySize: nil,
            suitableFor: ["one-shot", "supervisor_anchor"],
            badge: nil,
            badgeColor: nil
        )
    }

    private func oneShotAnchorModelName(for planDecision: AdaptivePoolPlanDecision) -> String {
        switch planDecision.riskSurface {
        case .critical:
            return "one-shot-anchor-critical"
        case .high:
            return "one-shot-anchor-high"
        case .medium:
            return "one-shot-anchor-medium"
        case .low:
            return "one-shot-anchor-low"
        }
    }

    private func applyGuardedOneShotLaunchResumeOutcome(
        _ outcome: GuardedOneShotLaunchResumeOutcome,
        request: SupervisorOneShotIntakeRequest,
        planDecision: AdaptivePoolPlanDecision
    ) {
        switch outcome {
        case .launched(let report):
            let blockedCount = report.blockedLaneReasons.count
            let deferredCount = report.deferredLaneIDs.count
            let summary = "one-shot launch started: launched=\(report.launchedLaneIDs.count), blocked=\(blockedCount), deferred=\(deferredCount)"
            oneShotRunState = oneShotRunStateStore.transition(
                to: .running,
                owner: .supervisor,
                activePools: planDecision.poolPlan.map(\.poolID),
                activeLanes: report.launchedLaneIDs.isEmpty ? planDecision.poolPlan.flatMap(\.laneIDs) : report.launchedLaneIDs,
                topBlocker: "none",
                nextDirectedTarget: "Supervisor",
                userVisibleSummary: summary,
                evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
                auditRef: request.auditRef
            )
            appendRecentEvent(summary)
            addSystemMessage("one-shot 已进入真实执行（launched=\(report.launchedLaneIDs.count)，blocked=\(blockedCount)，deferred=\(deferredCount)）。")

        case .blocked(let reason, let report):
            let blockedCount = report?.blockedLaneReasons.count ?? 0
            let summary = "one-shot launch blocked: \(reason)"
            let reasonText = blockerReasonText(reason)
            oneShotRunState = oneShotRunStateStore.transition(
                to: .blocked,
                owner: .supervisor,
                activePools: planDecision.poolPlan.map(\.poolID),
                activeLanes: planDecision.poolPlan.flatMap(\.laneIDs),
                topBlocker: reason,
                nextDirectedTarget: "Supervisor",
                userVisibleSummary: summary,
                evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
                auditRef: request.auditRef
            )
            appendRecentEvent(summary)
            let blockedSuffix = blockedCount > 0 ? " 当前仍有 \(blockedCount) 条 lane 处于阻塞。" : ""
            addSystemMessage("one-shot 启动仍被阻塞。原因：\(reasonText)。\(blockedSuffix)")

        case .failedClosed(let reason):
            let summary = "failed closed: \(reason)"
            let reasonText = blockerReasonText(reason)
            oneShotRunState = oneShotRunStateStore.transition(
                to: .failedClosed,
                owner: .supervisor,
                activePools: planDecision.poolPlan.map(\.poolID),
                activeLanes: planDecision.poolPlan.flatMap(\.laneIDs),
                topBlocker: reason,
                nextDirectedTarget: "Supervisor",
                userVisibleSummary: summary,
                evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
                auditRef: request.auditRef
            )
            appendRecentEvent("one-shot launch failed closed: \(reason)")
            addSystemMessage("one-shot 启动失败闭锁。原因：\(reasonText)。")
        }
    }

    func speakSupervisorHeartbeatUpdate(
        reason: String,
        changed: Bool,
        projects: [AXProjectEntry],
        blockerProjects: [(projectId: String, blocker: String)],
        blockerSignal: BlockerSignal,
        permissionSignals: [ProjectPermissionSignal],
        recoveryFollowUpSignal: HeartbeatRecoveryFollowUpSignal?,
        governedReviewSignal: HeartbeatGovernedReviewSignal?,
        governanceRepairSignals: [ProjectGovernanceRepairSignal],
        queueSignals: [ProjectQueueSignal],
        progressActions: [HeartbeatAutoProgressAction],
        nextStepSummary: String,
        routeAttentionSignal: HeartbeatRouteAttentionSignal?
    ) {
        let fallbackJob = heartbeatVoiceJob(
            reason: reason,
            changed: changed,
            projects: projects,
            blockerProjects: blockerProjects,
            blockerSignal: blockerSignal,
            permissionSignals: permissionSignals,
            recoveryFollowUpSignal: recoveryFollowUpSignal,
            governedReviewSignal: governedReviewSignal,
            governanceRepairSignals: governanceRepairSignals,
            queueSignals: queueSignals,
            progressActions: progressActions,
            nextStepSummary: nextStepSummary,
            routeAttentionSignal: routeAttentionSignal
        )
        let request = heartbeatProjectionRequest(
            reason: reason,
            changed: changed,
            projects: projects,
            blockerProjects: blockerProjects,
            blockerSignal: blockerSignal,
            permissionSignals: permissionSignals,
            recoveryFollowUpSignal: recoveryFollowUpSignal,
            governedReviewSignal: governedReviewSignal,
            governanceRepairSignals: governanceRepairSignals,
            queueSignals: queueSignals,
            progressActions: progressActions,
            nextStepSummary: nextStepSummary
        )
        let dispatchGeneration = beginHeartbeatVoiceDispatch()

        guard backgroundSupervisorServicesEnabled || supervisorBriefProjectionRequestOverride != nil else {
            guard let fallbackJob else { return }
            _ = dispatchSupervisorVoiceJob(
                fallbackJob,
                preferences: currentVoicePreferences(),
                source: "heartbeat",
                suppressRapidSameSourceRepeat: true,
                cancelPendingHeartbeat: false
            )
            return
        }

        guard let request else {
            guard let fallbackJob else { return }
            _ = dispatchSupervisorVoiceJob(
                fallbackJob,
                preferences: currentVoicePreferences(),
                source: "heartbeat",
                suppressRapidSameSourceRepeat: true,
                cancelPendingHeartbeat: false
            )
            return
        }

        heartbeatVoiceDispatchTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.finishHeartbeatVoiceDispatchIfCurrent(dispatchGeneration) }
            guard !Task.isCancelled,
                  self.isCurrentHeartbeatVoiceDispatch(dispatchGeneration) else {
                return
            }
            if let projectionResolution = await self.heartbeatProjectionVoiceResolution(
                request: request,
                blockerSignal: blockerSignal,
                projects: projects,
                governedReviewSignal: governedReviewSignal
            ) {
                let job: SupervisorVoiceTTSJob
                let detail: String
                switch projectionResolution {
                case .projection(let projectionJob):
                    job = projectionJob
                    detail = "projection"
                case .unavailable(let unavailableJob):
                    job = unavailableJob
                    detail = "projection_unavailable"
                }
                guard !Task.isCancelled,
                      self.isCurrentHeartbeatVoiceDispatch(dispatchGeneration) else {
                    self.appendRecentEvent("stale heartbeat voice projection dropped")
                    self.recordVoiceDispatchActivity(
                        state: "dropped",
                        source: "heartbeat",
                        job: job,
                        reasonCode: "stale_generation",
                        detail: detail
                    )
                    return
                }
                _ = self.dispatchSupervisorVoiceJob(
                    job,
                    preferences: self.currentVoicePreferences(),
                    source: "heartbeat",
                    suppressRapidSameSourceRepeat: true,
                    cancelPendingHeartbeat: false
                )
                return
            }
            guard let fallbackJob else { return }
            guard !Task.isCancelled,
                  self.isCurrentHeartbeatVoiceDispatch(dispatchGeneration) else {
                self.appendRecentEvent("stale heartbeat voice fallback dropped")
                self.recordVoiceDispatchActivity(
                    state: "dropped",
                    source: "heartbeat",
                    job: fallbackJob,
                    reasonCode: "stale_generation",
                    detail: "fallback"
                )
                return
            }
            _ = self.dispatchSupervisorVoiceJob(
                fallbackJob,
                preferences: self.currentVoicePreferences(),
                source: "heartbeat",
                suppressRapidSameSourceRepeat: true,
                cancelPendingHeartbeat: false
            )
        }
    }

    private func supervisorPendingGrantVoiceReplyIfApplicable(
        _ text: String
    ) async -> SupervisorVoicePendingGrantReply? {
        guard activeSupervisorMemoryFactFollowUp() == nil else { return nil }
        guard !looksLikeSupervisorNaturalMemoryPatchFacts(text) else { return nil }
        let projects = allProjects()
        if shouldPreferPendingSupervisorSkillApprovalOverGrantVoiceAction(
            text,
            projects: projects
        ) {
            return nil
        }
        guard let approve = pendingGrantVoiceDecision(in: text) else { return nil }
        if pendingHubGrants.isEmpty {
            await refreshSchedulerSnapshot(force: true)
        }

        let selection = resolvePendingHubGrantForVoiceAction(text, projects: projects)
        if let replyText = selection.reply {
            return SupervisorVoicePendingGrantReply(
                text: replyText,
                spokenOutcome: speakSupervisorVoiceReply(replyText)
            )
        }
        guard let grant = selection.grant else { return nil }
        rememberPendingHubGrantVoiceContext(grant)

        let request = makeVoiceAuthorizationRequestForPendingHubGrantAction(
            grant: grant,
            approve: approve
        )
        if let activeRequest = activeVoiceAuthorizationRequest,
           activeRequest.requestId == request.requestId,
           let existingResolution = voiceAuthorizationResolution,
           activeVoiceChallenge != nil {
            let replyText = renderPendingGrantVoiceAuthorizationReply(
                resolution: existingResolution,
                grant: grant,
                approve: approve,
                challengeAlreadyActive: true
            )
            return SupervisorVoicePendingGrantReply(
                text: replyText,
                spokenOutcome: .spoken
            )
        }

        activeVoicePendingGrantAction = SupervisorVoicePendingGrantActionContext(
            requestId: request.requestId,
            grant: grant,
            approve: approve
        )
        let resolution = await startVoiceAuthorization(request)
        let replyText = renderPendingGrantVoiceAuthorizationReply(
            resolution: resolution,
            grant: grant,
            approve: approve,
            challengeAlreadyActive: false
        )
        return SupervisorVoicePendingGrantReply(
            text: replyText,
            spokenOutcome: .spoken
        )
    }

    private func shouldPreferPendingSupervisorSkillApprovalOverGrantVoiceAction(
        _ text: String,
        projects: [AXProjectEntry]
    ) -> Bool {
        guard pendingSupervisorSkillApprovalDecision(in: text) != nil else { return false }
        let selection = resolvePendingSupervisorSkillApprovalForDirectAction(
            text,
            projects: projects
        )
        return selection.approval != nil || selection.reply != nil
    }

    private func handleActiveVoiceAuthorizationVoiceInputIfApplicable(
        _ text: String
    ) async -> Bool {
        guard activeVoiceChallenge != nil,
              let request = activeVoiceAuthorizationRequest else {
            return false
        }

        if shouldCancelActiveVoiceAuthorization(from: text) {
            cancelVoiceAuthorization()
            let replyText = "已取消当前语音授权。"
            let spokenOutcome = speakSupervisorVoiceReply(replyText)
            completeSupervisorAssistantTurn(
                SupervisorAfterTurnLifecycleContext(
                    userMessage: text,
                    responseText: replyText,
                    triggerSource: .userTurn,
                    triggeredByVoice: true,
                    spokenOutcome: spokenOutcome,
                    replySource: "voice_auth_cancel",
                    personaSlot: nil,
                    lifecycle: .nonReviewAssistantReply
                )
            )
            return true
        }

        if shouldRepeatActiveVoiceAuthorizationPrompt(for: text) {
            let replyText = renderActiveVoiceAuthorizationPrompt(request: request)
            let spokenOutcome = speakSupervisorVoiceReply(replyText)
            completeSupervisorAssistantTurn(
                SupervisorAfterTurnLifecycleContext(
                    userMessage: text,
                    responseText: replyText,
                    triggerSource: .userTurn,
                    triggeredByVoice: true,
                    spokenOutcome: spokenOutcome,
                    replySource: "voice_auth_repeat_prompt",
                    personaSlot: nil,
                    lifecycle: .nonReviewAssistantReply
                )
            )
            return true
        }

        let requiresMobileConfirm = voiceAuthorizationResolution?.requiresMobileConfirm ?? false
        let isPendingGrantVerification = isCurrentPendingGrantVoiceAuthorization(request)
        let mobileConfirmed = inferredMobileConfirmationState(
            from: text,
            requiresMobileConfirm: requiresMobileConfirm
        )
        if mobileConfirmed {
            setVoiceAuthorizationMobileConfirmed(
                true,
                source: "voice_input",
                emitSystemMessage: false
            )
            if isStandaloneMobileConfirmationUtterance(
                text,
                requiresMobileConfirm: requiresMobileConfirm
            ) {
                let replyText = "已记录移动端确认；现在继续说授权短语即可。"
                let spokenOutcome = speakSupervisorVoiceReply(replyText)
                completeSupervisorAssistantTurn(
                    SupervisorAfterTurnLifecycleContext(
                        userMessage: text,
                        responseText: replyText,
                        triggerSource: .userTurn,
                        triggeredByVoice: true,
                        spokenOutcome: spokenOutcome,
                        replySource: "voice_auth_mobile_confirmed",
                        personaSlot: nil,
                        lifecycle: .nonReviewAssistantReply
                    )
                )
                return true
            }
        }
        let semanticMatchScore = inferredVoiceAuthorizationSemanticMatchScore(
            from: text,
            mobileConfirmed: voiceAuthorizationMobileConfirmationLatched
        )
        let resolution = await retryVoiceAuthorizationVerification(
            transcript: text,
            semanticMatchScore: semanticMatchScore
        )

        if isPendingGrantVerification, resolution.state == .verified {
            return true
        }

        if let followUp = await guardedOneShotVoiceAuthorizationFollowUpReply(
            resolution: resolution,
            request: request
        ) {
            completeSupervisorAssistantTurn(
                SupervisorAfterTurnLifecycleContext(
                    userMessage: text,
                    responseText: followUp.text,
                    triggerSource: .userTurn,
                    triggeredByVoice: true,
                    spokenOutcome: followUp.spokenOutcome,
                    replySource: followUp.replySource,
                    personaSlot: nil,
                    lifecycle: .nonReviewAssistantReply
                )
            )
            return true
        }

        let replyText = renderActiveVoiceAuthorizationVerificationReply(
            resolution: resolution,
            request: request
        )
        completeSupervisorAssistantTurn(
            SupervisorAfterTurnLifecycleContext(
                userMessage: text,
                responseText: replyText,
                triggerSource: .userTurn,
                triggeredByVoice: true,
                spokenOutcome: .spoken,
                replySource: "voice_auth_verification_reply",
                personaSlot: nil,
                lifecycle: .nonReviewAssistantReply
            )
        )
        return true
    }

    private func isCurrentPendingGrantVoiceAuthorization(
        _ request: SupervisorVoiceAuthorizationRequest
    ) -> Bool {
        guard let context = activeVoicePendingGrantAction else { return false }
        return context.requestId == request.requestId
    }

    private func resolvePendingHubGrantForVoiceAction(
        _ userMessage: String,
        projects: [AXProjectEntry]
    ) -> (grant: SupervisorPendingGrant?, reply: String?) {
        let commandScope = supervisorCommandProjectScope(
            projects: projects,
            userMessage: userMessage
        )
        let visibleProjectIDs = Set(commandScope.projects.map(\.projectId))
        let grants = pendingHubGrants.filter { visibleProjectIDs.contains($0.projectId) }
        var candidates = grants
        let explicitGrantRequestId = explicitPendingGrantRequestId(in: userMessage)
        if let explicitGrantRequestId {
            let matches = pendingHubGrants.filter { grant in
                let grantId = grant.grantRequestId.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                guard !grantId.isEmpty else { return false }
                return grantId == explicitGrantRequestId.lowercased() ||
                    grantId.contains(explicitGrantRequestId.lowercased()) ||
                    explicitGrantRequestId.lowercased().contains(grantId)
            }
            guard !matches.isEmpty else {
                return (nil, "我没找到授权单号 \(explicitGrantRequestId) 对应的待处理 Hub 授权。")
            }
            candidates = matches
        }

        guard !candidates.isEmpty else {
            if let explicitGrantRequestId {
                return (nil, "我没找到授权单号 \(explicitGrantRequestId) 对应的待处理 Hub 授权。")
            }
            return (nil, XTHubGrantPresentation.emptyPendingReply(projectName: nil))
        }

        let focus = commandScope.selection
        if let focus, focus.source == "explicit_user_mention" {
            let projectMatches = candidates.filter { $0.projectId == focus.project.projectId }
            if !projectMatches.isEmpty {
                candidates = projectMatches
            } else if explicitGrantRequestId == nil {
                return (
                    nil,
                    XTHubGrantPresentation.emptyPendingReply(
                        projectName: focus.project.displayName
                    )
                )
            }
        }

        if candidates.count == 1, let grant = candidates.first {
            return (grant, nil)
        }

        let refined = refinedVoicePendingGrantCandidates(candidates, userMessage: userMessage)
        let ambiguous = refined.isEmpty ? candidates : refined
        if ambiguous.count == 1, let grant = ambiguous.first {
            return (grant, nil)
        }
        if let ordinalGrant = explicitPendingHubGrantOrdinalCandidate(
            candidates: ambiguous,
            userMessage: userMessage
        ) {
            return (ordinalGrant, nil)
        }

        if explicitGrantRequestId == nil,
           focus?.source != "explicit_user_mention",
           let contextualGrant = recentPendingHubGrantVoiceContextCandidate(
               candidates: ambiguous,
               userMessage: userMessage
           ) {
            return (contextualGrant, nil)
        }

        if let focus, focus.source != "explicit_user_mention" {
            let projectMatches = ambiguous.filter { $0.projectId == focus.project.projectId }
            if !projectMatches.isEmpty {
                if projectMatches.count == 1, let grant = projectMatches.first {
                    return (grant, nil)
                }
                candidates = projectMatches
            } else {
                candidates = ambiguous
            }
        } else {
            candidates = ambiguous
        }

        if candidates.count == 1, let grant = candidates.first {
            return (grant, nil)
        }

        return (
            nil,
            renderPendingGrantVoiceAmbiguityReply(
                candidates: candidates,
                focusedProjectName: focus?.source == "explicit_user_mention"
                    ? focus?.project.displayName
                    : nil
            )
        )
    }

    private func recentPendingHubGrantVoiceContextCandidate(
        candidates: [SupervisorPendingGrant],
        userMessage: String
    ) -> SupervisorPendingGrant? {
        let token = lastPendingHubGrantVoiceContextToken.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !token.isEmpty else { return nil }
        guard Date().timeIntervalSince1970 - lastPendingHubGrantVoiceContextAt <= supervisorEllipsisContextCarryWindowSec else {
            return nil
        }

        let normalized = normalizedLookupKey(userMessage)
        guard !normalized.isEmpty else { return nil }
        let hasDemonstrative = normalizedContainsAny(normalized, pendingGrantDemonstrativeTokens())
        let hasSubject = normalizedContainsAny(normalized, pendingGrantSubjectTokens())
        guard hasDemonstrative || hasSubject || hasRecentSupervisorPendingGrantContext(currentUserMessage: userMessage) else {
            return nil
        }

        let matches = candidates.filter { pendingGrantStableToken($0) == token }
        guard matches.count == 1 else { return nil }
        return matches[0]
    }

    private func supervisorBriefProjectionReplyIfApplicable(
        _ text: String,
        fromVoice: Bool
    ) async -> SupervisorBriefProjectionVoiceReply? {
        guard activeSupervisorMemoryFactFollowUp() == nil else { return nil }
        guard !looksLikeSupervisorNaturalMemoryPatchFacts(text) else { return nil }
        let normalized = normalizedLookupKey(text)
        guard !shouldBypassSupervisorBriefRouting(normalized) else { return nil }
        guard shouldUseSupervisorBriefProjectionForStatusQuery(text) else { return nil }
        let projects = allProjects()
        guard let focus = focusedSupervisorCommandProjectSelection(projects: projects, userMessage: text) else {
            return supervisorBriefProjectionUnavailableReply(
                presentation: supervisorBriefProjectionBindingRequiredPresentation(projects: projects),
                fromVoice: fromVoice
            )
        }
        let request = HubIPCClient.SupervisorBriefProjectionRequestPayload(
            requestId: "voice_query_brief_\(Int(Date().timeIntervalSince1970 * 1000))_\(UUID().uuidString.lowercased())",
            projectId: focus.project.projectId,
            runId: nil,
            missionId: nil,
            projectionKind: "progress_brief",
            trigger: supervisorBriefProjectionVoiceQueryTrigger(text),
            includeTtsScript: true,
            includeCardSummary: true,
            maxEvidenceRefs: 4
        )
        let fetcher = supervisorBriefProjectionRequestOverride
            ?? { payload in
                await HubIPCClient.requestSupervisorBriefProjection(payload)
            }
        let result = await fetcher(request)
        guard result.ok, let projection = result.projection else {
            let localSignal = heartbeatGovernanceVoicePresentation()
            return supervisorBriefProjectionUnavailableReply(
                presentation: supervisorBriefProjectionUnavailablePresentation(
                    projectName: focus.project.displayName,
                    reasonCode: result.reasonCode,
                    localSignal: localSignal
                ),
                fromVoice: fromVoice
            )
        }

        let replyText = renderSupervisorBriefProjectionVoiceReply(
            projection,
            projectName: focus.project.displayName
        )
        let script = projectionVoiceScript(from: projection)
        let spokenOutcome: SupervisorSpeechSynthesizer.Outcome
        if !fromVoice {
            spokenOutcome = .suppressed("not_voice_triggered")
        } else if script.isEmpty {
            spokenOutcome = speakSupervisorVoiceReply(replyText)
        } else {
            let job = SupervisorVoiceTTSJob(
                trigger: .userQueryReply,
                priority: .normal,
                script: script,
                dedupeKey: "voice-query:\(projectionVoiceDedupeKey(from: projection))"
            )
            spokenOutcome = dispatchSupervisorVoiceJob(
                job,
                preferences: currentVoicePreferences(),
                source: "brief_projection_voice_reply",
                suppressRapidSameSourceRepeat: false,
                cancelPendingHeartbeat: true
            )
        }
        return SupervisorBriefProjectionVoiceReply(
            text: replyText,
            spokenOutcome: spokenOutcome
        )
    }

    func runSupervisorDoctorPreflight(
        reason: String,
        emitSystemMessage: Bool
    ) -> SupervisorDoctorReport {
        let input = SupervisorDoctorChecker.loadDefaultInputBundle(
            memoryAssemblySnapshot: supervisorMemoryAssemblySnapshot
        )
        let report = SupervisorDoctorChecker.runAndPersist(input: input)
        doctorReport = report
        doctorSuggestionCards = report.suggestions
        doctorHasBlockingFindings = report.summary.blockingCount > 0
        releaseBlockedByDoctorWithoutReport = report.summary.releaseBlockedByDoctorWithoutReport
        doctorReportPath = input.reportURL.path

        if report.ok {
            doctorStatusLine = "Doctor 已通过（\(report.summary.warningCount) 个告警）"
        } else {
            doctorStatusLine = "Doctor 阻断：\(report.summary.blockingCount) 项（\(report.summary.warningCount) 告警）"
        }

        if emitSystemMessage {
            let headline = report.ok ? "✅ Doctor 预检通过" : "⛔️ Doctor 预检阻断"
            let reasonText = blockerReasonText(reason, fallback: "Doctor 预检")
            let body = "\(headline)（触发原因：\(reasonText)）\n\(renderDoctorSummary(report))"
            addSystemMessage(body)
        }
        return report
    }

    func resolveAutomationCommandProject(_ projectRef: String?) throws -> (AXProjectEntry, AXProjectContext) {
        let automationProjects = automationCommandProjects()
        if let rawRef = projectRef?.trimmingCharacters(in: .whitespacesAndNewlines),
           !rawRef.isEmpty {
            let normalizedRef = sanitizeProjectReference(rawRef)
            switch resolveProjectReference(normalizedRef, in: automationProjects) {
            case .matched(let project):
                guard let ctx = projectContext(from: project) else {
                    throw SupervisorAutomationRuntimeError.projectContextMissing(project.projectId)
                }
                return (project, ctx)
            case .notFound:
                throw SupervisorAutomationRuntimeError.projectNotFound(normalizedRef)
            case .ambiguous(let candidates):
                let labels = candidates.map { "\($0.displayName)(\($0.projectId))" }
                throw SupervisorAutomationRuntimeError.projectAmbiguous(normalizedRef, labels)
            }
        }

        if let selectedProjectID = appModel?.selectedProjectId,
           selectedProjectID != AXProjectRegistry.globalHomeId,
           let project = allProjects().first(where: { $0.projectId == selectedProjectID }) {
            guard let ctx = projectContext(from: project) else {
                throw SupervisorAutomationRuntimeError.projectContextMissing(project.projectId)
            }
            return (project, ctx)
        }

        if let snapshotProject = automationSnapshotProject,
           let ctx = projectContext(from: snapshotProject) {
            return (snapshotProject, ctx)
        }

        let projects = allProjects()
        if projects.count == 1, let project = projects.first {
            guard let ctx = projectContext(from: project) else {
                throw SupervisorAutomationRuntimeError.projectContextMissing(project.projectId)
            }
            return (project, ctx)
        }

        throw SupervisorAutomationRuntimeError.projectSelectionMissing
    }

    private func scheduleAutomationRetryIfPossible(
        for project: AXProjectEntry,
        ctx: AXProjectContext,
        decision: XTAutomationRestartRecoveryDecision,
        auditRef: String
    ) -> XTAutomationRetryPackage? {
        guard decision.decision == .resume else { return nil }
        return launchAutomationRetryIfPossible(
            for: project,
            ctx: ctx,
            sourceRunID: decision.runID,
            triggerMode: automationManualRetryTrigger,
            auditRef: auditRef
        )
    }

    private func launchAutomationRetryIfPossible(
        for project: AXProjectEntry,
        ctx: AXProjectContext,
        sourceRunID: String,
        triggerMode: String,
        auditRef: String
    ) -> XTAutomationRetryPackage? {
        guard let materialization = buildAutomationRetryPackage(
            for: project,
            ctx: ctx,
            sourceRunID: sourceRunID,
            triggerMode: triggerMode
        ) else {
            return nil
        }
        let retryPackage = materialization.package

        do {
            let request = try makeRetryAutomationRunRequest(
                for: project,
                ctx: ctx,
                retryPackage: retryPackage,
                triggerMode: triggerMode
            )
            let prepared = try startAutomationRun(
                for: ctx,
                request: request,
                emitSystemMessage: false
            )
            var finalized = retryPackage
            finalized.retryRunID = prepared.launchRef
            finalized.lineage = prepared.lineage
            if let persisted = xtAutomationPersistRetryPackage(finalized, ctx: ctx) {
                finalized = persisted
            }
            automationLatestRetryPackage = finalized
            let retryLineage = automationRetryLineage(for: finalized)
            let scheduledRow: [String: Any] = [
                "type": "automation_retry",
                "status": "scheduled",
                "created_at": Date().timeIntervalSince1970,
                "source_run_id": finalized.sourceRunID,
                "retry_run_id": finalized.retryRunID,
                "lineage_id": retryLineage.lineageID,
                "root_run_id": retryLineage.rootRunID,
                "parent_run_id": retryLineage.parentRunID.isEmpty ? NSNull() : retryLineage.parentRunID,
                "retry_depth": retryLineage.retryDepth,
                "retry_strategy": finalized.retryStrategy,
                "retry_reason": finalized.retryReason,
                "retry_reason_descriptor": finalized.retryReasonDescriptor.map(xtAutomationRetryReasonLogValue) ?? NSNull(),
                "delivery_ref": finalized.deliveryRef?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
                    ? finalized.deliveryRef!
                    : NSNull(),
                "source_handoff_artifact_path": finalized.sourceHandoffArtifactPath,
                "source_blocker": finalized.sourceBlocker.map(xtAutomationBlockerLogValue) ?? NSNull(),
                "source_hold_reason": finalized.sourceHoldReason.isEmpty ? NSNull() : finalized.sourceHoldReason,
                "blocker_code": finalized.sourceBlocker?.code ?? NSNull(),
                "blocker_summary": finalized.sourceBlocker?.summary ?? NSNull(),
                "blocker_stage": finalized.sourceBlocker?.stage.rawValue ?? NSNull(),
                "blocker_next_safe_action": finalized.sourceBlocker?.nextSafeAction ?? NSNull(),
                "blocker_retry_eligible": finalized.sourceBlocker?.retryEligible ?? NSNull(),
                "current_step_id": finalized.sourceBlocker?.currentStepID ?? NSNull(),
                "current_step_title": finalized.sourceBlocker?.currentStepTitle ?? NSNull(),
                "current_step_state": finalized.sourceBlocker?.currentStepState?.rawValue ?? NSNull(),
                "current_step_summary": finalized.sourceBlocker?.currentStepSummary ?? NSNull(),
                "retry_artifact_path": finalized.retryArtifactPath.isEmpty ? NSNull() : finalized.retryArtifactPath,
                "planning_artifact_path": (finalized.planningArtifactPath?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false)
                    ? finalized.planningArtifactPath!
                    : NSNull(),
                "recipe_proposal_artifact_path": (finalized.recipeProposalArtifactPath?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false)
                    ? finalized.recipeProposalArtifactPath!
                    : NSNull(),
                "revised_verification_contract": finalized.revisedVerificationContract.map {
                    XTAutomationVerificationContractSupport.foundationValue($0)
                } ?? NSNull(),
                "additional_evidence_refs": finalized.additionalEvidenceRefs,
                "retry_trigger": normalizedLookupKey(triggerMode),
                "audit_ref": auditRef
            ]
            AXProjectStore.appendRawLog(scheduledRow, for: ctx)
            appendRecentEvent(
                "automation retry scheduled: \(project.displayName) -> \(prepared.launchRef) from \(sourceRunID)",
                project: project
            )
            return finalized
        } catch {
            let retryLineage = automationRetryLineage(for: retryPackage)
            let failedRow: [String: Any] = [
                "type": "automation_retry",
                "status": "failed",
                "created_at": Date().timeIntervalSince1970,
                "source_run_id": retryPackage.sourceRunID,
                "lineage_id": retryLineage.lineageID,
                "root_run_id": retryLineage.rootRunID,
                "parent_run_id": retryLineage.parentRunID.isEmpty ? NSNull() : retryLineage.parentRunID,
                "retry_depth": retryLineage.retryDepth,
                "retry_strategy": retryPackage.retryStrategy,
                "retry_reason": retryPackage.retryReason,
                "retry_reason_descriptor": retryPackage.retryReasonDescriptor.map(xtAutomationRetryReasonLogValue) ?? NSNull(),
                "delivery_ref": retryPackage.deliveryRef?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
                    ? retryPackage.deliveryRef!
                    : NSNull(),
                "source_handoff_artifact_path": retryPackage.sourceHandoffArtifactPath,
                "source_blocker": retryPackage.sourceBlocker.map(xtAutomationBlockerLogValue) ?? NSNull(),
                "source_hold_reason": retryPackage.sourceHoldReason.isEmpty ? NSNull() : retryPackage.sourceHoldReason,
                "blocker_code": retryPackage.sourceBlocker?.code ?? NSNull(),
                "blocker_summary": retryPackage.sourceBlocker?.summary ?? NSNull(),
                "blocker_stage": retryPackage.sourceBlocker?.stage.rawValue ?? NSNull(),
                "blocker_next_safe_action": retryPackage.sourceBlocker?.nextSafeAction ?? NSNull(),
                "blocker_retry_eligible": retryPackage.sourceBlocker?.retryEligible ?? NSNull(),
                "current_step_id": retryPackage.sourceBlocker?.currentStepID ?? NSNull(),
                "current_step_title": retryPackage.sourceBlocker?.currentStepTitle ?? NSNull(),
                "current_step_state": retryPackage.sourceBlocker?.currentStepState?.rawValue ?? NSNull(),
                "current_step_summary": retryPackage.sourceBlocker?.currentStepSummary ?? NSNull(),
                "planning_artifact_path": (retryPackage.planningArtifactPath?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false)
                    ? retryPackage.planningArtifactPath!
                    : NSNull(),
                "recipe_proposal_artifact_path": (retryPackage.recipeProposalArtifactPath?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false)
                    ? retryPackage.recipeProposalArtifactPath!
                    : NSNull(),
                "revised_verification_contract": retryPackage.revisedVerificationContract.map {
                    XTAutomationVerificationContractSupport.foundationValue($0)
                } ?? NSNull(),
                "retry_trigger": normalizedLookupKey(triggerMode),
                "detail": error.localizedDescription,
                "audit_ref": auditRef
            ]
            AXProjectStore.appendRawLog(failedRow, for: ctx)
            appendRecentEvent(
                "automation retry scheduling failed: \(project.displayName) -> \(error.localizedDescription)",
                project: project
            )
            return nil
        }
    }

    private func scheduleAutomaticSelfIterationIfNeeded(
        prepared: XTAutomationPreparedRun,
        report: XTAutomationRunExecutionReport,
        finalCheckpoint: XTAutomationRunCheckpoint,
        project: AXProjectEntry? = nil,
        ctx: AXProjectContext,
        emitSystemMessage: Bool
    ) {
        guard report.finalState == .blocked,
              let config = try? AXProjectStore.loadOrCreateConfig(for: ctx),
              config.automationSelfIterateEnabled else {
            return
        }
        guard automationAutoRetryEligibleHoldReasons.contains(report.holdReason) else {
            logAutomationAutoRetrySkipped(
                sourceRunID: prepared.launchRef,
                holdReason: report.holdReason,
                reason: "hold_reason_not_auto_retryable",
                ctx: ctx,
                lineage: prepared.lineage
            )
            return
        }

        let project = project ?? automationProjectEntry(for: ctx)
        guard let materialization = buildAutomationRetryPackage(
            for: project,
            ctx: ctx,
            sourceRunID: prepared.launchRef,
            triggerMode: automationAutoRetryTrigger
        ) else {
            logAutomationAutoRetrySkipped(
                sourceRunID: prepared.launchRef,
                holdReason: report.holdReason,
                reason: "retry_package_unavailable",
                ctx: ctx,
                lineage: prepared.lineage
            )
            return
        }
        let retryPackage = materialization.package

        let retryDepth = automationRetryDepthValue(from: retryPackage)
        guard retryDepth <= config.automationMaxAutoRetryDepth else {
            logAutomationAutoRetrySkipped(
                sourceRunID: prepared.launchRef,
                holdReason: report.holdReason,
                reason: "auto_retry_budget_exhausted",
                ctx: ctx,
                retryDepth: retryDepth,
                lineage: prepared.lineage
            )
            automationStatusLine = automationStatusLine(
                runID: finalCheckpoint.runID,
                state: finalCheckpoint.state,
                detail: "auto_retry_budget_exhausted"
            )
            return
        }

        let autoRetryAuditRef = "audit-xt-auto-self-iterate-\(xtAutomationActionToken(prepared.launchRef, fallback: "run"))-\(Int(Date().timeIntervalSince1970))"
        automationAutoRetryTask?.cancel()
        automationStatusLine = automationStatusLine(
            runID: finalCheckpoint.runID,
            state: finalCheckpoint.state,
            detail: "auto_retry_scheduled:\(retryDepth)"
        )
        let retryLineage = automationRetryLineage(for: retryPackage)
        let pendingRow: [String: Any] = [
            "type": "automation_retry",
            "status": "pending",
            "created_at": Date().timeIntervalSince1970,
            "source_run_id": prepared.launchRef,
            "lineage_id": retryLineage.lineageID,
            "root_run_id": retryLineage.rootRunID,
            "parent_run_id": retryLineage.parentRunID.isEmpty ? NSNull() : retryLineage.parentRunID,
            "retry_depth": retryDepth,
            "retry_strategy": retryPackage.retryStrategy,
            "retry_reason": retryPackage.retryReason,
            "retry_reason_descriptor": retryPackage.retryReasonDescriptor.map(xtAutomationRetryReasonLogValue) ?? NSNull(),
            "delivery_ref": retryPackage.deliveryRef?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
                ? retryPackage.deliveryRef!
                : NSNull(),
            "retry_trigger": automationAutoRetryTrigger,
            "source_handoff_artifact_path": retryPackage.sourceHandoffArtifactPath,
            "source_blocker": retryPackage.sourceBlocker.map(xtAutomationBlockerLogValue) ?? NSNull(),
            "blocker_code": retryPackage.sourceBlocker?.code ?? NSNull(),
            "blocker_summary": retryPackage.sourceBlocker?.summary ?? NSNull(),
            "blocker_stage": retryPackage.sourceBlocker?.stage.rawValue ?? NSNull(),
            "revised_verification_contract": retryPackage.revisedVerificationContract.map {
                XTAutomationVerificationContractSupport.foundationValue($0)
            } ?? NSNull(),
            "current_step_id": retryPackage.sourceBlocker?.currentStepID ?? NSNull(),
            "current_step_title": retryPackage.sourceBlocker?.currentStepTitle ?? NSNull(),
            "current_step_state": retryPackage.sourceBlocker?.currentStepState?.rawValue ?? NSNull(),
            "current_step_summary": retryPackage.sourceBlocker?.currentStepSummary ?? NSNull(),
            "audit_ref": autoRetryAuditRef
        ]
        AXProjectStore.appendRawLog(pendingRow, for: ctx)
        appendRecentEvent(
            "automation auto retry pending: \(project.displayName) -> \(prepared.launchRef) depth \(retryDepth)",
            project: project
        )

        automationAutoRetryTask = Task { @MainActor [weak self] in
            defer { self?.automationAutoRetryTask = nil }
            guard let self else { return }
            guard !Task.isCancelled else { return }
            await Task.yield()
            guard !Task.isCancelled else { return }
            let launched = self.launchAutomationRetryIfPossible(
                for: project,
                ctx: ctx,
                sourceRunID: prepared.launchRef,
                triggerMode: self.automationAutoRetryTrigger,
                auditRef: autoRetryAuditRef
            )
            guard let launched else { return }
            self.automationStatusLine = self.automationStatusLine(
                runID: launched.retryRunID,
                state: .queued,
                detail: "auto_retry_started:\(retryDepth)"
            )
            if emitSystemMessage && self.projectVisibleInCurrentSupervisorJurisdiction(project) {
                self.addSystemMessage(
                    """
automation 自动迭代已继续
项目: \(project.displayName)
source_run_id: \(prepared.launchRef)
retry_run_id: \(launched.retryRunID)
retry_strategy: \(launched.retryStrategy)
retry_depth: \(retryDepth)
""",
                    project: project,
                    requiresKnownProjectMatch: true
                )
            }
        }
    }

    private func logAutomationAutoRetrySkipped(
        sourceRunID: String,
        holdReason: String,
        reason: String,
        ctx: AXProjectContext,
        retryDepth: Int? = nil,
        lineage: XTAutomationRunLineage? = nil
    ) {
        let resolvedLineage = lineage.map { xtAutomationResolvedLineage($0, fallbackRunID: sourceRunID) }
        let parentRunID = resolvedLineage?.parentRunID.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let suppressedRow: [String: Any] = [
            "type": "automation_retry",
            "status": "suppressed",
            "created_at": Date().timeIntervalSince1970,
            "source_run_id": sourceRunID,
            "lineage_id": resolvedLineage?.lineageID ?? NSNull(),
            "root_run_id": resolvedLineage?.rootRunID ?? NSNull(),
            "parent_run_id": parentRunID.isEmpty ? NSNull() : parentRunID,
            "retry_reason": holdReason,
            "retry_trigger": automationAutoRetryTrigger,
            "delivery_ref": xtAutomationPersistedRunDeliveryRef(for: sourceRunID, ctx: ctx) ?? NSNull(),
            "blocker_code": holdReason.isEmpty ? NSNull() : holdReason,
            "blocker_summary": SupervisorBlockerPresentation.displayText(holdReason) ?? holdReason,
            "detail": reason,
            "retry_depth": retryDepth ?? resolvedLineage?.retryDepth ?? NSNull()
        ]
        AXProjectStore.appendRawLog(suppressedRow, for: ctx)
    }

    func refreshAutomationRuntimeSnapshotForPresentation(
        project: AXProjectEntry,
        ctx: AXProjectContext,
        lastLaunchRef: String
    ) {
        hydrateAutomationRuntimeSnapshot(
            for: project,
            ctx: ctx,
            lastLaunchRef: lastLaunchRef
        )
    }

    private func persistAutomationRecoveryAction(
        decision: XTAutomationRestartRecoveryDecision,
        recoveryMode: XTAutomationRestartRecoveryMode,
        retryPackage: XTAutomationRetryPackage?,
        project: AXProjectEntry,
        ctx: AXProjectContext,
        now: Date = Date()
    ) {
        let resumeMode: XTAutomationRecoveryResumeMode? = {
            guard decision.decision == .resume else { return nil }
            return retryPackage == nil ? .inPlace : .retryPackage
        }()
        let deliveryClosureProjection = automationDeliveryClosureProjection(
            for: project,
            ctx: ctx,
            preferredRunID: firstNonEmpty(
                retryPackage?.retryRunID,
                decision.runID
            ),
            now: now
        )
        let retryRunID = retryPackage?.retryRunID.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let deliveryRef = deliveryClosureProjection?.deliveryRef?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let deliveryClosureParentRunID = deliveryClosureProjection?.lineage.parentRunID
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        AXProjectStore.appendRawLog(
            [
                "type": "automation_run_recovery",
                "schema_version": XTAutomationRestartRecoveryDecision.currentSchemaVersion,
                "created_at": now.timeIntervalSince1970,
                "run_id": decision.runID,
                "recipe_id": decision.recipeID,
                "recovered_state": decision.recoveredState.rawValue,
                "decision": decision.decision.rawValue,
                "hold_reason": decision.holdReason.isEmpty ? NSNull() : decision.holdReason,
                "stable_identity_pass": decision.stableIdentityPass,
                "checkpoint_ref": decision.checkpointRef,
                "resume_token": decision.resumeToken,
                "recovery_mode": recoveryMode.rawValue,
                "resume_mode": resumeMode?.rawValue ?? NSNull(),
                "retry_run_id": retryRunID.isEmpty ? NSNull() : retryRunID,
                "retry_strategy": retryPackage?.retryStrategy ?? NSNull(),
                "retry_reason": retryPackage?.retryReason ?? NSNull(),
                "delivery_ref": deliveryRef.isEmpty ? NSNull() : deliveryRef,
                "delivery_closure_source": deliveryClosureProjection?.source.rawValue ?? NSNull(),
                "delivery_closure_run_id": deliveryClosureProjection?.runID ?? NSNull(),
                "lineage_id": deliveryClosureProjection?.lineage.lineageID ?? NSNull(),
                "root_run_id": deliveryClosureProjection?.lineage.rootRunID ?? NSNull(),
                "parent_run_id": deliveryClosureParentRunID.isEmpty ? NSNull() : deliveryClosureParentRunID,
                "retry_depth": deliveryClosureProjection?.lineage.retryDepth ?? NSNull(),
                "audit_ref": decision.auditRef
            ],
            for: ctx
        )
    }

    private func hydrateAutomationRuntimeSnapshot(
        for project: AXProjectEntry,
        ctx: AXProjectContext,
        lastLaunchRef: String
    ) {
        let previousRecoveryDecision = automationRecoveryDecision
        automationPreparedRun = nil
        automationRecoveryDecision = nil
        clearAutomationPublishedRuntimeSnapshot()
        let normalizedLastLaunchRef = lastLaunchRef.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalizedLastLaunchRef.isEmpty else {
            return
        }

        if let persistedCheckpoint = try? automationRunCoordinator.latestCheckpoint(for: normalizedLastLaunchRef, in: ctx) {
            automationCurrentCheckpoint = persistedCheckpoint
            automationStatusLine = automationStatusLine(
                runID: persistedCheckpoint.runID,
                state: persistedCheckpoint.state,
                detail: persistedCheckpoint.lastTransition
            )
            let effectiveRecoveryDecision: XTAutomationRestartRecoveryDecision? = {
                if let previousRecoveryDecision,
                   previousRecoveryDecision.runID == persistedCheckpoint.runID,
                   XTAutomationRunCheckpointStore.recoverableStates.contains(previousRecoveryDecision.recoveredState),
                   previousRecoveryDecision.decision != .resume {
                    return previousRecoveryDecision
                }

                return try? automationRunCoordinator.recoverRun(
                    normalizedLastLaunchRef,
                    for: ctx,
                    now: Date().timeIntervalSince1970,
                    auditRef: "audit-xt-auto-runtime-snapshot-hydrate"
                )
            }()
            if let effectiveRecoveryDecision,
               XTAutomationRunCheckpointStore.recoverableStates.contains(effectiveRecoveryDecision.recoveredState),
               effectiveRecoveryDecision.decision != .resume {
                automationRecoveryDecision = effectiveRecoveryDecision
                let recoveryDetail = effectiveRecoveryDecision.holdReason.isEmpty
                    ? effectiveRecoveryDecision.decision.rawValue
                    : effectiveRecoveryDecision.holdReason
                automationStatusLine = automationStatusLine(
                    runID: effectiveRecoveryDecision.runID,
                    state: effectiveRecoveryDecision.recoveredState,
                    detail: recoveryDetail
                )
            }
        }
        if let persistedExecution = xtAutomationLoadExecutionReport(for: normalizedLastLaunchRef, ctx: ctx) {
            automationLatestExecutionReport = persistedExecution
            automationStatusLine = automationStatusLine(
                runID: persistedExecution.runID,
                state: persistedExecution.finalState,
                detail: persistedExecution.detail
            )
        }
        if let persistedRetry = xtAutomationLoadRetryPackage(
            forRetryRunID: normalizedLastLaunchRef,
            projectID: project.projectId,
            ctx: ctx
        ) {
            automationLatestRetryPackage = persistedRetry
        } else {
            automationLatestRetryPackage = nil
        }
    }

    private func clearAutomationPublishedRuntimeSnapshot() {
        automationCurrentCheckpoint = nil
        automationLatestExecutionReport = nil
        automationLatestRetryPackage = nil
        automationStatusLine = "自动化执行：空闲"
    }

    private func clearAutomationRuntimeSnapshotForSelection() {
        automationSnapshotProject = nil
        automationPreparedRun = nil
        automationRecoveryDecision = nil
        clearAutomationPublishedRuntimeSnapshot()
    }

    func syncAutomationRuntimeSnapshot(forSelectedProject project: AXProjectEntry?) {
        guard let project,
              let ctx = projectContext(from: project),
              (try? AXProjectStore.loadOrCreateConfig(for: ctx)) != nil else {
            clearAutomationRuntimeSnapshotForSelection()
            return
        }

        automationSnapshotProject = project
        let lastLaunchRef = effectiveAutomationRunRef(for: ctx) ?? ""
        hydrateAutomationRuntimeSnapshot(
            for: project,
            ctx: ctx,
            lastLaunchRef: lastLaunchRef
        )
    }

    func injectXTReadyIncidents(using command: String) async -> String {
        guard let monitor = appModel?.legacySupervisorRuntimeContextIfLoaded?.monitor else {
            return "❌ 未找到兼容执行监控器；请先启动需要多泳道执行的 Supervisor 兼容运行时。"
        }

        let cleared = supervisorIncidentLedger.count
        supervisorIncidentLedger.removeAll()
        xtReadyIncidentEventsAutoExportStatus = "reset_before_inject"

        let specs = parseXTReadyIncidentInjectSpecs(from: command)
        let snapshot = monitor.laneStates
        guard !snapshot.isEmpty else {
            return """
❌ 当前没有可注入的 lane（lane health 为空）。
请先完成提案 confirm 并启动多泳道执行，再运行本命令。
"""
        }

        var applied: [String] = []
        var skipped: [String] = []
        for spec in specs {
            guard let state = snapshot[spec.laneID] else {
                skipped.append("\(spec.laneID):lane_not_found")
                continue
            }
            if state.status.isTerminal {
                skipped.append("\(spec.laneID):lane_terminal")
                continue
            }

            switch spec.incidentCode {
            case LaneBlockedReason.grantPending.rawValue:
                await monitor.updateState(
                    state.taskId,
                    status: .blocked,
                    blockedReason: .grantPending,
                    note: "xt_ready_manual_inject_grant_pending"
                )
                applied.append("\(spec.laneID):grant_pending")
            case LaneBlockedReason.awaitingInstruction.rawValue:
                await monitor.updateState(
                    state.taskId,
                    status: .blocked,
                    blockedReason: .awaitingInstruction,
                    note: "xt_ready_manual_inject_awaiting_instruction"
                )
                applied.append("\(spec.laneID):awaiting_instruction")
            case LaneBlockedReason.runtimeError.rawValue:
                await monitor.updateState(
                    state.taskId,
                    status: .failed,
                    blockedReason: .runtimeError,
                    note: "xt_ready_manual_inject_runtime_error"
                )
                applied.append("\(spec.laneID):runtime_error")
            default:
                skipped.append("\(spec.laneID):unsupported_code=\(spec.incidentCode)")
            }
        }

        _ = exportXTReadyIncidentEventsReport()

        let appliedText = applied.isEmpty ? "（无）" : applied.joined(separator: " | ")
        let skippedText = skipped.isEmpty ? "（无）" : skipped.joined(separator: " | ")
        return """
🧪 XT-Ready incident 注入已执行
ledger_cleared：\(cleared)
applied：\(appliedText)
skipped：\(skippedText)
下一步：
1) /xt-ready incidents status
2) /xt-ready incidents export
"""
    }

}

extension SupervisorManager {
    @discardableResult
    func prepareOneShotControlPlane(submission: OneShotIntakeSubmission) async -> OneShotControlPlaneSnapshot {
        let normalization = oneShotIntakeCoordinator.normalize(submission)
        oneShotNormalizationIssues = normalization.issues
        oneShotIntakeRequest = normalization.request

        let buildResult = await oneShotTaskDecomposer.analyzeAndBuildSplitProposal(
            normalization.request.userGoal,
            rootProjectId: normalization.request.projectUUID,
            planVersion: 1
        )
        oneShotPreparedSplitBuildResult = buildResult
        let planning = oneShotAdaptivePoolPlanner.plan(
            request: normalization.request,
            buildResult: buildResult
        )
        oneShotAdaptivePoolPlan = planning.decision
        oneShotSeatGovernor = planning.seatGovernor
        oneShotPlannerExplain = planning.decision.decisionExplain

        _ = oneShotRunStateStore.bootstrap(
            request: normalization.request,
            planDecision: planning.decision,
            owner: .supervisor,
            evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs()
        )
        _ = oneShotRunStateStore.transition(
            to: .planning,
            owner: .supervisor,
            activePools: planning.decision.poolPlan.map(\ .poolID),
            activeLanes: planning.decision.poolPlan.flatMap(\ .laneIDs),
            topBlocker: "none",
            nextDirectedTarget: "Supervisor",
            userVisibleSummary: "adaptive pool planning completed",
            evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
            auditRef: normalization.request.auditRef
        )

        var finalRunState: OneShotRunStateSnapshot
        if planning.decision.decision == .deny {
            finalRunState = oneShotRunStateStore.transition(
                to: .failedClosed,
                owner: .supervisor,
                activePools: planning.decision.poolPlan.map(\ .poolID),
                activeLanes: planning.decision.poolPlan.flatMap(\ .laneIDs),
                topBlocker: planning.decision.denyCode,
                nextDirectedTarget: "Supervisor",
                userVisibleSummary: "failed closed: \(planning.decision.denyCode)",
                evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
                auditRef: normalization.request.auditRef
            )
        } else if !normalization.request.requiresHumanAuthorizationTypes.isEmpty {
            finalRunState = oneShotRunStateStore.transition(
                to: .awaitingGrant,
                owner: .hubL5,
                activePools: planning.decision.poolPlan.map(\ .poolID),
                activeLanes: planning.decision.poolPlan.flatMap(\ .laneIDs),
                topBlocker: normalization.request.requiresHumanAuthorizationTypes.map(\ .rawValue).joined(separator: ","),
                nextDirectedTarget: "Hub-L5",
                userVisibleSummary: "awaiting grant for guarded one-shot launch",
                evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
                auditRef: normalization.request.auditRef
            )
            _ = await ensureVoiceAuthorizationForGuardedOneShotLaunch(
                request: normalization.request,
                planDecision: planning.decision
            )
        } else {
            let launchingRunState = oneShotRunStateStore.transition(
                to: .launching,
                owner: .supervisor,
                activePools: planning.decision.poolPlan.map(\ .poolID),
                activeLanes: planning.decision.poolPlan.flatMap(\ .laneIDs),
                topBlocker: "none",
                nextDirectedTarget: "Supervisor",
                userVisibleSummary: "one-shot mainline ready to launch",
                evidenceRefs: OneShotControlPlaneSnapshot.defaultEvidenceRefs(),
                auditRef: normalization.request.auditRef
            )
            oneShotRunState = launchingRunState
            let outcome = await executePreparedOneShotLaunch(
                request: normalization.request,
                planDecision: planning.decision
            )
            applyGuardedOneShotLaunchResumeOutcome(
                outcome,
                request: normalization.request,
                planDecision: planning.decision
            )
            finalRunState = oneShotRunState ?? launchingRunState
        }

        oneShotRunState = finalRunState

        return OneShotControlPlaneSnapshot(
            schemaVersion: "xt.one_shot_control_plane_snapshot.v1",
            normalization: normalization,
            planDecision: planning.decision,
            seatGovernor: planning.seatGovernor,
            runState: finalRunState,
            fieldFreeze: .ai1Core
        )
    }

    @discardableResult
    private func ensureVoiceAuthorizationForGuardedOneShotLaunch(
        request: SupervisorOneShotIntakeRequest,
        planDecision: AdaptivePoolPlanDecision
    ) async -> SupervisorVoiceAuthorizationResolution? {
        let voiceRequest = makeVoiceAuthorizationRequestForGuardedOneShotLaunch(
            request: request,
            planDecision: planDecision
        )

        if let activeRequest = activeVoiceAuthorizationRequest,
           activeRequest.requestId == voiceRequest.requestId,
           let existingResolution = voiceAuthorizationResolution {
            switch existingResolution.state {
            case .pending, .escalatedToMobile:
                if activeVoiceChallenge != nil {
                    return existingResolution
                }
            case .verified:
                return existingResolution
            case .denied, .failClosed:
                break
            }
        }

        return await startVoiceAuthorization(voiceRequest)
    }

    func preferredVoiceBoundDeviceId(for projectID: String) -> String? {
        guard let appModel else { return nil }
        let selectedProjectID = appModel.selectedProjectId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !selectedProjectID.isEmpty, selectedProjectID == projectID else { return nil }
        let boundDeviceId = appModel.projectConfig?.trustedAutomationDeviceId
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return boundDeviceId.isEmpty ? nil : boundDeviceId
    }

