    @discardableResult
    func prepareAutomationRun(
        for ctx: AXProjectContext,
        request: XTAutomationRunRequest,
        emitSystemMessage: Bool = false
    ) throws -> XTAutomationPreparedRun {
        let project = automationProjectEntry(for: ctx)
        let projectDisplayName = project.displayName
        let prepared = try automationRunCoordinator.prepareActiveRun(for: ctx, request: request)
        automationPreparedRun = prepared
        clearAutomationPublishedRuntimeSnapshot()
        automationCurrentCheckpoint = prepared.currentCheckpoint
        automationRecoveryDecision = nil
        automationStatusLine = automationStatusLine(
            runID: prepared.launchRef,
            state: prepared.currentCheckpoint.state,
            detail: prepared.verticalSlice.eventRunner.launchDecision.decision.rawValue
        )
        appendRecentEvent(
            "automation prepared: \(projectDisplayName) -> \(prepared.launchRef)",
            project: project
        )
        if emitSystemMessage && projectVisibleInCurrentSupervisorJurisdictionOrUnknown(project) {
            addSystemMessage(
                "automation 已准备：\(projectDisplayName) -> \(prepared.launchRef)",
                project: project,
                requiresKnownProjectMatch: true
            )
        }
        return prepared
    }

    private func scheduleAutomationExecutionIfNeeded(
        prepared: XTAutomationPreparedRun,
        ctx: AXProjectContext,
        emitSystemMessage: Bool
    ) throws {
        let project = automationProjectEntry(for: ctx)
        let projectDisplayName = project.displayName
        guard prepared.currentCheckpoint.state == .queued else { return }

        let config = try AXProjectStore.loadOrCreateConfig(for: ctx)
        let recipe = prepared.executionRecipe
        guard !recipe.actionGraph.isEmpty else {
            return
        }
        if prepared.recipeRef == recipe.ref,
           config.automationRecipes.contains(where: { $0.ref == recipe.ref }) == false {
            return
        }

        automationExecutionTask?.cancel()
        automationAutoRetryTask?.cancel()
        automationAutoRetryTask = nil
        automationStatusLine = automationStatusLine(
            runID: prepared.launchRef,
            state: prepared.currentCheckpoint.state,
            detail: "auto_execution_scheduled"
        )
        appendRecentEvent(
            "automation execution scheduled: \(projectDisplayName) -> \(prepared.launchRef)",
            project: project
        )

        automationExecutionTask = Task { @MainActor [weak self] in
            guard let self else { return }
            await self.executeAutomationActionGraph(
                prepared: prepared,
                recipe: recipe,
                project: project,
                ctx: ctx,
                emitSystemMessage: emitSystemMessage
            )
        }
    }

    private func executeAutomationActionGraph(
        prepared: XTAutomationPreparedRun,
        recipe: AXAutomationRecipeRuntimeBinding,
        project: AXProjectEntry,
        ctx: AXProjectContext,
        emitSystemMessage: Bool
    ) async {
        let projectDisplayName = project.displayName
        defer { automationExecutionTask = nil }
        let startAuditRef = "audit-xt-auto-action-graph-start-\(Int(Date().timeIntervalSince1970))"

        do {
            let firstAction = recipe.actionGraph.first
            let firstActionStepTitle: String? = {
                let title = firstAction?.title.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                if !title.isEmpty {
                    return title
                }
                let actionID = firstAction?.actionID.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                return actionID.isEmpty ? nil : actionID
            }()
            let runningCheckpoint = try automationRunCoordinator.advanceRun(
                prepared.launchRef,
                to: .running,
                currentStepID: firstAction?.actionID,
                currentStepTitle: firstActionStepTitle,
                currentStepState: firstAction == nil ? nil : .inProgress,
                currentStepSummary: firstAction == nil ? nil : "executing_current_action",
                for: ctx,
                auditRef: startAuditRef,
                now: Date()
            )
            automationCurrentCheckpoint = runningCheckpoint
            automationStatusLine = automationStatusLine(
                runID: runningCheckpoint.runID,
                state: runningCheckpoint.state,
                detail: "action_graph_started"
            )
            if handleAutomationSafePointHoldIfNeeded(
                runID: prepared.launchRef,
                requestedState: .running,
                project: project,
                ctx: ctx,
                emitSystemMessage: emitSystemMessage,
                executionDetail: "before executing action graph"
            ) {
                return
            }

            let report = await automationRunExecutor.execute(
                runID: prepared.launchRef,
                recipe: recipe,
                ctx: ctx,
                lineage: prepared.lineage,
                verifyCommandsOverride: prepared.verifyCommandsOverride,
                verificationContractOverride: prepared.verificationContractOverride
            )
            automationLatestExecutionReport = report

            let finalCheckpoint = try automationRunCoordinator.advanceRun(
                prepared.launchRef,
                to: report.finalState,
                retryAfterSeconds: report.finalState == .blocked ? 120 : 0,
                currentStepID: report.currentStepID,
                currentStepTitle: report.currentStepTitle,
                currentStepState: report.currentStepState,
                currentStepSummary: report.currentStepSummary,
                for: ctx,
                auditRef: report.auditRef,
                now: Date()
            )
            automationCurrentCheckpoint = finalCheckpoint
            automationRecoveryDecision = nil
            automationStatusLine = automationStatusLine(
                runID: finalCheckpoint.runID,
                state: finalCheckpoint.state,
                detail: report.detail
            )
            let heldAtSafePoint = handleAutomationSafePointHoldIfNeeded(
                runID: prepared.launchRef,
                requestedState: report.finalState,
                project: project,
                ctx: ctx,
                emitSystemMessage: emitSystemMessage,
                executionDetail: report.detail
            )
            if !heldAtSafePoint {
                appendRecentEvent(
                    "automation executed: \(projectDisplayName) -> \(report.detail)",
                    project: project
                )
                if emitSystemMessage && projectVisibleInCurrentSupervisorJurisdictionOrUnknown(project) {
                    addSystemMessage(
                        renderAutomationExecutionSummary(
                            project: project,
                            report: report
                        ),
                        project: project,
                        requiresKnownProjectMatch: true
                    )
                }
                scheduleAutomaticSelfIterationIfNeeded(
                    prepared: prepared,
                    report: report,
                    finalCheckpoint: finalCheckpoint,
                    project: project,
                    ctx: ctx,
                    emitSystemMessage: emitSystemMessage
                )
            }
        } catch {
            automationStatusLine = "自动化执行：\(prepared.launchRef) -> 失败 (\(error.localizedDescription))"
            appendRecentEvent(
                "automation execution failed: \(projectDisplayName) -> \(error.localizedDescription)",
                project: project
            )
            if emitSystemMessage && projectVisibleInCurrentSupervisorJurisdictionOrUnknown(project) {
                addSystemMessage(
                    "automation 执行失败：\(projectDisplayName) -> \(error.localizedDescription)",
                    project: project,
                    requiresKnownProjectMatch: true
                )
            }
        }
    }

    @discardableResult
    func advanceAutomationRun(
        for project: AXProjectEntry,
        to nextState: XTAutomationRunState,
        runID: String? = nil,
        retryAfterSeconds: Int = 0,
        auditRef: String,
        now: Date = Date(),
        emitSystemMessage: Bool = false
    ) throws -> XTAutomationRunCheckpoint {
        guard let ctx = projectContext(from: project) else {
            throw SupervisorAutomationRuntimeError.projectContextMissing(project.projectId)
        }
        return try advanceAutomationRun(
            for: ctx,
            to: nextState,
            runID: runID,
            retryAfterSeconds: retryAfterSeconds,
            auditRef: auditRef,
            now: now,
            emitSystemMessage: emitSystemMessage
        )
    }

    @discardableResult
    func advanceAutomationRun(
        for ctx: AXProjectContext,
        to nextState: XTAutomationRunState,
        runID: String? = nil,
        retryAfterSeconds: Int = 0,
        auditRef: String,
        now: Date = Date(),
        emitSystemMessage: Bool = false
    ) throws -> XTAutomationRunCheckpoint {
        let project = automationProjectEntry(for: ctx)
        let projectDisplayName = project.displayName
        let resolvedRunID = try resolvedAutomationRunID(runID)
        let checkpoint = try automationRunCoordinator.advanceRun(
            resolvedRunID,
            to: nextState,
            retryAfterSeconds: retryAfterSeconds,
            for: ctx,
            auditRef: auditRef,
            now: now
        )
        automationCurrentCheckpoint = checkpoint
        automationStatusLine = automationStatusLine(
            runID: checkpoint.runID,
            state: checkpoint.state,
            detail: checkpoint.lastTransition
        )
        if handleAutomationSafePointHoldIfNeeded(
            runID: checkpoint.runID,
            requestedState: nextState,
            project: project,
            ctx: ctx,
            emitSystemMessage: emitSystemMessage,
            executionDetail: checkpoint.lastTransition
        ) {
            return checkpoint
        }
        appendRecentEvent(
            "automation advanced: \(projectDisplayName) -> \(checkpoint.state.rawValue)",
            project: project
        )
        if emitSystemMessage && projectVisibleInCurrentSupervisorJurisdictionOrUnknown(project) {
            addSystemMessage(
                "automation 状态更新：\(projectDisplayName) -> \(checkpoint.state.rawValue)",
                project: project,
                requiresKnownProjectMatch: true
            )
        }
        return checkpoint
    }

