    }

    @discardableResult
    func cancelAutomationRun(
        for ctx: AXProjectContext,
        runID: String? = nil,
        auditRef: String,
        now: Date = Date(),
        emitSystemMessage: Bool = false
    ) throws -> XTAutomationRestartRecoveryDecision {
        let project = automationProjectEntry(for: ctx)
        let projectDisplayName = project.displayName
        let resolvedRunID = try resolvedAutomationRunID(runID)
        automationExecutionTask?.cancel()
        automationExecutionTask = nil
        automationAutoRetryTask?.cancel()
        automationAutoRetryTask = nil
        try automationRunCoordinator.cancelRun(
            resolvedRunID,
            for: ctx,
            auditRef: auditRef,
            now: now
        )
        let decision = try automationRunCoordinator.recoverRun(
            resolvedRunID,
            for: ctx,
            now: now.timeIntervalSince1970,
            auditRef: auditRef
        )
        persistAutomationRecoveryAction(
            decision: decision,
            recoveryMode: .automatic,
            retryPackage: nil,
            project: project,
            ctx: ctx,
            now: now
        )
        automationRecoveryDecision = decision
        automationStatusLine = automationStatusLine(
            runID: decision.runID,
            state: decision.recoveredState,
            detail: decision.holdReason
        )
        appendRecentEvent(
            "automation cancelled: \(projectDisplayName) -> \(decision.runID)",
            project: project
        )
        if emitSystemMessage && projectVisibleInCurrentSupervisorJurisdictionOrUnknown(project) {
            addSystemMessage(
                "automation 已取消：\(projectDisplayName) -> \(decision.runID)",
                project: project,
                requiresKnownProjectMatch: true
            )
        }
        return decision
    }

    @discardableResult
    func recoverLatestAutomationRun(
        for project: AXProjectEntry,
        checkpointAgeSeconds: Int,
        recoveryMode: XTAutomationRestartRecoveryMode = .operatorOverride,
        auditRef: String,
        emitSystemMessage: Bool = false
    ) throws -> XTAutomationRestartRecoveryDecision? {
        guard let ctx = projectContext(from: project) else {
            throw SupervisorAutomationRuntimeError.projectContextMissing(project.projectId)
        }
        return try recoverLatestAutomationRun(
            for: project,
            ctx: ctx,
            checkpointAgeSeconds: checkpointAgeSeconds,
            recoveryMode: recoveryMode,
            auditRef: auditRef,
            emitSystemMessage: emitSystemMessage
        )
    }

    @discardableResult
    func recoverLatestAutomationRun(
        for ctx: AXProjectContext,
        checkpointAgeSeconds: Int,
        recoveryMode: XTAutomationRestartRecoveryMode = .operatorOverride,
        auditRef: String,
        emitSystemMessage: Bool = false
    ) throws -> XTAutomationRestartRecoveryDecision? {
        let project = automationProjectEntry(for: ctx)
        return try recoverLatestAutomationRun(
            for: project,
            ctx: ctx,
            checkpointAgeSeconds: checkpointAgeSeconds,
            recoveryMode: recoveryMode,
            auditRef: auditRef,
            emitSystemMessage: emitSystemMessage
        )
    }

    @discardableResult
    private func recoverLatestAutomationRun(
        for project: AXProjectEntry,
        ctx: AXProjectContext,
        checkpointAgeSeconds: Int,
        recoveryMode: XTAutomationRestartRecoveryMode,
        auditRef: String,
        emitSystemMessage: Bool
    ) throws -> XTAutomationRestartRecoveryDecision? {
        let decision = try automationRunCoordinator.recoverLatestRun(
            for: ctx,
            checkpointAgeSeconds: checkpointAgeSeconds,
            recoveryMode: recoveryMode,
            auditRef: auditRef
        )
        return try applyRecoveredAutomationDecision(
            decision,
            project: project,
            ctx: ctx,
            recoveryMode: recoveryMode,
            auditRef: auditRef,
            emitSystemMessage: emitSystemMessage
        )
    }

    @discardableResult
    func recoverLatestAutomationRun(
        for project: AXProjectEntry,
        ctx: AXProjectContext,
        now: TimeInterval,
        recoveryMode: XTAutomationRestartRecoveryMode,
        auditRef: String,
        emitSystemMessage: Bool
    ) throws -> XTAutomationRestartRecoveryDecision? {
        let decision = try automationRunCoordinator.recoverLatestRun(
            for: ctx,
            now: now,
            recoveryMode: recoveryMode,
            auditRef: auditRef
        )
        return try applyRecoveredAutomationDecision(
            decision,
            project: project,
            ctx: ctx,
            recoveryMode: recoveryMode,
            auditRef: auditRef,
            emitSystemMessage: emitSystemMessage
        )
    }

    @discardableResult
    private func applyRecoveredAutomationDecision(
        _ decision: XTAutomationRestartRecoveryDecision?,
        project: AXProjectEntry,
        ctx: AXProjectContext,
        recoveryMode: XTAutomationRestartRecoveryMode,
        auditRef: String,
        emitSystemMessage: Bool
    ) throws -> XTAutomationRestartRecoveryDecision? {
        automationRecoveryDecision = decision
        automationLatestRetryPackage = nil
        guard let decision else { return nil }

        let checkpoint = try automationRunCoordinator.latestCheckpoint(for: decision.runID, in: ctx)
        automationCurrentCheckpoint = checkpoint
        let retryPackage = scheduleAutomationRetryIfPossible(
            for: project,
            ctx: ctx,
            decision: decision,
            auditRef: auditRef
        )
        persistAutomationRecoveryAction(
            decision: decision,
            recoveryMode: recoveryMode,
            retryPackage: retryPackage,
            project: project,
            ctx: ctx
        )
        if retryPackage == nil {
            let statusDetail = decision.holdReason.isEmpty ? decision.decision.rawValue : decision.holdReason
            automationStatusLine = automationStatusLine(
                runID: decision.runID,
                state: decision.recoveredState,
                detail: statusDetail
            )
        }
        appendRecentEvent(
            "automation recovered: \(project.displayName) -> \(decision.runID)",
            project: project
        )
        if emitSystemMessage && projectVisibleInCurrentSupervisorJurisdictionOrUnknown(project) {
            addSystemMessage(
                "automation 已恢复判定：\(project.displayName) -> \(decision.decision.rawValue)",
                project: project,
                requiresKnownProjectMatch: true
            )
        }
        return decision
    }

}
